-- ---- O_Tcontrols_ControlEngine
O_Tcontrols_ControlEngine = lua_class("Tcontrols_ControlEngine", nil, {Cpp_ICopy})
function O_Tcontrols_ControlEngine._new() return L_setmetatable({last_action_count_ = 0, total_premises_ = 0, control_value_ = 0.0, set_point_ = 0.0, eval_date_ = 0.0, cur_date_ = 0.0, cur_time_ = 0.0, elapsed_days_ = 0.0}, O_Tcontrols_ControlEngine) end
function O_Tcontrols_ControlEngine.evaluate(self, ctx, current_date, dt, rule_time_reached)
  local t_1, t_2
  if not rule_time_reached then
    self.last_action_count_ = 0
    do return 0 end
  end
  self.eval_date_ = current_date
  self.cur_date_ = L_floor(current_date)
  self.cur_time_ = current_date - self.cur_date_
  self.elapsed_days_ = current_date - ctx.options.start_date
  local current_time = current_date
  local dt_days = dt / S_F_constants_SEC_PER_DAY
  local half_step = dt_days / 2.0
  self.pending_actions_:clear()
  do
    local v___r1 = self.premise_groups_
    do
      local v___i2_n = v___r1.n
      for v___i2 = 0, v___i2_n - 1 do
        local g = v___r1.a[v___i2]
        O_Tcontrols_ControlEngine.batchEvaluateGroup(self, g, ctx, current_time, half_step)
      end
    end
  end
  do
    local r = 0
    while L_ult(r, self.rules_.n) do
      do
        local rule = self.rules_.a[r]
        local base = self.rule_premise_offset_.a[r]
        do
          local p = 0
          while L_ult(p, rule.premises.n) do
            do
              local prem = rule.premises.a[p]
              if (not prem.is_expression) and (not prem.rhs_is_variable) then
                goto cont3
              end
              local ok = O_Tcontrols_ControlEngine.evaluatePremise(self, ctx, prem, current_time, half_step)
              self.premise_results_.a[base + p] = (ok and 1 or 0) & 0xFF
            end
            ::cont3::
            p = p + 1
          end
        end
      end
      r = r + 1
    end
  end
  self.rule_results_:assign_ul_T(self.rules_.n, false)
  do
    local r_2 = 0
    while L_ult(r_2, self.rules_.n) do
      do
        local rule_2 = self.rules_.a[r_2]
        local base_2 = self.rule_premise_offset_.a[r_2]
        local result = false
        do
          local p_2 = 0
          while L_ult(p_2, rule_2.premises.n) do
            do
              local pval = self.premise_results_.a[base_2 + p_2]
              local logic = rule_2.premises.a[p_2].logic
              if p_2 == 0 then
                result = pval ~= 0
              elseif logic == 0 then
                if not result then
                  break
                end
                result = pval ~= 0
              elseif not result then
                result = pval ~= 0
              end
            end
            p_2 = p_2 + 1
          end
        end
        self.rule_results_.a[r_2] = result
      end
      r_2 = r_2 + 1
