-- ---- O_Tiface_InterfaceManager
O_Tiface_InterfaceManager = lua_class("Tiface_InterfaceManager", nil, {Cpp_ICopy})
function O_Tiface_InterfaceManager._new() return L_setmetatable({old_time_ = 0.0, new_time_ = 0.0, n_iface_polluts_ = 0, n_values_per_node_ = 0, iface_flow_units_ = 0, iface_step_ = 0, iface_frac_ = 0.0}, O_Tiface_InterfaceManager) end
function O_Tiface_InterfaceManager.init(self, p)
  O_Tiface_InterfaceManager.closeFiles(self)
  self.data_.count_f = 0
  self.infile_ = nil
  self.outfile_ = nil
  self.old_time_ = 0.0
  self.new_time_ = 0.0
  self.n_iface_polluts_ = 0
  self.n_values_per_node_ = 1
  self.iface_frac_ = 0.0
  self.pollut_map_:clear()
end
function O_Tiface_InterfaceManager.openFiles(self, infile_path, outfile_path)
  if (not (infile_path.n == 0)) and (not (outfile_path.n == 0)) then
    if infile_path:Equals_Str(outfile_path) then
      do return -1 end
    end
  end
  if not (outfile_path.n == 0) then
    self.outfile_ = F_io_fopen_utf8(outfile_path, R_Lit("wt"))
    if not (self.outfile_ ~= nil) then
      do return -2 end
    end
  end
  if not (infile_path.n == 0) then
    self.infile_ = F_io_fopen_utf8(infile_path, R_Lit("rt"))
    if not (self.infile_ ~= nil) then
      do return -3 end
    end
  end
  do return 0 end
end
function O_Tiface_InterfaceManager.readFileHeader(self, ctx)
  if not (self.infile_ ~= nil) then
    do return -1 end
  end
  local line = R_Buf_i(1025)
  local s1 = R_Buf_i(1025)
  local s2 = R_Buf_i(1025)
  if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
    do return -1 end
  end
  if R_sscanf(line, R_Lit("%s"), s1) ~= 1 then
    do return -1 end
  end
  if R_strncmp(s1, R_Lit("SWMM5"), 5) ~= 0 then
    do return -1 end
  end
  if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
    do return -1 end
  end
  if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
    do return -1 end
  end
  if (R_sscanf(line, R_Lit("%d"), R_RefI(function(v___sv)
  self.iface_step_ = v___sv
  do return end
end)) ~= 1) or (self.iface_step_ <= 0) then
    do return -1 end
  end
  local n_constit = 0
  if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
    do return -1 end
  end
  if R_sscanf(line, R_Lit("%d"), R_RefI(function(v___sv_2)
  n_constit = v___sv_2
  do return end
end)) ~= 1 then
    do return -1 end
  end
  self.n_iface_polluts_ = (((n_constit - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  if self.n_iface_polluts_ < 0 then
    do return -1 end
  end
  self.n_values_per_node_ = (((1 + self.n_iface_polluts_) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
    do return -1 end
  end
  if R_sscanf(line, R_Lit("%s %s"), s1, s2) < 2 then
    do return -1 end
  end
  if R_strncmp(s1, R_Lit("FLOW"), 4) ~= 0 then
    do return -1 end
  end
  if not S_Tiface_InterfaceManager_S_flow_words_15_done then
    S_Tiface_InterfaceManager_S_flow_words_15 = {[0] = R_Lit("CFS"), R_Lit("GPM"), R_Lit("MGD"), R_Lit("CMS"), R_Lit("LPS"), R_Lit("MLD"), n = 6}
    S_Tiface_InterfaceManager_S_flow_words_15_done = true
  end
  self.iface_flow_units_ = 0
  do
    local fi = 0
    while fi < 6 do
      do
        if R_strncmp(s2, S_Tiface_InterfaceManager_S_flow_words_15[fi], 3) == 0 then
          self.iface_flow_units_ = fi
          break
        end
      end
      fi = fi + 1
    end
  end
  local n_polluts = ((ctx.pollutant_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  if n_polluts > 0 then
    self.pollut_map_:assign_ul_T(n_polluts, -1)
  end
  do
    local i = 0
    while i < self.n_iface_polluts_ do
      do
        if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
          do return -1 end
        end
        if R_sscanf(line, R_Lit("%s %s"), s1, s2) < 2 then
          do return -1 end
        end
        local j = O_NameIndex.find(ctx.pollutant_names, NewStr_CPtr(s1))
        if (j >= 0) and (j < n_polluts) then
          self.pollut_map_.a[j] = i
        end
      end
      i = i + 1
    end
  end
  local n_nodes = 0
  if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
    do return -1 end
  end
  if (R_sscanf(line, R_Lit("%d"), R_RefI(function(v___sv_3)
  n_nodes = v___sv_3
  do return end
end)) ~= 1) or (n_nodes <= 0) then
    do return -1 end
  end
  O_Tiface_InterfaceFileSoA.resize(self.data_, n_nodes)
  local un = n_nodes
  local total_values = un * self.n_values_per_node_
  self.data_.old_values:assign_ul_T(total_values, 0.0)
  self.data_.new_values:assign_ul_T(total_values, 0.0)
  do
    local i_2 = 0
    while i_2 < n_nodes do
      do
        if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
          do return -1 end
        end
        local name = R_Buf_i(1025)
        if R_sscanf(line, R_Lit("%s"), name) ~= 1 then
          do return -1 end
        end
        self.data_.node_idx.a[i_2] = O_NameIndex.find(ctx.node_names, NewStr_CPtr(name))
      end
      i_2 = i_2 + 1
    end
  end
  if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
    do return -1 end
  end
  O_Tiface_InterfaceManager.readNextPeriod(self)
  self.old_time_ = self.new_time_
  do return 0 end
end
function O_Tiface_InterfaceManager.writeFileHeader(self, ctx)
  if not (self.outfile_ ~= nil) then
    do return end
  end
  R_fprintf(self.outfile_, R_Lit("SWMM5 Interface File"))
  R_fprintf(self.outfile_, R_Lit("\n%s"), R_Lit("OpenSWMM Engine Output"))
  local report_step = L_f2i32(ctx.options.report_step)
  R_fprintf(self.outfile_, R_Lit("\n%-4d - reporting time step in sec"), report_step)
  local n_polluts = ((ctx.pollutant_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  R_fprintf(self.outfile_, R_Lit("\n%-4d - number of constituents as listed below:"), (((n_polluts + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)
  if not S_Tiface_InterfaceManager_S_flow_words_16_done then
    S_Tiface_InterfaceManager_S_flow_words_16 = {[0] = R_Lit("CFS"), R_Lit("GPM"), R_Lit("MGD"), R_Lit("CMS"), R_Lit("LPS"), R_Lit("MLD"), n = 6}
    S_Tiface_InterfaceManager_S_flow_words_16_done = true
  end
  local fu = ctx.options.flow_units
  if (fu < 0) or (fu > 5) then
    fu = 0
  end
  R_fprintf(self.outfile_, R_Lit("\nFLOW %s"), S_Tiface_InterfaceManager_S_flow_words_16[fu])
  do
    local i = 0
    while i < n_polluts do
      do
        local pname = ctx.pollutant_names.names_.a[i]
        R_fprintf(self.outfile_, R_Lit("\n%s MG/L"), pname:c_str())
      end
      i = i + 1
    end
  end
  local n_outlets = 0
  do
    local i_2 = 0
    while i_2 < (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        if Tiface_InterfaceManager_isOutletNode(ctx, i_2) then
          n_outlets = (((n_outlets + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        end
      end
      i_2 = i_2 + 1
    end
  end
  R_fprintf(self.outfile_, R_Lit("\n%-4d - number of nodes as listed below:"), n_outlets)
  do
    local i_3 = 0
    while i_3 < (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        if not Tiface_InterfaceManager_isOutletNode(ctx, i_3) then
          goto cont3
        end
        local nname = ctx.node_names.names_.a[i_3]
        R_fprintf(self.outfile_, R_Lit("\n%s"), nname:c_str())
      end
      ::cont3::
      i_3 = i_3 + 1
    end
  end
  R_fprintf(self.outfile_, R_Lit("\nNode             Year Mon Day Hr  Min Sec FLOW      "))
  do
    local i_4 = 0
    while i_4 < n_polluts do
      do
        local pname_2 = ctx.pollutant_names.names_.a[i_4]
        R_fprintf(self.outfile_, R_Lit(" %-10s"), pname_2:c_str())
      end
      i_4 = i_4 + 1
    end
  end
end
function O_Tiface_InterfaceManager.readInflows(self, ctx, current_time)
  local t_1, t_2
  if not (self.infile_ ~= nil) then
    do return end
  end
  if self.data_.old_values.n == 0 then
    if O_Tiface_InterfaceManager.readFileHeader(self, ctx) ~= 0 then
      O_Tiface_InterfaceManager.closeFiles(self)
      do return end
    end
  end
  if self.data_.count_f == 0 then
    do return end
  end
  if self.old_time_ > current_time then
    do return end
  end
  while (self.new_time_ < current_time) and (self.new_time_ ~= S_F_iface_NO_DATE_InterfaceFile) do
    O_Tiface_InterfaceManager.setOldValues(self)
    O_Tiface_InterfaceManager.readNextPeriod(self)
  end
  if self.new_time_ == S_F_iface_NO_DATE_InterfaceFile then
    do return end
  end
  local dt_iface = self.new_time_ - self.old_time_
  if dt_iface > 0.0 then
    self.iface_frac_ = (current_time - self.old_time_) / dt_iface
    t_1 = (self.iface_frac_ < 1.0) and self.iface_frac_ or 1.0
    self.iface_frac_ = (0.0 < t_1) and t_1 or 0.0
  else
    self.iface_frac_ = 0.0
  end
  do
    local i = 0
    while i < self.data_.count_f do
      do
        local node = self.data_.node_idx.a[i]
        if (node < 0) or (node >= (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
          goto cont2
        end
        local flow = O_Tiface_InterfaceManager.getFlow(self, i, self.iface_frac_)
        if L_abs(flow) < S_F_constants_FLOW_TOL then
          goto cont2
        end
        ctx.nodes.iface_inflow.a[node] = ctx.nodes.iface_inflow.a[node] + flow
        local n_polluts = ((ctx.pollutant_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        if (((flow > 0.0) and (n_polluts > 0)) and (not (self.pollut_map_.n == 0))) and (not (ctx.nodes.iface_qual_mass.n == 0)) then
          local base_q = node * n_polluts
          do
            local p = 0
            while p < n_polluts do
              do
                local qual = O_Tiface_InterfaceManager.getQuality(self, i, p, self.iface_frac_)
                if qual > 0.0 then
                  t_1 = ctx.nodes.iface_qual_mass.a
                  t_2 = base_q + p
                  t_1[t_2] = t_1[t_2] + (flow * qual)
                end
              end
              p = p + 1
            end
          end
        end
      end
      ::cont2::
      i = i + 1
    end
  end
end
function O_Tiface_InterfaceManager.writeOutfallResults(self, ctx, current_time)
  if not (self.outfile_ ~= nil) then
    do return end
  end
  local yr = {0}
  local mon = {0}
  local day = {0}
  local hr = {0}
  local mn = {0}
  local sec = {0}
  F_datetime_decodeDate(current_time, yr, 1, mon, 1, day, 1)
  F_datetime_decodeTime(current_time, hr, 1, mn, 1, sec, 1)
  do
    local i = 0
    while i < (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local ui = i
        if not Tiface_InterfaceManager_isOutletNode(ctx, i) then
          goto cont1
        end
        local name = ctx.node_names.names_.a[ui]
        R_fprintf(self.outfile_, R_Lit("\n%-16s"), name:c_str())
        R_fprintf(self.outfile_, R_Lit(" %04d %02d  %02d  %02d  %02d  %02d "), yr[1], mon[1], day[1], hr[1], mn[1], sec[1])
        local fu = ctx.options.flow_units
        if (fu < 0) or (fu > 5) then
          fu = 0
        end
        R_fprintf(self.outfile_, R_Lit(" %-10f"), ctx.nodes.inflow.a[ui] * S_F_ucf_Qcf_UnitConversion[fu])
        local np = ((ctx.pollutant_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        do
          local p = 0
          while p < np do
            do
              local qi = (ui * np) + p
              local conc = L_ult(qi, ctx.nodes.conc.n) and ctx.nodes.conc.a[qi] or 0.0
              R_fprintf(self.outfile_, R_Lit(" %-10f"), conc)
            end
            p = p + 1
          end
        end
      end
      ::cont1::
      i = i + 1
    end
  end
end
function O_Tiface_InterfaceManager.closeFiles(self)
  if self.infile_ ~= nil then
    R_fclose(self.infile_)
    self.infile_ = nil
  end
  if self.outfile_ ~= nil then
    R_fclose(self.outfile_)
    self.outfile_ = nil
  end
end
function O_Tiface_InterfaceManager.getFlow(self, index, frac)
  if (index < 0) or (index >= self.data_.count_f) then
    do return 0.0 end
  end
  local base = index * self.n_values_per_node_
  local q1 = self.data_.old_values.a[base]
  local q2 = self.data_.new_values.a[base]
  do return ((1.0 - frac) * q1) + (frac * q2) end
end
function O_Tiface_InterfaceManager.getQuality(self, index, pollut_idx, frac)
  if (index < 0) or (index >= self.data_.count_f) then
    do return 0.0 end
  end
  if (pollut_idx < 0) or (pollut_idx >= (((self.pollut_map_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
    do return 0.0 end
  end
  local col = self.pollut_map_.a[pollut_idx]
  if col < 0 then
    do return 0.0 end
  end
  local base = index * self.n_values_per_node_
  local offset = base + ((((col + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)
  local c1 = self.data_.old_values.a[offset]
  local c2 = self.data_.new_values.a[offset]
  do return ((1.0 - frac) * c1) + (frac * c2) end
end
function O_Tiface_InterfaceManager.readNextPeriod(self)
  if not (self.infile_ ~= nil) then
    do return false end
  end
  local line = R_Buf_i(1025)
  self.new_time_ = S_F_iface_NO_DATE_InterfaceFile
  do
    local i = 0
    while i < self.data_.count_f do
      do
        local ui = i
        if R_feof(self.infile_) ~= 0 then
          do return false end
        end
        if not (not R_fgets(line, S_F_iface_MAXLINE_InterfaceFile, self.infile_):get_IsNull()) then
          do return false end
        end
        local strtok_ctx = CPtr_ZERO
        local tok = R_strtok(line, R_Lit(" \t\n\r"))
        if not (not tok:get_IsNull()) then
          do return false end
        end
        local yr = 0
        local mon = 0
        local day = 0
        local hr = 0
        local mn = 0
        local sec = 0
        tok = R_strtok(CPtr_ZERO, R_Lit(" \t\n\r"))
        if not (not tok:get_IsNull()) then
          do return false end
        end
        yr = R_atoi(tok)
        tok = R_strtok(CPtr_ZERO, R_Lit(" \t\n\r"))
        if not (not tok:get_IsNull()) then
          do return false end
        end
        mon = R_atoi(tok)
        tok = R_strtok(CPtr_ZERO, R_Lit(" \t\n\r"))
        if not (not tok:get_IsNull()) then
          do return false end
        end
        day = R_atoi(tok)
        tok = R_strtok(CPtr_ZERO, R_Lit(" \t\n\r"))
        if not (not tok:get_IsNull()) then
          do return false end
        end
        hr = R_atoi(tok)
        tok = R_strtok(CPtr_ZERO, R_Lit(" \t\n\r"))
        if not (not tok:get_IsNull()) then
          do return false end
        end
        mn = R_atoi(tok)
        tok = R_strtok(CPtr_ZERO, R_Lit(" \t\n\r"))
        if not (not tok:get_IsNull()) then
          do return false end
        end
        sec = R_atoi(tok)
        tok = R_strtok(CPtr_ZERO, R_Lit(" \t\n\r"))
        if not (not tok:get_IsNull()) then
          do return false end
        end
        local base = ui * self.n_values_per_node_
        self.data_.new_values.a[base] = R_atof(tok)
        if (self.iface_flow_units_ >= 0) and (self.iface_flow_units_ <= 5) then
          self.data_.new_values.a[base] = self.data_.new_values.a[base] / S_F_ucf_Qcf_UnitConversion[self.iface_flow_units_]
        end
        do
          local j = 1
          while j <= self.n_iface_polluts_ do
            do
              tok = R_strtok(CPtr_ZERO, R_Lit(" \t\n\r"))
              if not (not tok:get_IsNull()) then
                do return false end
              end
              self.data_.new_values.a[base + j] = R_atof(tok)
            end
            j = j + 1
          end
        end
        self.new_time_ = F_datetime_encodeDate(yr, mon, day) + F_datetime_encodeTime(hr, mn, sec)
      end
      i = i + 1
    end
  end
  do return true end
end
function O_Tiface_InterfaceManager.setOldValues(self)
  self.old_time_ = self.new_time_
  local total = self.data_.count_f * self.n_values_per_node_
  do
    local i = 0
    while L_ult(i, total) do
      do
        self.data_.old_values.a[i] = self.data_.new_values.a[i]
      end
      i = i + 1
    end
  end
end
function O_Tiface_InterfaceManager.u__init_rInterfaceManager(self, p)
  O_Tiface_InterfaceManager.u__CopyFrom_InterfaceManager(self, p)
end
function O_Tiface_InterfaceManager.u__init_mInterfaceManager(self, p)
  O_Tiface_InterfaceManager.MoveFrom(self, p)
end
function O_Tiface_InterfaceManager.u__init_d(self)
  self.data_ = Tiface_InterfaceFileSoA__new()
  self.infile_ = nil
  self.outfile_ = nil
  self.old_time_ = 0.0
  self.new_time_ = 0.0
  self.n_iface_polluts_ = 0
  self.n_values_per_node_ = 1
