function O_SWMMEngine.writeHotstartSave(self, entry)
  local t_1
  if not (entry.path.absolute.n == 0) then
    t_1 = entry.path.absolute
  else
    t_1 = entry.path.original
  end
  local sp = t_1
  if sp.n == 0 then
    do return end
  end
  local lid_restart = Algo_any_of(self.ctx_.node_subtypes.storages.lid:begin(), self.ctx_.node_subtypes.storages.lid:end_(), function(c) return c.control >= 0 end)
  local full_continuation = self.ctx_.options.heat_transport
  local native = (entry.format == 2) or ((entry.format == 0) and (lid_restart or full_continuation))
  local rc = 0
  if native then
    local hs = {nil}
    if full_continuation and self.checkpoint_enabled_ then
      local snapshot = NewStr()
      local v_error = O_SWMMEngine.checkpointBytes(self, snapshot, false)
      if not (v_error.n == 0) then
        self.ctx_.warnings_f:push_back(Str_Cat_CPtr_Str(R_Lit("SAVE HOTSTART: incomplete native continuation: "), v_error))
        do return end
      end
      Mv_Reset(hs, 1, HotStartManager_save_with_engine_checkpoint(self.ctx_, self.runoff_, self.groundwater_, sp, snapshot))
    else
      Mv_Reset(hs, 1, HotStartManager_save(self.ctx_, sp))
    end
    rc = (hs[1] ~= nil) and 0 or 1
  else
    if lid_restart then
      self.ctx_.warnings_f:push_back(Str_Cat_Str_CPtr(Str_Cat_CPtr_Str(R_Lit("SAVE HOTSTART: '"), sp), R_Lit("' is LEGACY; a legacy SWMM5 file carries no LID state.")))
    end
    local runoff = O_SWMMEngine.legacyRunoffSection(self)
    rc = HotStartManager_save_legacy_routing(sp, self.ctx_, runoff)
  end
  if rc ~= 0 then
    self.ctx_.warnings_f:push_back(Str_Cat_CPtr_Str(R_Lit("SAVE HOTSTART: "), S_F_tl_last_io_error_HotStartManager))
  end
end
function O_SWMMEngine.writeDueHotstartSaves(self)
  do
    local k = 0
    while L_ult(k, self.ctx_.files.hotstart_saves.n) do
      do
