        if ((entry.datetime == 0.0) or (not L_ult(k, self.hotstart_save_done_.n))) or (self.hotstart_save_done_.a[k] ~= 0) then
          goto cont1
        end
        local due_ms = (entry.datetime - self.ctx_.options.start_date) * 86400000.0
        if (self.ctx_.elapsed_ms + 1.0) < due_ms then
          goto cont1
        end
        self.hotstart_save_done_.a[k] = 1
        O_SWMMEngine.writeHotstartSave(self, entry)
      end
      ::cont1::
      k = k + 1
    end
  end
end
