  e.ctx_.climate_state:Assign(self.climate)
  e.ctx_.dt_controls_remaining = self.controls_remaining
  if self.heat_profile then
    O_HeatState.MoveFrom(e.ctx_.heat_state, self.heat)
    O_BedZoneState.MoveFrom(e.ctx_.bed_state, self.bed)
  end
  if self.reaction_profile then
    O_ReactionData.MoveFrom(e.ctx_.reactions, self.reaction)
    if self.prepared_ard ~= nil then
      O_Ttransport_ArdEngine.MoveFrom(e.ard_, self.prepared_ard)
    end
    if self.prepared_lard ~= nil then
      O_Tlard_LagrangianSolver.MoveFrom(e.lard_, self.prepared_lard)
    end
    e.ard_init_attempted_ = self.ard_attempted
    e.ctx_.subcatches.sweep_last_swept:MoveFrom_VecT(self.subcatch.sweep_last_swept)
    e.ctx_.subcatches.sweep_now:MoveFrom_VecT(self.subcatch.sweep_now)
    e.ctx_.subcatches.sweep_last_date:MoveFrom_VecT(self.subcatch.sweep_last_date)
  end
  O_Texfil_ExfilSoA.MoveFrom(e.exfil_.soa_, self.exfil)
  O_SWMMEngine_AvgAccumulator.MoveFrom(e.avg_, self.avg)
  do
    local i_2 = 0
    while L_ult(i_2, self.cursors.n) do
      do
        e.ctx_.tables.tables.a[i_2].cursor:Assign(self.cursors.a[i_2])
      end
      i_2 = i_2 + 1
    end
  end
  e.controls_.pending_actions_:MoveFrom_VecT(self.pending_f)
  e.controls_.action_slots_:MoveFrom_VecT(self.slots)
  e.controls_.last_action_count_ = self.action_count
  e.controls_.control_value_ = self.control_scratch[0]
  e.controls_.set_point_ = self.control_scratch[1]
  e.controls_.eval_date_ = self.control_scratch[2]
  e.controls_.cur_date_ = self.control_scratch[3]
  e.controls_.cur_time_ = self.control_scratch[4]
  e.controls_.elapsed_days_ = self.control_scratch[5]
  e.controls_.pid_states_:MoveFrom_VecT(self.pid)
  e.hydstruct_.orifices_.surf_area:MoveFrom_VecT(self.orifice_area)
  e.hydstruct_.weirs_.surf_area:MoveFrom_VecT(self.weir_area)
  e.xsp_cache_gen_ = 0xFFFFFFFFFFFFFFFF
  e.checkpoint_ready_ = true
end

