function O_SimulationContext.refreshReportedSpecies(self)
  self.reported_species_names:clear()
  do
    local p = 0
    while p < (((self.pollutant_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        self.reported_species_names:push_back(self.pollutant_names.names_:at(p):Clone())
      end
      p = p + 1
    end
  end
  if self.options.water_age then
    self.reported_species_names:push_back(NewStr_CPtr(R_Lit("__WATER_AGE__")))
  end
  if self.options.heat_transport then
    self.reported_species_names:push_back(NewStr_CPtr(R_Lit("__TEMPERATURE__")))
  end
  self.reactions.reported_species:clear()
  do
    local m = 0
    while m < (((self.reactions.species_name.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        if (not (self.reactions.report_enabled.n == 0)) and (not (self.reactions.report_enabled.a[m] ~= 0)) then
          goto cont2
        end
        self.reactions.reported_species:push_back(m)
        self.reported_species_names:push_back(self.reactions.species_name.a[m]:Clone())
      end
      ::cont2::
      m = m + 1
    end
  end
end
function O_SimulationContext.n_reported_species(self)
  do return ((self.reported_species_names.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
end
function O_SimulationContext.logControlAction(self, e)
  if not L_ult(self.control_log.n, S_SimulationContext_kMaxControlLog) then
    self.control_log_dropped = self.control_log_dropped + 1
    do return end
  end
  self.control_log:push_back(e:Clone())
end
function O_SimulationContext.finalize_max_stats(self)
  local t_1, t_2
  do
    local k = 0
    while k < S_SimulationContext_MAX_STATS do
      do
        t_2 = self.max_courant_crit[k]
        t_1 = SimulationContext_MaxStats__new()
        t_1.obj_type = 0
        t_1.index = -1
        t_1.value_f = -1.0
        O_SimulationContext_MaxStats.MoveFrom(t_2, t_1)
        t_2 = self.max_flow_turns[k]
        t_1 = SimulationContext_MaxStats__new()
        t_1.obj_type = 1
        t_1.index = -1
        t_1.value_f = -1.0
        O_SimulationContext_MaxStats.MoveFrom(t_2, t_1)
        t_2 = self.max_non_converged[k]
        t_1 = SimulationContext_MaxStats__new()
        t_1.obj_type = 0
        t_1.index = -1
        t_1.value_f = 0.0
        O_SimulationContext_MaxStats.MoveFrom(t_2, t_1)
      end
      k = k + 1
    end
  end
  local rpt_steps = self.routing_stats.report_steps
  if rpt_steps > 2 then
    local z = 100.0 / (0.6666666666666666 * ((rpt_steps - 2) + 0.0))
    do
      local j = 0
      while j < (((self.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
        do
          local x = (self.links.stat_flow_turns.a[j] + 0.0) * z
          SimulationContext_updateMaxStats(NewPtr_TA_l(self.max_flow_turns, 0), 1, j, x)
        end
        j = j + 1
      end
    end
  end
  local step_count = self.routing_stats.n_steps
  local dw = self.options.routing_model == 2
  if dw then
    do
      local j_2 = 0
      while j_2 < (((self.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
        do
          SimulationContext_updateMaxStats(NewPtr_TA_l(self.max_non_converged, 0), 0, j_2, self.nodes.stat_non_converged_count.a[j_2] / (step_count + 0.0))
        end
        j_2 = j_2 + 1
      end
    end
  end
  if ((not dw) or (self.options.variable_step == 0.0)) or (step_count == 0) then
    do return end
  end
  local inv_steps = 1.0 / (step_count + 0.0)
  do
    local j_3 = 0
    while j_3 < (((self.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local x_2 = self.nodes.stat_time_courant_critical.a[j_3] * inv_steps
        SimulationContext_updateMaxStats(NewPtr_TA_l(self.max_courant_crit, 0), 0, j_3, 100.0 * x_2)
      end
      j_3 = j_3 + 1
    end
  end
  do
    local j_4 = 0
    while j_4 < (((self.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local x_3 = self.links.stat_time_courant_critical.a[j_4] * inv_steps
        SimulationContext_updateMaxStats(NewPtr_TA_l(self.max_courant_crit, 0), 1, j_4, 100.0 * x_3)
      end
      j_4 = j_4 + 1
    end
  end
end
