function O_SimulationContext.save_lat_qual_state(self)
  O_NodeData.save_lat_qual_state(self.nodes)
  O_LinkData.save_qual_state(self.links)
end
function O_SimulationContext.save_hyd_state(self)
  O_NodeData.save_hyd_state(self.nodes)
  O_LinkData.save_hyd_state(self.links)
end
function O_SimulationContext.reset_state(self)
  self.runtime_coupling_used = false
  O_NodeData.reset_state(self.nodes)
  O_LinkData.reset_state(self.links)
  O_SubcatchData.reset_state(self.subcatches)
  O_GageData.reset_state(self.gages)
  O_TableData.reset_cursors(self.tables)
  self.current_time = 0.0
  self.current_date = self.options.start_date
  self.dt_controls_remaining = 0.0
  self.elapsed_ms = 0.0
  self.old_elapsed_ms = 0.0
  self.next_report_ms = 1000.0 * self.options.report_step
end
function O_SimulationContext.shrink_all_to_fit(self)
  O_NodeData.shrink_to_fit(self.nodes)
  O_LinkData.shrink_to_fit(self.links)
  O_SubcatchData.shrink_to_fit(self.subcatches)
  O_GageData.shrink_to_fit(self.gages)
  O_PollutantData.shrink_to_fit(self.pollutants)
  O_LanduseData.shrink_to_fit(self.landuses)
  O_BuildupData.shrink_to_fit(self.buildup)
  O_WashoffData.shrink_to_fit(self.washoff)
  O_TreatmentData.shrink_to_fit(self.treatment)
  O_SpatialFrame.shrink_to_fit(self.spatial)
end
function O_SimulationContext.n_nodes(self)
  do return ((self.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
end
function O_SimulationContext.n_links(self)
  do return ((self.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
end
function O_SimulationContext.n_subcatches(self)
  do return ((self.subcatch_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
end
function O_SimulationContext.n_gages(self)
  do return ((self.gage_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
end
function O_SimulationContext.n_pollutants(self)
  do return ((self.pollutant_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
end
function O_SimulationContext.n_landuses(self)
  do return ((self.landuse_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
end
function O_SimulationContext.n_tables(self)
  do return ((self.tables.tables.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
