end
function O_SimulationContext_RoutingStepStats.record_step(self, dt, steady, first_step)
  local t_1, t_2, t_3, t_4, t_5
  if steady then
    self.steady_time = self.steady_time + dt
    do return end
  end
  if not first_step then
    self.min_step = (dt < self.min_step) and dt or self.min_step
    do
      local i = 0
      while i < S_SimulationContext_RoutingStepStats_N_TIME_BINS do
        do
          if dt >= self.step_intervals[(((i + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000] then
            t_1 = self.step_counts
            t_2 = i
            t_3 = t_1[t_2]
            t_1[t_2] = t_3 + 1
            t_4, t_5 = {0}, 1
            t_4[t_5] = t_3
            break
          end
        end
        i = i + 1
      end
    end
  end
  self.max_step = (self.max_step < dt) and dt or self.max_step
  self.sum_step = self.sum_step + dt
  self.n_steps = self.n_steps + 1
end
function O_SimulationContext_RoutingStepStats.update_iterations(self, iters, converged)
  self.sum_iterations = self.sum_iterations + iters
  if not converged then
    self.n_non_converged = self.n_non_converged + 1
  end
end
function O_SimulationContext_RoutingStepStats.init_histogram(self, route_step, min_route_step)
  if route_step <= 0.0 then
    do return end
  end
  if min_route_step <= 0.0 then
    min_route_step = route_step
  end
  local log_hi = Math_Log10_d(route_step)
  local log_lo = Math_Log10_d(min_route_step)
  local delta = (log_hi - log_lo) / S_SimulationContext_RoutingStepStats_N_TIME_BINS
  self.step_intervals[0] = route_step
  do
    local i = 1
    while i <= S_SimulationContext_RoutingStepStats_N_TIME_BINS do
      do
        self.step_intervals[i] = L_pow(10.0, log_hi - (i * delta))
      end
      i = i + 1
    end
  end
  self.step_intervals[S_SimulationContext_RoutingStepStats_N_TIME_BINS] = min_route_step
end
function O_SimulationContext_RoutingStepStats.build_histogram(self)
  if (self.n_steps == 0) or (self.max_step <= 0.0) then
    do return end
  end
  local hi = self.max_step
  local lo = (self.min_step < (1E+30)) and self.min_step or 0.0
  if lo <= 0.0 then
    lo = hi
  end
  O_SimulationContext_RoutingStepStats.init_histogram(self, hi, lo)
end
function O_SimulationContext_RoutingStepStats.avg_step(self)
  do return (self.n_steps > 0) and (self.sum_step / (self.n_steps + 0.0)) or 0.0 end
end
function O_SimulationContext_RoutingStepStats.pct_non_converged(self)
  do return (self.n_steps > 0) and ((100.0 * (self.n_non_converged + 0.0)) / (self.n_steps + 0.0)) or 0.0 end
end
function O_SimulationContext_RoutingStepStats.computed_avg_iterations(self)
  do return (self.n_steps > 0) and (self.sum_iterations / (self.n_steps + 0.0)) or 0.0 end
end

