function O_SimulationOptions.linkValidateRoutingStep(self)
  local t_1, t_2
  if self.routing_step_authored > 0.0 then
    t_1, t_2 = self, "routing_step_authored"
  else
    t_1, t_2 = self, "routing_step"
  end
  do return t_1[t_2] end
end
function O_SimulationOptions.totalDurationMs(self)
  if self.total_duration_ms >= 0.0 then
    do return self.total_duration_ms end
  end
  do return L_floor((self.end_date - self.start_date) * 86400.0) * 1000.0 end
end

