  self.cell_conc:assign_ul_T(ns * nc, 0.0)
  self.cells_seeded = true
end
function O_BedZoneState.sized(self, n_links)
  do return self.link_temp.n == ((n_links > 0) and n_links or 0) end
end
function O_BedZoneState.clear(self)
  local t_1
  t_1 = BedZoneState__new()
  t_1.link_temp = NewVecD()
  t_1.link_conc = NewVecD()
  t_1.cell_temp = NewVecD()
  t_1.cell_conc = NewVecD()
  O_BedZoneState.MoveFrom(self, t_1)
end

