function O_ForcingData.resize(self, n_nodes, n_links, n_subcatches, n_gages, n_pollutants)
  self.n_nodes_ = n_nodes
  self.n_links_ = n_links
  self.n_subcatches_ = n_subcatches
  self.n_gages_ = n_gages
  self.n_pollutants_ = n_pollutants
  local un = n_nodes
  local ul = n_links
  local us = n_subcatches
  local ug = n_gages
  local unp = n_nodes * n_pollutants
  self.node_lat_inflow_mode:assign_ul_T(un, 0)
  self.node_lat_inflow_value:assign_ul_T(un, 0.0)
  self.node_lat_inflow_persist:assign_ul_T(un, 0)
  self.node_head_boundary_mode:assign_ul_T(un, 0)
  self.node_head_boundary_value:assign_ul_T(un, 0.0)
