  self.node_quality_value:assign_ul_T(unp, 0.0)
  self.node_quality_persist:assign_ul_T(unp, 0)
  self.node_temperature_mode:assign_ul_T(un, 0)
  self.node_temperature_value:assign_ul_T(un, 0.0)
