  self.node_age_mode:assign_ul_T(un, 0)
  self.node_age_value:assign_ul_T(un, 0.0)
  self.node_age_persist:assign_ul_T(un, 0)
  self.link_flow_mode:assign_ul_T(ul, 0)
  self.link_flow_value:assign_ul_T(ul, 0.0)
  self.link_flow_persist:assign_ul_T(ul, 0)
  self.link_setting_mode:assign_ul_T(ul, 0)
  self.link_setting_value:assign_ul_T(ul, 0.0)
  self.link_setting_persist:assign_ul_T(ul, 0)
  self.link_seepage_mode:assign_ul_T(ul, 0)
  self.link_seepage_value:assign_ul_T(ul, 0.0)
  self.link_seepage_persist:assign_ul_T(ul, 0)
