function O_ForcingData.clear_reset_entries(self)
  local clear_resets = function(mode_vec, persist_vec)
  do
    local i = 0
    while L_ult(i, mode_vec.n) do
      do
        if persist_vec.a[i] == 0 then
          mode_vec.a[i] = 0
        end
      end
      i = i + 1
    end
  end
  do return end
end
  clear_resets(self.node_lat_inflow_mode, self.node_lat_inflow_persist)
  clear_resets(self.node_head_boundary_mode, self.node_head_boundary_persist)
  clear_resets(self.node_quality_mode, self.node_quality_persist)
  clear_resets(self.node_temperature_mode, self.node_temperature_persist)
  clear_resets(self.node_age_mode, self.node_age_persist)
  clear_resets(self.link_flow_mode, self.link_flow_persist)
  clear_resets(self.link_setting_mode, self.link_setting_persist)
  clear_resets(self.link_seepage_mode, self.link_seepage_persist)
  clear_resets(self.link_quality_mode, self.link_quality_persist)
  clear_resets(self.subcatch_rainfall_mode, self.subcatch_rainfall_persist)
  clear_resets(self.subcatch_evap_mode, self.subcatch_evap_persist)
  clear_resets(self.subcatch_snowfall_mode, self.subcatch_snowfall_persist)
  clear_resets(self.gage_rainfall_mode, self.gage_rainfall_persist)
  if self.climate_temperature_persist == 0 then
    self.climate_temperature_mode = 0
  end
  if self.climate_wind_persist == 0 then
    self.climate_wind_mode = 0
  end
  if self.climate_evap_persist == 0 then
    self.climate_evap_mode = 0
  end
  do
    local k = 0
    while k < 2 do
      do
        O_ForcingData_ElemClimateChannel.resetPerStep(self.elem_air_temp[k])
        O_ForcingData_ElemClimateChannel.resetPerStep(self.elem_humidity[k])
        O_ForcingData_ElemClimateChannel.resetPerStep(self.elem_wind[k])
        O_ForcingData_ElemClimateChannel.resetPerStep(self.elem_shortwave[k])
      end
      k = k + 1
    end
  end
end
function O_ForcingData.effective_temperature(self, broadcast)
  local t_1
  t_1 = self.climate_temperature_mode
  if t_1 == 1 then
    do return self.climate_temperature_value end
  elseif t_1 == 2 then
    do return broadcast + self.climate_temperature_value end
  else
    do return broadcast end
  end
end
function O_ForcingData.effective_wind(self, broadcast)
  local t_1
  t_1 = self.climate_wind_mode
