function O_ForcingData.effective_rainfall(self, ui, gage_rainfall)
  local t_1
  if not L_ult(ui, self.subcatch_rainfall_mode.n) then
    do return gage_rainfall end
  end
  t_1 = self.subcatch_rainfall_mode.a[ui]
  if t_1 == 1 then
    do return self.subcatch_rainfall_value.a[ui] end
  elseif t_1 == 2 then
    do return gage_rainfall + self.subcatch_rainfall_value.a[ui] end
  else
    do return gage_rainfall end
  end
end
