  self.persist = s.persist
  s.persist = NewVecB()
end
function O_ForcingData_ElemClimateChannel.apply__i_d(self, i, base)
  if i < 0 then
    do return base end
  end
  local u = i
  if (not L_ult(u, self.mode.n)) or (self.mode.a[u] == 0) then
    do return base end
  end
  do return (self.mode.a[u] == 1) and self.value_f.a[u] or (base + self.value_f.a[u]) end
end
function O_ForcingData_ElemClimateChannel.resetPerStep(self)
  do
    local i = 0
    while L_ult(i, self.mode.n) do
      do
        if self.persist.a[i] == 0 then
          self.mode.a[i] = 0
        end
      end
      i = i + 1
    end
  end
end

