function O_HeatConfigData.source_temp(self, s, node)
  do
    local i = 0
    while L_ult(i, self.node_over_source.n) do
      do
        if (self.node_over_source.a[i] == s) and (self.node_over_node.a[i] == node) then
          do return self.node_over_temp.a[i] end
        end
      end
      i = i + 1
    end
  end
  do return self.global_temp[s] end
end

