  self.elem_idx:push_back(ei)
  self.constituent:push_back(cons:Clone())
  self.kind_f:push_back(k)
  self.value_f:push_back(v)
  self.from_file:push_back((fromFile and 1 or 0) & 0xFF)
end
function O_InitialQualityData.erase(self, idx)
  if (idx < 0) or (idx >= (((self.is_link.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
    do return end
  end
  local u = idx
  self.is_link:erase_IterT(IterB_op_Add(self.is_link:begin(), u):Clone())
  self.elem_name:erase_IterT(Iter_op_Add(self.elem_name:begin(), u):Clone())
  self.elem_idx:erase_IterT(IterI_op_Add(self.elem_idx:begin(), u):Clone())
  self.constituent:erase_IterT(Iter_op_Add(self.constituent:begin(), u):Clone())
  self.kind_f:erase_IterT(IterI_op_Add(self.kind_f:begin(), u):Clone())
  self.value_f:erase_IterT(IterD_op_Add(self.value_f:begin(), u):Clone())
  if L_ult(u, self.from_file.n) then
    self.from_file:erase_IterT(IterB_op_Add(self.from_file:begin(), u):Clone())
  end
end

