  self.value_f:assign_ul_T(n_layers * species, 0.0)
  self.vol_prev:assign_ul_T(n_layers, 0.0)
  self.drain_value:assign_ul_T(units * species, 0.0)
  self.inflow_value:assign_ul_T(units * species, 0.0)
end
function O_LidLayerSpeciesState.ensureSized(self, units, species, offsets)
  local want = (units * S_LidLayerSpeciesState_kLayerCount) * species
  if ((self.n_units == units) and (self.n_species_f == species)) and (self.value_f.n == want) then
