function O_LinkData.add_lstep_sample(self, j, dt, dur, rs)
  local t_1, t_2
  local u = j
  if (self.stat_lstep_time.a[u] <= 0.0) or (dt < self.stat_lstep_min.a[u]) then
    self.stat_lstep_min.a[u] = dt
  end
  if dt > self.stat_lstep_max.a[u] then
    self.stat_lstep_max.a[u] = dt
  end
  self.stat_lstep_dt_time.a[u] = self.stat_lstep_dt_time.a[u] + (dt * dur)
  self.stat_lstep_time.a[u] = self.stat_lstep_time.a[u] + dur
  t_1 = self.stat_lstep_bin_time.a
  t_2 = (u * S_LinkData_N_LSTEP_BINS) + LinkData_lstep_bin(dt, rs)
  t_1[t_2] = t_1[t_2] + dur
end
function O_LinkData.count(self)
  do return ((self.type.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
end
