function O_LinkData.save_hyd_state(self)
  Algo_copy_IterT_IterT_IterT__D(self.flow:begin(), self.flow:end_(), self.old_flow:begin())
  Algo_copy_IterT_IterT_IterT__D(self.depth:begin(), self.depth:end_(), self.old_depth:begin())
  Algo_copy_IterT_IterT_IterT__D(self.volume:begin(), self.volume:end_(), self.old_volume:begin())
end
function O_LinkData.save_qual_state(self)
  Algo_copy_IterT_IterT_IterT__D(self.conc:begin(), self.conc:end_(), self.conc_old:begin())
end
function O_LinkData.reset_state(self)
  Algo_fill_IterT_IterT_T__D(self.flow:begin(), self.flow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.kw_inflow:begin(), self.kw_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.depth:begin(), self.depth:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.volume:begin(), self.volume:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.froude:begin(), self.froude:end_(), 0.0)
  Algo_fill_IterT_IterT_T__B(self.flow_class:begin(), self.flow_class:end_(), 0)
  Algo_fill_IterT_IterT_T__D(self.old_flow:begin(), self.old_flow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.old_depth:begin(), self.old_depth:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.old_volume:begin(), self.old_volume:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.conc:begin(), self.conc:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.conc_old:begin(), self.conc_old:end_(), 0.0)
end

