function O_MsxSurfaceData.active(self)
  do return self.resolved and (self.n_species_f > 0) end
end
function O_MsxSurfaceData.pidx(self, lu, m)
  do return (lu * self.n_species_f) + m end
end
function O_MsxSurfaceData.bu_idx(self, sc, lu, m)
  do return (((sc * self.n_landuses_f) + lu) * self.n_species_f) + m end
end
function O_MsxSurfaceData.sidx(self, sc, m)
  do return (sc * self.n_species_f) + m end
end
function O_MsxSurfaceData.resize_params(self, nlu, nm)
  self.n_landuses_f = nlu
  self.n_species_f = nm
  local n = nlu * nm
  self.bu_type:assign_ul_T(n, 0)
  self.bu_c1:assign_ul_T(n, 0.0)
  self.bu_c2:assign_ul_T(n, 0.0)
  self.bu_c3:assign_ul_T(n, 0.0)
  self.bu_normalizer:assign_ul_T(n, 0)
  self.bu_max_days:assign_ul_T(n, 0.0)
  self.wo_type:assign_ul_T(n, 0)
  self.wo_coeff:assign_ul_T(n, 0.0)
  self.wo_expon:assign_ul_T(n, 0.0)
  self.wo_sweep_effic:assign_ul_T(n, 0.0)
  self.wo_bmp_effic:assign_ul_T(n, 0.0)
  self.mcf:assign_ul_T(nm, 1.0)
  if self.c_rain.n ~= nm then
    self.c_rain:assign_ul_T(nm, 0.0)
  end
  self.snow_only:assign_ul_T(nm, false)
end
function O_MsxSurfaceData.resize_state(self, nsc)
  self.n_subcatch = nsc
  local nm = self.n_species_f
  self.buildup:assign_ul_T((nsc * self.n_landuses_f) * nm, 0.0)
  self.washoff_conc:assign_ul_T(nsc * nm, 0.0)
  self.washoff_conc_old:assign_ul_T(nsc * nm, 0.0)
  self.ponded_qual:assign_ul_T(nsc * nm, 0.0)
  self.runon_qual_rate:assign_ul_T(nsc * nm, 0.0)
  self.lid_drain_runon_load:assign_ul_T(nsc * nm, 0.0)
  if self.init_loading.n ~= (nsc * nm) then
    self.init_loading:assign_ul_T(nsc * nm, 0.0)
  end
  self.led_init_buildup:assign_ul_T(nm, 0.0)
  self.led_buildup:assign_ul_T(nm, 0.0)
  self.led_runoff_load:assign_ul_T(nm, 0.0)
  self.led_sweeping:assign_ul_T(nm, 0.0)
  self.led_bmp_removal:assign_ul_T(nm, 0.0)
  self.led_wet_deposition:assign_ul_T(nm, 0.0)
  self.led_infil_loss:assign_ul_T(nm, 0.0)
  self.led_ponded_lost:assign_ul_T(nm, 0.0)
  self.led_reacted:assign_ul_T(nm, 0.0)
  self.led_reaction_clamped:assign_ul_T(nm, 0.0)
  self.led_subcatch_load:assign_ul_T(nsc * nm, 0.0)
end

