function O_NodeData.resize_loads(self, n_pollutants)
  self.stat_n_pollutants = n_pollutants
  if n_pollutants > 0 then
    local total = (((self.type.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) * n_pollutants
    self.stat_total_load:assign_ul_T(total, 0.0)
  end
end
function O_NodeData.resize_quality(self, n_pollutants)
  self.conc_n_pollutants = n_pollutants
  if n_pollutants > 0 then
    local total = (((self.type.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) * n_pollutants
    self.conc:assign_ul_T(total, 0.0)
    self.conc_old:assign_ul_T(total, 0.0)
    self.hrt:assign_ul_T(((self.type.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000, 0.0)
