function O_NodeData.save_hyd_state(self)
  Algo_copy_IterT_IterT_IterT__D(self.depth:begin(), self.depth:end_(), self.old_depth:begin())
  Algo_copy_IterT_IterT_IterT__D(self.volume:begin(), self.volume:end_(), self.old_volume:begin())
  Algo_copy_IterT_IterT_IterT__D(self.inflow:begin(), self.inflow:end_(), self.old_inflow:begin())
  do
    local i = 0
    while L_ult(i, self.inflow.n) do
      do
        self.old_net_inflow.a[i] = self.inflow.a[i] - self.outflow.a[i]
      end
      i = i + 1
    end
  end
end
function O_NodeData.save_lat_qual_state(self)
  Algo_copy_IterT_IterT_IterT__D(self.lat_flow:begin(), self.lat_flow:end_(), self.old_lat_flow:begin())
  Algo_copy_IterT_IterT_IterT__D(self.conc:begin(), self.conc:end_(), self.conc_old:begin())
end
function O_NodeData.reset_state(self)
  local n = self.depth.n
  do
    local i = 0
    while L_ult(i, n) do
      do
        self.depth.a[i] = self.init_depth.a[i]
        self.old_depth.a[i] = self.init_depth.a[i]
        self.head.a[i] = self.invert_elev.a[i] + self.init_depth.a[i]
      end
      i = i + 1
    end
  end
  Algo_fill_IterT_IterT_T__D(self.volume:begin(), self.volume:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.old_volume:begin(), self.old_volume:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.lat_flow:begin(), self.lat_flow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.inflow:begin(), self.inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.outflow:begin(), self.outflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.overflow:begin(), self.overflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.losses:begin(), self.losses:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.old_net_inflow:begin(), self.old_net_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.old_lat_flow:begin(), self.old_lat_flow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.old_inflow:begin(), self.old_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.coupling_inflow:begin(), self.coupling_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.coupling_volume:begin(), self.coupling_volume:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.coupling_queue:begin(), self.coupling_queue:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.coupling_qual_queue:begin(), self.coupling_qual_queue:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.coupling_qual_inflow:begin(), self.coupling_qual_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.coupling_age_vol_queue:begin(), self.coupling_age_vol_queue:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.coupling_temp_vol_queue:begin(), self.coupling_temp_vol_queue:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.coupling_age_vol_inflow:begin(), self.coupling_age_vol_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.coupling_temp_vol_inflow:begin(), self.coupling_temp_vol_inflow:end_(), 0.0)
  O_NodeData.clearInflowSources(self)
  Algo_fill_IterT_IterT_T__D(self.conc:begin(), self.conc:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.conc_old:begin(), self.conc_old:end_(), 0.0)
end
function O_NodeData.clearInflowSources(self)
  Algo_fill_IterT_IterT_T__D(self.ext_inflow:begin(), self.ext_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.dwf_inflow:begin(), self.dwf_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.rdii_inflow:begin(), self.rdii_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.iface_inflow:begin(), self.iface_inflow:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.iface_qual_mass:begin(), self.iface_qual_mass:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.ext_qual_mass:begin(), self.ext_qual_mass:end_(), 0.0)
  Algo_fill_IterT_IterT_T__D(self.dwf_qual_mass:begin(), self.dwf_qual_mass:end_(), 0.0)
