function O_NodeSubtypes.rebuild_index(self, n_nodes)
  self.subtype_row:assign_ul_T(n_nodes, -1)
  do
    local r = 0
    while r < (((self.storages.node_idx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        self.subtype_row.a[self.storages.node_idx.a[r]] = r
      end
      r = r + 1
    end
  end
  do
    local r_2 = 0
    while r_2 < (((self.outfalls.node_idx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        self.subtype_row.a[self.outfalls.node_idx.a[r_2]] = r_2
      end
      r_2 = r_2 + 1
    end
  end
  do
    local r_3 = 0
    while r_3 < (((self.dividers.node_idx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        self.subtype_row.a[self.dividers.node_idx.a[r_3]] = r_3
      end
      r_3 = r_3 + 1
    end
  end
end
function O_NodeSubtypes.set_node_type(self, nodes, i, t)
  local ui = i
  if i >= (((self.subtype_row.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) then
    self.subtype_row:resize_ul_T(i + 1, -1)
  end
  if (t ~= 0) and L_ult(ui, nodes.storage_area.n) then
    nodes.storage_area.a[ui] = 0.0
  end
  local old = nodes.type.a[ui]
  local existing = self.subtype_row.a[ui]
  if (old == t) and (existing >= 0) then
    do return existing end
  end
  local shifted = false
  if existing >= 0 then
    if old == 3 then
      O_StorageData.erase_at(self.storages, existing)
      goto sw1
    elseif old == 1 then
      O_OutfallData.erase_at(self.outfalls, existing)
      goto sw1
    elseif old == 2 then
      O_DividerData.erase_at(self.dividers, existing)
      goto sw1
    else
      goto sw1
    end
    ::sw1::
    shifted = true
  end
  nodes.type.a[ui] = t
  local row = -1
  if t == 3 then
    row = O_StorageData.add_default(self.storages, i)
    if row ~= (((((((self.storages.node_idx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) then
      shifted = true
    end
    goto sw2
  elseif t == 1 then
    row = O_OutfallData.add_default(self.outfalls, i)
    if row ~= (((((((self.outfalls.node_idx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) then
      shifted = true
    end
    goto sw2
  elseif t == 2 then
    row = O_DividerData.add_default(self.dividers, i)
    if row ~= (((((((self.dividers.node_idx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) then
      shifted = true
    end
    goto sw2
  elseif t == 0 then
    goto sw2
  else
    goto sw2
  end
  ::sw2::
  if shifted then
    O_NodeSubtypes.rebuild_index(self, ((nodes.type.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)
    do return (t == 0) and (-1) or self.subtype_row.a[ui] end
  end
  self.subtype_row.a[ui] = row
  do return row end
end
function O_NodeSubtypes.storage_row(self, i)
  if (i >= 0) and (i < (((self.subtype_row.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
    local r = self.subtype_row.a[i]
    if ((r >= 0) and (r < (((self.storages.node_idx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000))) and (self.storages.node_idx.a[r] == i) then
