function O_ReactionData.find_species(self, n)
  do
    local i = 0
    while L_ult(i, self.species_name.n) do
      do
        if n:Clone():Equals_Str(self.species_name.a[i]:Clone()) then
          do return ((i + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
        end
      end
      i = i + 1
    end
  end
  do return -1 end
end
