  self.name_ = s.name_ and s.name_:Clone()
  self.kind_ = s.kind_ and s.kind_:Clone()
  self.units_ = s.units_ and s.units_:Clone()
  self.n_pollutants_ = s.n_pollutants_
end
function O_SpeciesRegistry.Assign(self, s)
  if L_rawequal(self, s) then
    do return end
  end
  self.name_:Assign_VecT(s.name_)
  self.kind_:Assign_VecT(s.kind_)
  self.units_:Assign_VecT(s.units_)
  self.n_pollutants_ = s.n_pollutants_
end
function O_SpeciesRegistry.MoveFrom(self, s)
  if L_rawequal(self, s) then
    do return end
  end
  self.name_ = s.name_
  s.name_ = NewVec(NewStr)
  self.kind_ = s.kind_
  s.kind_ = NewVecI()
  self.units_ = s.units_
  s.units_ = NewVec(NewStr)
  self.n_pollutants_ = s.n_pollutants_
end
function O_SpeciesRegistry.clear(self)
  self.name_:clear()
  self.kind_:clear()
  self.units_:clear()
  self.n_pollutants_ = 0
end
function O_SpeciesRegistry.add(self, name_in, kind, units_in)
  local name = {name_in}
  local units = {units_in}
  if O_SpeciesRegistry.find(self, name[1]:Clone()) >= 0 then
    do return -1 end
  end
  self.name_:push_back(Mv_Take(name, 1, NewStr))
  self.kind_:push_back(kind)
  self.units_:push_back(Mv_Take(units, 1, NewStr))
  if kind == 0 then
    self.n_pollutants_ = (((self.n_pollutants_ + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  end
  do return ((((((self.name_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
end
function O_SpeciesRegistry.find(self, name)
  do
    local i = 0
    while L_ult(i, self.name_.n) do
      do
        if name:Clone():Equals_Str(self.name_.a[i]:Clone()) then
          do return ((i + 0x80000000) & 0xFFFFFFFF) - 0x80000000 end
        end
      end
      i = i + 1
    end
  end
  do return -1 end
end
function O_SpeciesRegistry.pollutant_count(self)
  do return self.n_pollutants_ end
end
function O_SpeciesRegistry.name(self, i)
  do return self.name_.a[i] end
end

