function O_SubcatchData.resize_quality(self, n_pollutants)
  self.conc_n_pollutants = n_pollutants
  if n_pollutants > 0 then
    local total = (((self.area.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) * n_pollutants
    self.conc:assign_ul_T(total, 0.0)
    self.conc_old:assign_ul_T(total, 0.0)
    self.init_loading:assign_ul_T(total, 0.0)
    self.ponded_qual:assign_ul_T(total, 0.0)
    self.runon_qual_rate:assign_ul_T(total, 0.0)
    self.lid_drain_runon_qual:assign_ul_T(total, 0.0)
    self.washoff_load:assign_ul_T(total, 0.0)
  end
end
