-- ---- O_Tdynwave_DWSolver
O_Tdynwave_DWSolver = lua_class("Tdynwave_DWSolver", nil, {Cpp_ICopy})
function O_Tdynwave_DWSolver._new() return L_setmetatable({head_tol = 0.0, max_trials = 0, omega = 0.0, surcharge_method = 0, node_continuity = 0, anderson_accel = false, unsteady_friction = 0, uf_k3 = 0.0, tpa_celerity = 0.0, evap_rate = 0.0, n_nodes_ = 0, n_links_ = 0, n_conduits_ = 0, num_threads_ = 0, any_conduit_seep_ = false, losses_all_zero_ = false, dt_gravity_ = 0.0, last_converged_ = false, min_surf_area_ = 0.0, variable_step_ = 0.0, unit_sys_ = 0, sim_time_ = 0.0}, O_Tdynwave_DWSolver) end
function O_Tdynwave_DWSolver.init(self, n_nodes, n_links, groups, ctx)
  local t_1, t_2
  self.n_nodes_ = n_nodes
  self.n_links_ = n_links
  self.groups_ = groups
  do
    local ucf_len = S_F_ucf_Ucf_UnitConversion[3][F_ucf_getUnitSystem(ctx.options.flow_units)]
    self.min_surf_area_ = (ctx.options.min_surf_area > 0.0) and (ctx.options.min_surf_area / (ucf_len * ucf_len)) or S_F_constants_MIN_SURFAREA
  end
  local un = n_nodes
  local ul = n_links
  if self.unsteady_friction ~= 0 then
    self.uf_nb_up_:assign_ul_T(ul, -1)
    self.uf_nb_dn_:assign_ul_T(ul, -1)
    self.uf_sg_up_:assign_ul_T(ul, 0)
    self.uf_sg_dn_:assign_ul_T(ul, 0)
    local ccount = NewVecI_ul_T(un, 0)
    local other = NewVecI_ul_T(un, 0)
    local inc = NewVec_ul_T(un, {[0] = -1, -1, n = 2}, MK_N)
    do
      local j = 0
      while j < n_links do
        do
          local ujj = j
          local is_cond = ctx.links.type.a[ujj] == 0
          do
            local v___r1 = {[0] = ctx.links.node1.a[ujj], ctx.links.node2.a[ujj], n = 2}
            do
              local v___i2_n = v___r1.n
              for v___i2 = 0, v___i2_n - 1 do
                do
                  local nd = v___r1[v___i2]
                  do
                    if (nd < 0) or (nd >= n_nodes) then
                      goto cont2
                    end
                    local und = nd
                    if not is_cond then
                      other.a[und] = (((other.a[und] + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
                      goto cont2
                    end
                    if ccount.a[und] < 2 then
                      inc.a[und][ccount.a[und]] = j
                    end
                    ccount.a[und] = (((ccount.a[und] + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
                  end
                end
                ::cont2::
              end
            end
          end
        end
        j = j + 1
      end
    end
    do
      local j_2 = 0
      while j_2 < n_links do
        do
          local ujj_2 = j_2
          if ctx.links.type.a[ujj_2] ~= 0 then
            goto cont3
          end
          local n1 = ctx.links.node1.a[ujj_2]
          local n2 = ctx.links.node2.a[ujj_2]
          if (n1 >= 0) and (n1 < n_nodes) then
            local u1 = n1
            if (ccount.a[u1] == 2) and (other.a[u1] == 0) then
              if inc.a[u1][0] == j_2 then
                t_1, t_2 = inc.a[u1], 1
              else
                t_1, t_2 = inc.a[u1], 0
              end
              local k = t_1[t_2]
              if k >= 0 then
                self.uf_nb_up_.a[ujj_2] = k
                self.uf_sg_up_.a[ujj_2] = (ctx.links.node2.a[k] == n1) and 1 or (-1)
              end
            end
          end
          if (n2 >= 0) and (n2 < n_nodes) then
            local u2 = n2
            if (ccount.a[u2] == 2) and (other.a[u2] == 0) then
              if inc.a[u2][0] == j_2 then
                t_1, t_2 = inc.a[u2], 1
              else
                t_1, t_2 = inc.a[u2], 0
              end
              local k_2 = t_1[t_2]
              if k_2 >= 0 then
                self.uf_nb_dn_.a[ujj_2] = k_2
                self.uf_sg_dn_.a[ujj_2] = (ctx.links.node1.a[k_2] == n2) and 1 or (-1)
              end
            end
          end
        end
        ::cont3::
        j_2 = j_2 + 1
      end
    end
  end
  self.any_conduit_seep_ = false
  self.losses_all_zero_ = true
  do
    local v_CD = ctx.link_subtypes.conduits
    do
      local r = 0
      while r < (((v_CD.link_idx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
        do
          if v_CD.seep_rate.a[r] > 0.0 then
            self.any_conduit_seep_ = true
            break
          end
        end
        r = r + 1
      end
    end
  end
  O_Tdynwave_DWNodeArrays.resize(self.xnode_, un)
  self.area1_:resize_ul_T(ul, 0.0)
  self.area2_:resize_ul_T(ul, 0.0)
  self.area_mid_:resize_ul_T(ul, 0.0)
  self.hrad_mid_:resize_ul_T(ul, 0.0)
  self.width_mid_:resize_ul_T(ul, 0.0)
  self.depth1_:resize_ul_T(ul, 0.0)
  self.depth2_:resize_ul_T(ul, 0.0)
  self.depth_mid_:resize_ul_T(ul, 0.0)
  self.velocity_:resize_ul_T(ul, 0.0)
  self.froude_:resize_ul_T(ul, 0.0)
  self.sigma_:resize_ul_T(ul, 0.0)
  self.dqdh_:resize_ul_T(ul, 0.0)
  self.new_flow_:resize_ul_T(ul, 0.0)
  self.q1_:assign_ul_T(ul, 0.0)
  self.area_old_:resize_ul_T(ul, 0.0)
  self.bypassed_:assign_ul_T(ul, 0)
  self.surf_area1_:resize_ul_T(ul, 0.0)
  self.surf_area2_:resize_ul_T(ul, 0.0)
  self.hrad1_:resize_ul_T(ul, 0.0)
  self.width1_:resize_ul_T(ul, 0.0)
  self.width2_:resize_ul_T(ul, 0.0)
  self.h1_:resize_ul_T(ul, 0.0)
  self.h2_:resize_ul_T(ul, 0.0)
  self.fasnh_:resize_ul_T(ul, 1.0)
  self.wcap_d1_:resize_ul_T(ul, 0.0)
  self.wcap_d2_:resize_ul_T(ul, 0.0)
  self.wcap_dm_:resize_ul_T(ul, 0.0)
  self.conduit_idx_:clear()
  self.conduit_idx_:reserve(ul)
  do
    local j_3 = 0
    while j_3 < n_links do
      do
        local ujc = j_3
        if (ctx.links.type.a[ujc] == 0) and (ctx.links.xsect_shape.a[ujc] ~= 25) then
          self.conduit_idx_:push_back(j_3)
        end
      end
      j_3 = j_3 + 1
    end
  end
  self.n_conduits_ = ((self.conduit_idx_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  self.is_open_:resize_ul_T(ul, 0)
  self.is_force_main_:resize_ul_T(ul, 0)
  self.has_losses_:resize_ul_T(ul, 0)
  self.barrels_d_:resize_ul_T(ul, 1.0)
  self.cached_length_:resize_ul_T(ul, 0.0)
  self.inv_length_:resize_ul_T(ul, 0.0)
  local links = ctx.links
  local v_CD_2 = ctx.link_subtypes.conduits
  do
    local ci = 0
    while ci < self.n_conduits_ do
      do
        local j_4 = self.conduit_idx_.a[ci]
        local uj = j_4
        local ucr = O_LinkSubtypes.row_in(ctx.link_subtypes, j_4, ctx.link_subtypes.conduits.link_idx)
        local shape = links.xsect_shape.a[uj]
        self.is_open_.a[uj] = (F_dynwave_isOpenShape_DynamicWave(shape) and 1 or 0) & 0xFF
        self.is_force_main_.a[uj] = ((shape == 23) and 1 or 0) & 0xFF
        self.has_losses_.a[uj] = ((((v_CD_2.loss_inlet.a[ucr] ~= 0.0) or (v_CD_2.loss_outlet.a[ucr] ~= 0.0)) or (v_CD_2.loss_avg.a[ucr] ~= 0.0)) and 1 or 0) & 0xFF
        t_1 = v_CD_2.barrels.a[ucr]
        self.barrels_d_.a[uj] = ((t_1 < 1) and 1 or t_1) + 0.0
        self.q1_.a[uj] = links.flow.a[uj] / self.barrels_d_.a[uj]
        local len = v_CD_2.mod_length.a[ucr]
        if len <= 0.0 then
          len = v_CD_2.length.a[ucr]
        end
        self.cached_length_.a[uj] = len
        self.inv_length_.a[uj] = (len > 0.0) and (1.0 / len) or 0.0
        local xs0 = F_dynwave_buildXSP_DynamicWave(ctx, uj)
        self.area_mid_.a[uj] = O_Txsect_XsectEval.getAofY(F_xsect_hostEval(), xs0, links.depth.a[uj])
      end
      ci = ci + 1
    end
  end
  self.category_:resize_ul_T(ul, 0)
  O_Tdynwave_DWSolver.refreshConduitTile(self, ctx)
  O_Tdynwave_DWSolver.buildConduitNodeCSR(self, ctx)
  O_Tdynwave_DWSolver.buildVirtualJunctionPairs(self, ctx)
  self.aa_y_prev_:resize_ul_T(un, 0.0)
  self.aa_g_prev_:resize_ul_T(un, 0.0)
  self.aa_r_prev_:resize_ul_T(un, 0.0)
  self.aa_skip_:resize_ul_T(un, 0)
  if self.surcharge_method == 3 then
    local ucf_len2 = S_F_ucf_Ucf_UnitConversion[3][F_ucf_getUnitSystem(ctx.options.flow_units)]
    t_1 = self.tpa_celerity / ucf_len2
    local a_fts = (t_1 < 1.0) and 1.0 or t_1
    local ucn = self.n_conduits_
    self.tpa_w_:assign_ul_T(ucn, 0.0)
    self.tpa_latch_:assign_ul_T(ucn, 0)
    self.tpa_latch_changed_:assign_ul_T(ucn, 0)
    do
      local ci_2 = 0
      while ci_2 < self.n_conduits_ do
        do
          local uj_2 = self.conduit_idx_.a[ci_2]
          local af = ctx.links.xsect_a_full.a[uj_2]
          self.tpa_w_.a[ci_2] = (af > 0.0) and ((S_F_constants_GRAVITY * af) / (a_fts * a_fts)) or 0.0
        end
        ci_2 = ci_2 + 1
      end
    end
  end
  if self.surcharge_method == 2 then
    self.dps_config_.c_pT = ctx.options.dps_target_celerity * 3.28084
    self.dps_config_.alpha = (ctx.options.dps_alpha < 2.0) and 2.0 or ctx.options.dps_alpha
    self.dps_config_.r = (ctx.options.dps_decay_time < 0.001) and 0.001 or ctx.options.dps_decay_time
    self.dps_config_.c_pT_sq = self.dps_config_.c_pT * self.dps_config_.c_pT
    O_Tdynwave_DPSLinkArrays.resize(self.dps_, self.n_conduits_)
    self.sim_time_ = 0.0
    do
      local ci_3 = 0
      while ci_3 < self.n_conduits_ do
        do
          local j_5 = self.conduit_idx_.a[ci_3]
          local uj_3 = j_5
          local uci = ci_3
          if self.is_open_.a[uj_3] ~= 0 then
            self.dps_.P_hat_0.a[uci] = 1.0
            self.dps_.P_hat.a[uci] = 1.0
            self.dps_.P.a[uci] = 1.0
            goto cont8
          end
          local af_2 = links.xsect_a_full.a[uj_3]
          local tw = links.xsect_w_max.a[uj_3]
          local l_D = (tw > 0.0) and (af_2 / tw) or 0.0
          local c_g = (l_D > 0.0) and L_sqrt(S_F_constants_GRAVITY * l_D) or 1.0
          self.dps_.P_hat_0.a[uci] = self.dps_config_.c_pT / (self.dps_config_.alpha * c_g)
          t_1 = self.dps_.P_hat_0.a[uci]
          self.dps_.P_hat_0.a[uci] = (t_1 < 1.0) and 1.0 or t_1
          t_1 = self.dps_.P_hat_0.a[uci]
          self.dps_.P_hat.a[uci] = t_1
          self.dps_.P.a[uci] = t_1
          self.dps_.As.a[uci] = 0.0
          self.dps_.hs.a[uci] = 0.0
          self.dps_.hs_prev_iter.a[uci] = 0.0
          self.dps_.T_s_target.a[uci] = (self.dps_config_.c_pT_sq > 0.0) and ((S_F_constants_GRAVITY * af_2) / self.dps_config_.c_pT_sq) or 0.0
          self.dps_.surcharged.a[uci] = 0
          self.dps_.t_s.a[uci] = 0.0
        end
        ::cont8::
        ci_3 = ci_3 + 1
      end
    end
  end
end
function O_Tdynwave_DWSolver.setNumThreads(self, n, warnings)
  do
    local e = R_getenv(R_Lit("SWMM_DW_THREADS"))
    if not e:get_IsNull() then
      local forced = R_atoi(e)
      if forced >= 1 then
        self.num_threads_ = forced
        if warnings ~= nil then
          local buf = R_Buf_i(160)
          R_snprintf_CPtr_ul_CPtr_oA(buf, 160, R_Lit("Dynamic-wave thread count forced to %d by the SWMM_DW_THREADS environment variable ([OPTIONS] THREADS ignored for dynamic wave)."), forced)
          warnings:emplace_back(Str_from_CPtr(buf:Clone()))
        end
        do return end
      end
    end
  end
  self.num_threads_ = F_threadinfo_dwThreads(n, self.n_conduits_, warnings)
end
function O_Tdynwave_DWSolver.execute(self, ctx, dt, non_conduit_fn)
  local t_1, t_2, t_3
  local steps = 0
  local converged = false
  self.dt_gravity_ = dt * S_F_constants_GRAVITY
  if (self.evap_rate > 0.0) or self.any_conduit_seep_ then
    self.losses_all_zero_ = false
  end
  Algo_copy_IterT_IterT_IterT__D(self.area_mid_:begin(), self.area_mid_:end_(), self.area_old_:begin())
  if self.surcharge_method == 3 then
    O_Tdynwave_DWSolver.updateTpaLatch(self, ctx)
  end
  Algo_fill_IterT_IterT_T__B(self.bypassed_:begin(), self.bypassed_:end_(), 0)
  do
    local nd = ctx.nodes
    if self.node_tile_.n ~= self.n_nodes_ then
      self.node_tile_:resize_ul(self.n_nodes_)
    end
    self.unit_sys_ = F_ucf_getUnitSystem(ctx.options.flow_units)
    do
      local i = 0
      while i < self.n_nodes_ do
        do
          local ui = i
          local t = self.node_tile_.a[ui]
          t.full_depth = nd.full_depth.a[ui]
          t.y_crown = nd.crown_elev.a[ui] - nd.invert_elev.a[ui]
          t.invert_elev = nd.invert_elev.a[ui]
          t.ponded_area = nd.ponded_area.a[ui]
          t.sur_depth = nd.sur_depth.a[ui]
          t.full_volume = nd.full_volume.a[ui]
