    self.variable_step_ = min_route_step
    do return self.variable_step_ end
  end
  local dt_min = fixed_step
  local min_link = -1
  local min_node = -1
  do
    local j = 0
    while j < self.n_links_ do
      do
        local t = O_Tdynwave_DWSolver.getLinkStep(self, ctx, j)
        if (t <= 0.0) or (t > 1000000000.0) then
          goto cont1
        end
        t = t * courant_factor
        if t < dt_min then
          dt_min = t
          min_link = j
          min_node = -1
        end
      end
      ::cont1::
      j = j + 1
    end
  end
  do
    local i = 0
    while i < self.n_nodes_ do
      do
        local ui = i
        if ctx.nodes.type.a[ui] == 1 then
          goto cont2
        end
        if ctx.nodes.depth.a[ui] <= S_F_constants_FUDGE then
          goto cont2
        end
        local yCrown = ctx.nodes.crown_elev.a[ui] - ctx.nodes.invert_elev.a[ui]
        if (ctx.nodes.depth.a[ui] + S_F_constants_FUDGE) >= yCrown then
          goto cont2
        end
        local max_depth = yCrown * 0.25
        if max_depth < S_F_constants_FUDGE then
          goto cont2
        end
        local dYdT = self.xnode_.dYdT.a[ui]
        if dYdT < S_F_constants_FUDGE then
          goto cont2
        end
        local t_2 = max_depth / dYdT
        if (t_2 > 0.0) and (t_2 < dt_min) then
          dt_min = t_2
