              min_link = -1
            end
          end
        end
        ::cont3::
      end
    end
  end
  if min_node >= 0 then
    ctx.nodes.stat_time_courant_critical.a[min_node] = ctx.nodes.stat_time_courant_critical.a[min_node] + 1.0
  elseif min_link >= 0 then
    ctx.links.stat_time_courant_critical.a[min_link] = ctx.links.stat_time_courant_critical.a[min_link] + 1.0
  end
