    elseif min_link >= 0 then
      gov = R_Lit("link")
      nm = ctx.link_names.names_:at(min_link):c_str()
    elseif min_node >= 0 then
      gov = R_Lit("node")
      nm = ctx.node_names.names_:at(min_node):c_str()
