end
function O_Tdynwave_DWSolver.accumulateLinkStepStats(self, ctx, dt, fixed_step, courant_factor)
  local t_1, t_2
  if dt <= 0.0 then
    do return end
  end
  local cf = (courant_factor > 0.0) and courant_factor or 1.0
  local v_L = ctx.links
  do
    local j = 0
    while j < self.n_links_ do
      do
        local uj = j
        if v_L.type.a[uj] ~= 0 then
          goto cont1
        end
        local n1 = v_L.node1.a[uj]
        local n2 = v_L.node2.a[uj]
        local c1 = (self.node_tile_.a[n1].is_outfall ~= 0) or (self.xnode_.converged_f.a[n1] ~= 0)
        local c2 = (self.node_tile_.a[n2].is_outfall ~= 0) or (self.xnode_.converged_f.a[n2] ~= 0)
        v_L.stat_conv_total.a[uj] = v_L.stat_conv_total.a[uj] + 1
        if c1 and c2 then
          v_L.stat_conv_steps.a[uj] = v_L.stat_conv_steps.a[uj] + 1
        end
        local t = O_Tdynwave_DWSolver.getLinkStep(self, ctx, j)
        if (t <= 0.0) or (t > 1000000000.0) then
          goto cont1
        end
        t_2 = j
        t_1 = t * cf
        O_LinkData.add_lstep_sample(v_L, t_2, (fixed_step < t_1) and fixed_step or t_1, dt, fixed_step)
      end
      ::cont1::
      j = j + 1
    end
  end
end
