    local v___r1 = self.vjunc_
    do
      local v___i2_n = v___r1.n
      for v___i2 = 0, v___i2_n - 1 do
        do
          local p = v___r1.a[v___i2]
          do
            p.active_f = 0
            p.dirn = 0
            p.dq4j = 0.0
            if ((not (p.through ~= 0)) or (p.up_link < 0)) or (p.dn_link < 0) then
              goto cont1
            end
            if ((p.node >= 0) and L_ult(p.node, ctx.nodes.is_inlet.n)) and (ctx.nodes.is_inlet.a[p.node] ~= 0) then
              goto cont1
            end
            local uu = p.up_link
            local ud = p.dn_link
            local ucu = self.tile_uj_to_ci_.a[uu]
            local ucd = self.tile_uj_to_ci_.a[ud]
            local aj = self.area2_.a[uu]
            local wj = self.width2_.a[uu]
            if aj <= S_F_constants_FUDGE then
              goto cont1
            end
            local ajFull = links.xsect_a_full.a[uu]
            local qU = links.flow.a[uu] / self.tile_barrels_d_.a[ucu]
            local qD = links.flow.a[ud] / self.tile_barrels_d_.a[ucd]
            local vj = (0.5 * (qU + qD)) / F_dynwave_conveyArea_DynamicWave(aj, ajFull)
            if L_abs(vj) > S_F_constants_MAX_VELOCITY then
              vj = (vj > 0.0) and S_F_constants_MAX_VELOCITY or (-S_F_constants_MAX_VELOCITY)
            end
            local dh = (wj > S_F_constants_FUDGE) and (aj / wj) or 0.0
            local frj = (dh > 0.0) and (L_abs(vj) / L_sqrt(S_F_constants_GRAVITY * dh)) or 0.0
            t_1 = 2.0 * (1.0 - frj)
            t_2 = (t_1 < 1.0) and t_1 or 1.0
            p.sigma_j = (0.0 < t_2) and t_2 or 0.0
            p.a_up_mid = F_dynwave_conveyArea_DynamicWave(self.area_mid_.a[uu], ajFull)
            p.r_up_mid = self.hrad_mid_.a[uu]
            p.active_f = 1
            if ((qU >= 0.0) and (qD >= 0.0)) and ((qU + qD) > 0.0) then
              p.dirn = 1
            elseif ((qU <= 0.0) and (qD <= 0.0)) and ((qU + qD) < 0.0) then
              p.dirn = -1
            end
            if (full_momentum and (p.lambda > 0.0)) and (p.dirn ~= 0) then
