              local aMu = (t_1 < S_F_constants_FUDGE) and S_F_constants_FUDGE or t_1
              t_1 = self.area_mid_.a[ud]
              local aMd = (t_1 < S_F_constants_FUDGE) and S_F_constants_FUDGE or t_1
