            surfArea2 = ((wMsa + w2_2) * length) * 0.5
            self.depth1_.a[uj_3] = y1_2
            self.depth_mid_.a[uj_3] = yMid_2
            self.width_mid_.a[uj_3] = wM_2
            self.h1_.a[uj_3] = h1_2
            goto sw4
          end
        elseif fc == 6 then
          do
            y2_2 = cached_yC
            if cached_yN < cached_yC then
