            end
            y2_2 = (y2_2 < S_F_constants_FUDGE) and S_F_constants_FUDGE or y2_2
            local z2_elev_2 = inv2_2 + z2_off
            h2_2 = z2_elev_2 + y2_2
            t_1 = 0.5 * (y1_2 + y2_2)
            local yMid_3 = (t_1 < S_F_constants_FUDGE) and S_F_constants_FUDGE or t_1
            local w1_2 = self.width1_.a[uj_3]
            local xs_6 = xs_ref()
