            local wMsa_2 = 0.0
            local wSlotM_2 = O_Tdynwave_DWSolver.getSlotWidth(self, yMid_3, yf_3, self.tile_w_max_.a[uci_3], self.tile_shape_.a[uci_3])
            if wSlotM_2 > 0.0 then
              wMsa_2 = wSlotM_2
            elseif ((yMid_3 / yf_3) >= O_Tdynwave_DWSolver.getCrownCutoff(self)) and (not O_Txsect_XsectEval.isOpen(F_xsect_hostEval(), self.tile_xsect_batch_shape_.a[uci_3])) then
              wMsa_2 = F_xsect_getWofY(xs_6, O_Tdynwave_DWSolver.getCrownCutoff(self) * yf_3)
            else
              wMsa_2 = wM_3
            end
            surfArea1 = ((w1_2 + wMsa_2) * length) * 0.5
            self.depth2_.a[uj_3] = y2_2
            self.depth_mid_.a[uj_3] = yMid_3
            self.width_mid_.a[uj_3] = wM_3
            self.h2_.a[uj_3] = h2_2
            goto sw4
          end
        elseif fc == 1 then
          do
            y1_2 = S_F_constants_FUDGE
            t_1 = 0.5 * (S_F_constants_FUDGE + y2_2)
            local yMid_4 = (t_1 < S_F_constants_FUDGE) and S_F_constants_FUDGE or t_1
            local w1_3 = self.width1_.a[uj_3]
            local w2_3 = self.width2_.a[uj_3]
            local wM_4 = self.width_mid_.a[uj_3]
            surfArea2 = ((wM_4 + w2_3) * length) / 4.0
            if z1_off <= 0.0 then
              surfArea1 = ((w1_3 + wM_4) * length) / 4.0
            end
            self.depth1_.a[uj_3] = S_F_constants_FUDGE
            self.depth_mid_.a[uj_3] = yMid_4
            do
              local xs_7 = xs_ref()
              self.width_mid_.a[uj_3] = O_Txsect_XsectEval.getWofY(F_xsect_hostEval(), xs_7, yMid_4)
            end
            goto sw4
          end
        elseif fc == 2 then
          do
            y2_2 = S_F_constants_FUDGE
            t_1 = 0.5 * (y1_2 + S_F_constants_FUDGE)
            local yMid_5 = (t_1 < S_F_constants_FUDGE) and S_F_constants_FUDGE or t_1
            local w1_4 = self.width1_.a[uj_3]
            local w2_4 = self.width2_.a[uj_3]
            local wM_5 = self.width_mid_.a[uj_3]
            surfArea1 = ((wM_5 + w1_4) * length) / 4.0
            if z2_off <= 0.0 then
              surfArea2 = ((w2_4 + wM_5) * length) / 4.0
            end
            self.depth2_.a[uj_3] = S_F_constants_FUDGE
            self.depth_mid_.a[uj_3] = yMid_5
            do
              local xs_8 = xs_ref()
              self.width_mid_.a[uj_3] = O_Txsect_XsectEval.getWofY(F_xsect_hostEval(), xs_8, yMid_5)
            end
            goto sw4
          end
        elseif fc == 0 then
