end
function O_Tdynwave_DWSolver.recomputeConduitLossOne(self, ctx, dt, ci)
  local t_1, t_2
  local links = ctx.links
  local v_CD = ctx.link_subtypes.conduits
  local evap = self.evap_rate
  do
    local uci = ci
    local uj = self.conduit_idx_.a[uci]
    local u = uj
    local ucr = self.tile_crow_.a[uci]
    local fc = links.flow_class.a[u]
    if (((((fc == 0) or (fc == 1)) or (fc == 2)) or (self.area_mid_.a[u] <= S_F_constants_FUDGE)) or (self.tile_is_closed_.a[uci] ~= 0)) or (links.setting.a[u] == 0.0) then
      v_CD.evap_loss_rate.a[ucr] = 0.0
      v_CD.seep_loss_rate.a[ucr] = 0.0
      do return end
    end
    local depth = 0.5 * (links.old_depth.a[u] + links.depth.a[u])
    local evap_loss = 0.0
    local seep_loss = {0.0}
    if depth > S_F_constants_FUDGE then
      local length = v_CD.true_length.a[ucr]
      if length <= 0.0 then
        length = v_CD.length.a[ucr]
      end
      if length <= 0.0 then
        length = v_CD.mod_length.a[ucr]
      end
      local shape = links.xsect_batch_shape.a[u]
      local gw_two_way = (not (v_CD.gw_coupled.n == 0)) and (v_CD.gw_coupled.a[ucr] ~= 0)
      if gw_two_way then
        t_1, t_2 = v_CD.gw_kc.a, ucr
      else
        t_1, t_2 = v_CD.seep_rate.a, ucr
      end
      local k_seep = t_1[t_2]
      local wantEvap = O_Txsect_XsectEval.isOpen(F_xsect_hostEval(), shape) and (evap > 0.0)
      local wantSeep = k_seep > 0.0
      if wantEvap or wantSeep then
        local xs = F_dynwave_buildXSP_DynamicWave(ctx, u)
        if wantEvap then
          local topWidth = O_Txsect_XsectEval.getWofY(F_xsect_hostEval(), xs, depth)
          evap_loss = (topWidth * length) * evap
        end
        if wantSeep then
          local d_seep = depth
          if (shape ~= 3) and (d_seep >= xs.yw_max) then
            d_seep = xs.yw_max
          end
          local width = (shape == 3) and xs.w_max or O_Txsect_XsectEval.getWofY(F_xsect_hostEval(), xs, d_seep)
          seep_loss[1] = (k_seep * width) * length
          seep_loss[1] = seep_loss[1] * ctx.climate_state.infil_factor
          if gw_two_way then
            seep_loss[1] = seep_loss[1] * F_hydraulics_aquiferSeepFactor(depth, v_CD.gw_head_rel.a[ucr], v_CD.gw_dc.a[ucr])
            seep_loss[1] = F_hydraulics_capAquiferGain(seep_loss[1], v_CD.gw_gain_max.a[ucr])
          end
        end
      end
      t_1 = seep_loss[1]
      local total = evap_loss + ((t_1 < 0.0) and 0.0 or t_1)
      if total > 0.0 then
        local q = links.volume.a[u] / (dt * v_CD.barrels.a[ucr])
        if total > q then
          evap_loss = (evap_loss * q) / total
          if seep_loss[1] > 0.0 then
            seep_loss[1] = (seep_loss[1] * q) / total
          end
        end
      end
    end
    F_hydraulics_applySeepageForcing(ctx, u, seep_loss, 1)
    v_CD.evap_loss_rate.a[ucr] = evap_loss
    v_CD.seep_loss_rate.a[ucr] = seep_loss[1]
  end
end
function O_Tdynwave_DWSolver.limitConduitLosses(self, ctx, dt)
  local t_1, t_2
  local nodes = ctx.nodes
  local v_CD = ctx.link_subtypes.conduits
  local adjustable = function(j, r)
  local modes = ctx.forcing.link_seepage_mode
  do return ((not L_ult(j, modes.n)) or ((modes.a[j] ~= 1) and (modes.a[j] ~= 2))) and ((v_CD.evap_loss_rate.a[r] + v_CD.seep_loss_rate.a[r]) > 0.0) end
end
  Algo_fill_IterT_IterT_T__D(self.xnode_.conduit_loss:begin(), self.xnode_.conduit_loss:end_(), 0.0)
  do
    local ci = 0
    while ci < self.n_conduits_ do
      do
        local j_2 = self.tile_uj_.a[ci]
        local r_2 = self.tile_crow_.a[ci]
        if not adjustable(j_2, r_2) then
          goto cont1
        end
        local n1 = self.tile_n1_.a[ci]
        local n2 = self.tile_n2_.a[ci]
        local rate = (v_CD.evap_loss_rate.a[r_2] + v_CD.seep_loss_rate.a[r_2]) * self.tile_barrels_d_.a[ci]
        local share = ((not (self.node_tile_.a[n1].is_outfall ~= 0)) and (not (self.node_tile_.a[n2].is_outfall ~= 0))) and 0.5 or 1.0
        if not (self.node_tile_.a[n1].is_outfall ~= 0) then
          self.xnode_.conduit_loss.a[n1] = self.xnode_.conduit_loss.a[n1] + (share * rate)
        end
        if not (self.node_tile_.a[n2].is_outfall ~= 0) then
          self.xnode_.conduit_loss.a[n2] = self.xnode_.conduit_loss.a[n2] + (share * rate)
        end
      end
      ::cont1::
      ci = ci + 1
    end
  end
  do
    local i = 0
    while i < self.n_nodes_ do
      do
        self.xnode_.loss_factor.a[i] = 1.0
        local rate_2 = self.xnode_.conduit_loss.a[i]
        if (rate_2 <= 0.0) or (self.node_tile_.a[i].is_outfall ~= 0) then
          goto cont2
        end
        if nodes.storage_area.a[i] > 0.0 then
          t_2 = self.xnode_.new_surf_area.a[i]
        else
          t_1 = self.xnode_.new_surf_area.a[i]
          t_2 = (t_1 < self.min_surf_area_) and self.min_surf_area_ or t_1
        end
        local area = t_2
        t_1 = nodes.old_depth.a[i] - S_F_constants_FUDGE
        local storage_rate = (((0.0 < t_1) and t_1 or 0.0) * area) / dt
        if nodes.storage_area.a[i] > 0.0 then
          local volume = nodes.old_volume.a[i]
          do
            local k = self.csr_row_.a[i]
            while k < self.csr_row_.a[(((i + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000] do
              do
                local link = self.csr_link_.a[k]
                if (ctx.links.type.a[link] ~= 0) or (ctx.links.xsect_shape.a[link] == 25) then
                  goto cont3
                end
                volume = volume - F_dynwave_chamberPipeVolumeChange_DynamicWave(ctx, i, link, self.area1_.a[link], self.area2_.a[link], self.aa_y_prev_:data())
              end
              ::cont3::
              k = k + 1
            end
          end
          storage_rate = volume / dt
        end
        local net = (nodes.inflow.a[i] - nodes.outflow.a[i]) + rate_2
        t_1 = net + storage_rate
        t_2 = (net + nodes.old_net_inflow.a[i]) + (2.0 * storage_rate)
        local available = (t_2 < t_1) and t_2 or t_1
        t_1 = available / rate_2
        t_2 = (0.0 < t_1) and t_1 or 0.0
        self.xnode_.loss_factor.a[i] = (t_2 < 1.0) and t_2 or 1.0
      end
      ::cont2::
      i = i + 1
    end
  end
  do
    local ci_2 = 0
    while ci_2 < self.n_conduits_ do
      do
        local j_3 = self.tile_uj_.a[ci_2]
        local r_3 = self.tile_crow_.a[ci_2]
        if not adjustable(j_3, r_3) then
          goto cont4
        end
        local n1_2 = self.tile_n1_.a[ci_2]
        local n2_2 = self.tile_n2_.a[ci_2]
        t_1 = self.xnode_.loss_factor.a[n1_2]
        t_2 = self.xnode_.loss_factor.a[n2_2]
        local factor = (t_2 < t_1) and t_2 or t_1
        if factor >= 1.0 then
          goto cont4
        end
        local rate_3 = v_CD.evap_loss_rate.a[r_3] + v_CD.seep_loss_rate.a[r_3]
        t_2 = v_CD.evap_loss_rate.a[r_3]
        t_1 = v_CD.seep_loss_rate.a[r_3]
        local positive = t_2 + ((0.0 < t_1) and t_1 or 0.0)
        local scale = (v_CD.seep_loss_rate.a[r_3] >= 0.0) and factor or ((positive - (rate_3 * (1.0 - factor))) / positive)
        v_CD.evap_loss_rate.a[r_3] = v_CD.evap_loss_rate.a[r_3] * scale
        if v_CD.seep_loss_rate.a[r_3] > 0.0 then
          v_CD.seep_loss_rate.a[r_3] = v_CD.seep_loss_rate.a[r_3] * scale
        end
        local reduction = (rate_3 * self.tile_barrels_d_.a[ci_2]) * (1.0 - factor)
        local share_2 = ((not (self.node_tile_.a[n1_2].is_outfall ~= 0)) and (not (self.node_tile_.a[n2_2].is_outfall ~= 0))) and 0.5 or 1.0
        if not (self.node_tile_.a[n1_2].is_outfall ~= 0) then
          nodes.outflow.a[n1_2] = nodes.outflow.a[n1_2] - (share_2 * reduction)
        end
        if not (self.node_tile_.a[n2_2].is_outfall ~= 0) then
          nodes.outflow.a[n2_2] = nodes.outflow.a[n2_2] - (share_2 * reduction)
        end
      end
      ::cont4::
      ci_2 = ci_2 + 1
    end
  end
end
function O_Tdynwave_DWSolver.momentumKernels(self, ctx, dt, step)
  local links = ctx.links
  local static_slot_e = self.surcharge_method ~= 2
  local do_losses = not self.losses_all_zero_
  if not (self.vjunc_.n == 0) then
    O_Tdynwave_DWSolver.vjPrepareIteration(self, ctx, dt)
  end
  local solve_conduit = function(ci)
  local t_1
  local uci = ci
  local j = self.tile_uj_.a[uci]
  local uj = j
  self.new_flow_.a[uj] = links.flow.a[uj]
  if self.bypassed_.a[uj] ~= 0 then
    do return end
  end
  if do_losses then
    O_Tdynwave_DWSolver.recomputeConduitLossOne(self, ctx, dt, ci)
  end
  self.dqdh_.a[uj] = 0.0
  if static_slot_e then
    local yf = self.tile_y_full_.a[uci]
    local af = self.tile_a_full_.a[uci]
    local rf = self.tile_r_full_.a[uci]
    local wm = self.tile_w_max_.a[uci]
    local shape = self.tile_shape_.a[uci]
    if self.depth1_.a[uj] >= yf then
      self.area1_.a[uj] = af
      self.hrad1_.a[uj] = rf
    end
    if self.depth2_.a[uj] >= yf then
      self.area2_.a[uj] = af
    end
    if self.depth_mid_.a[uj] >= yf then
      self.area_mid_.a[uj] = af
      self.hrad_mid_.a[uj] = rf
    end
    if self.depth1_.a[uj] > yf then
      local wSlot = O_Tdynwave_DWSolver.getSlotWidth(self, self.depth1_.a[uj], yf, wm, shape)
      self.area1_.a[uj] = af + ((self.depth1_.a[uj] - yf) * wSlot)
      self.hrad1_.a[uj] = rf
    end
    if self.depth2_.a[uj] > yf then
      local wSlot_2 = O_Tdynwave_DWSolver.getSlotWidth(self, self.depth2_.a[uj], yf, wm, shape)
      self.area2_.a[uj] = af + ((self.depth2_.a[uj] - yf) * wSlot_2)
    end
    local yMid = self.depth_mid_.a[uj]
    if yMid > yf then
      local wSlot_3 = O_Tdynwave_DWSolver.getSlotWidth(self, yMid, yf, wm, shape)
      self.area_mid_.a[uj] = af + ((yMid - yf) * wSlot_3)
      if wSlot_3 > 0.0 then
        self.width_mid_.a[uj] = wSlot_3
      end
      self.hrad_mid_.a[uj] = rf
    end
  end
  local fc = links.flow_class.a[uj]
  local aMid = self.area_mid_.a[uj]
  local yf_c = self.tile_y_full_.a[uci]
  local isFull = (self.depth1_.a[uj] >= yf_c) and (self.depth2_.a[uj] >= yf_c)
  local cat = 0
  if (((((fc == 0) or (fc == 1)) or (fc == 2)) or (aMid <= S_F_constants_FUDGE)) or (self.tile_is_closed_.a[uci] ~= 0)) or (links.setting.a[uj] == 0.0) then
    cat = 0
  elseif (self.tile_is_force_main_.a[uci] ~= 0) and isFull then
    cat = (ctx.options.force_main_eqn == 1) and 5 or 4
  elseif (not (self.tile_is_open_.a[uci] ~= 0)) and isFull then
    cat = 3
  elseif self.tile_is_open_.a[uci] ~= 0 then
    cat = 1
  else
    cat = 2
  end
  self.category_.a[uj] = cat
  if cat == 0 then
    O_Tdynwave_DWSolver.processDryLink(self, ctx, dt, uj)
    goto sw1
  elseif cat == 1 or cat == 2 or cat == 3 then
    O_Tdynwave_DWSolver.processManningLink(self, ctx, dt, step, uj, cat)
    goto sw1
  elseif cat == 4 or cat == 5 then
    O_Tdynwave_DWSolver.processForceMainLink(self, ctx, dt, step, uj, cat)
    goto sw1
  else
    goto sw1
  end
  ::sw1::
  if (ctx.nodes.storage_area.a[links.node1.a[uj]] > 0.0) or (ctx.nodes.storage_area.a[links.node2.a[uj]] > 0.0) then
    local a1 = self.area1_.a[uj]
    local a2 = self.area2_.a[uj]
    t_1 = ctx.nodes.depth.a[links.node1.a[uj]] - links.offset1.a[uj]
    local y1 = (0.0 < t_1) and t_1 or 0.0
    t_1 = ctx.nodes.depth.a[links.node2.a[uj]] - links.offset2.a[uj]
    local y2 = (0.0 < t_1) and t_1 or 0.0
    if y1 < S_F_constants_FUDGE then
      a1 = F_dynwave_chamberEndArea_DynamicWave(ctx, ((uj + 0x80000000) & 0xFFFFFFFF) - 0x80000000, y1)
    end
    if y2 < S_F_constants_FUDGE then
      a2 = F_dynwave_chamberEndArea_DynamicWave(ctx, ((uj + 0x80000000) & 0xFFFFFFFF) - 0x80000000, y2)
    end
    links.volume.a[uj] = ((0.5 * (a1 + a2)) * self.tile_links_length_.a[uci]) * self.tile_barrels_d_.a[uci]
  end
  links.flow.a[uj] = self.new_flow_.a[uj]
  links.dqdh.a[uj] = self.dqdh_.a[uj]
  do return end
end
  if (self.unsteady_friction ~= 0) and (self.uf_k3 > 0.0) then
    do
      local ci_2 = 0
      while ci_2 < self.n_conduits_ do
        do
          solve_conduit(ci_2)
        end
        ci_2 = ci_2 + 1
      end
    end
  else
    do
      local ci_3 = 0
      while ci_3 < self.n_conduits_ do
        do
          solve_conduit(ci_3)
        end
        ci_3 = ci_3 + 1
      end
    end
  end
end
function O_Tdynwave_DWSolver.processDryLink(self, ctx, dt, uj)
  local t_1
  local links = ctx.links
  local dt_g = self.dt_gravity_
  local uci = self.tile_uj_to_ci_.a[uj]
  local aMid = self.area_mid_.a[uj]
  local barrels_d = self.tile_barrels_d_.a[uci]
  self.area_mid_.a[uj] = 0.5 * (self.area1_.a[uj] + self.area2_.a[uj])
  self.dqdh_.a[uj] = ((dt_g * aMid) / self.tile_length_.a[uci]) * barrels_d
  self.froude_.a[uj] = 0.0
  self.new_flow_.a[uj] = 0.0
  self.q1_.a[uj] = 0.0
  local yf = self.tile_y_full_.a[uci]
  t_1 = self.depth_mid_.a[uj]
  links.depth.a[uj] = (yf < t_1) and yf or t_1
  links.volume.a[uj] = (self.area_mid_.a[uj] * self.tile_links_length_.a[uci]) * barrels_d
end
function O_Tdynwave_DWSolver.processManningLink(self, ctx, dt, step, uj, cat)
  local t_1, t_2
  local links = ctx.links
  local v_CD = ctx.link_subtypes.conduits
  local inert_damping = ctx.options.inertial_damping
  local dt_g = self.dt_gravity_
  local is_closed_full = cat == 3
  local is_open_cat = cat == 1
  local uci = self.tile_uj_to_ci_.a[uj]
  local barrels_d = self.tile_barrels_d_.a[uci]
  local length = self.tile_length_.a[uci]
  local inv_len = self.tile_inv_length_.a[uci]
  local aMid = self.area_mid_.a[uj]
  local rMid = self.hrad_mid_.a[uj]
  local qLast = self.q1_.a[uj]
  local yf = self.tile_y_full_.a[uci]
  local isFull = (self.depth1_.a[uj] >= yf) and (self.depth2_.a[uj] >= yf)
