function O_Tdynwave_DWSolver.updateNodeFlows(self, ctx)
  local links = ctx.links
  local nodes = ctx.nodes
  do
    local j = 0
    while j < self.n_links_ do
      do
        local uj = j
        local accepted = F_boundSurfaceOutfallFlow(ctx, j, self.new_flow_.a[uj])
        if accepted ~= self.new_flow_.a[uj] then
          self.new_flow_.a[uj] = accepted
          ctx.links.dqdh.a[uj] = 0.0
          self.dqdh_.a[uj] = 0.0
        end
        links.flow.a[uj] = self.new_flow_.a[uj]
        local n1 = links.node1.a[uj]
        local n2 = links.node2.a[uj]
