        local un2 = n2
        local q = self.new_flow_.a[uj]
        if q >= 0.0 then
          nodes.outflow.a[un1] = nodes.outflow.a[un1] + q
          nodes.inflow.a[un2] = nodes.inflow.a[un2] + q
        else
          nodes.inflow.a[un1] = nodes.inflow.a[un1] - q
          nodes.outflow.a[un2] = nodes.outflow.a[un2] - q
        end
        self.xnode_.sumdqdh.a[un1] = self.xnode_.sumdqdh.a[un1] + self.dqdh_.a[uj]
        self.xnode_.sumdqdh.a[un2] = self.xnode_.sumdqdh.a[un2] + self.dqdh_.a[uj]
