          local ucr_l = self.tile_crow_.a[uci_l]
          local conduit_loss = (ctx.link_subtypes.conduits.evap_loss_rate.a[ucr_l] + ctx.link_subtypes.conduits.seep_loss_rate.a[ucr_l]) * self.tile_barrels_d_.a[uci_l]
