            if nodes.type.a[un1] ~= 1 then
              nodes.inflow.a[un1] = nodes.inflow.a[un1] + gain
            end
            if nodes.type.a[un2] ~= 1 then
              nodes.inflow.a[un2] = nodes.inflow.a[un2] + gain
            end
          elseif conduit_loss > 0.0 then
            if (nodes.type.a[un1] ~= 1) and (nodes.type.a[un2] ~= 1) then
              conduit_loss = conduit_loss / 2.0
            end
            if nodes.type.a[un1] ~= 1 then
              nodes.outflow.a[un1] = nodes.outflow.a[un1] + conduit_loss
            end
            if nodes.type.a[un2] ~= 1 then
              nodes.outflow.a[un2] = nodes.outflow.a[un2] + conduit_loss
            end
