        local b0 = self.csr_row_.a[un]
        local b1 = self.csr_row_.a[un + 1]
        if b0 == b1 then
          goto cont1
        end
        local self_outfall = self.node_tile_.a[un].is_outfall ~= 0
        local inflow = nodes.inflow.a[un]
        local outflow = nodes.outflow.a[un]
        local sumdqdh = self.xnode_.sumdqdh.a[un]
        local surf = self.xnode_.new_surf_area.a[un]
