              local at_n2 = self.csr_is_n2_.a[uk] ~= 0
              local uci = self.tile_uj_to_ci_.a[uj]
              local q = self.new_flow_.a[uj]
              if q >= 0.0 then
                if at_n2 then
                  inflow = inflow + q
                else
                  outflow = outflow + q
