              end
              sumdqdh = sumdqdh + self.dqdh_.a[uj]
              local ucr_g = self.tile_crow_.a[uci]
              local conduit_loss = (v_CD.evap_loss_rate.a[ucr_g] + v_CD.seep_loss_rate.a[ucr_g]) * self.tile_barrels_d_.a[uci]
