        self.area_mid_.a[uj] = v_A_total
        if y1 > yf then
          self.area1_.a[uj] = v_A_total
        end
        if y2 > yf then
          self.area2_.a[uj] = v_A_total
        end
        self.width_mid_.a[uj] = v_Ts
        local v_L = self.cached_length_.a[uj]
        local slot_surf_per_end = (0.25 * v_Ts) * v_L
        if y1 > yf then
          self.surf_area1_.a[uj] = slot_surf_per_end
        end
        if y2 > yf then
          self.surf_area2_.a[uj] = slot_surf_per_end
        end
        self.hrad_mid_.a[uj] = rf
      end
      ::cont1::
      ci = ci + 1
    end
  end
end
function O_Tdynwave_DWSolver.updateTpaLatch(self, ctx)
  local links = ctx.links
  local nodes = ctx.nodes
  local kCavHead = 30.0
  do
    local ci = 0
    while ci < self.n_conduits_ do
      do
        local uci = ci
        local j = self.conduit_idx_.a[uci]
        local uj = j
        self.tpa_latch_changed_.a[uci] = 0
        if self.is_open_.a[uj] ~= 0 then
          self.tpa_latch_.a[uci] = 0
          goto cont1
        end
        local yf = links.xsect_y_full.a[uj]
        if yf <= 0.0 then
          self.tpa_latch_.a[uci] = 0
          goto cont1
        end
        local y1 = self.depth1_.a[uj]
        local y2 = self.depth2_.a[uj]
        local old = self.tpa_latch_.a[uci]
        local latched = old
        if not (old ~= 0) then
          latched = ((y1 >= yf) and (y2 >= yf)) and 1 or 0
        else
          local yMid = self.depth_mid_.a[uj]
          if yMid < (yf - kCavHead) then
            latched = 0
          else
            local vented_end = function(n, y_end)
  if n < 0 then
    do return false end
  end
  local un2 = n
  local sealed = (L_ult(un2, nodes.is_virtual.n) and (nodes.is_virtual.a[un2] ~= 0)) or (L_ult(un2, nodes.sur_depth.n) and (nodes.sur_depth.a[un2] > 0.0))
  do return (not sealed) and (y_end < yf) end
end
            if vented_end(links.node1.a[uj], y1) or vented_end(links.node2.a[uj], y2) then
              latched = 0
            end
          end
        end
        self.tpa_latch_.a[uci] = latched
        self.tpa_latch_changed_.a[uci] = (latched ~= old) and 1 or 0
      end
      ::cont1::
      ci = ci + 1
    end
  end
end
function O_Tdynwave_DWSolver.applyTpaGeometry(self, ctx)
  local links = ctx.links
  do
    local ci = 0
    while ci < self.n_conduits_ do
      do
        local uci = ci
        local j = self.conduit_idx_.a[uci]
        local uj = j
        if self.is_open_.a[uj] ~= 0 then
          goto cont1
        end
        local yf = links.xsect_y_full.a[uj]
        local af = links.xsect_a_full.a[uj]
        local rf = links.xsect_r_full.a[uj]
        if (yf <= 0.0) or (af <= 0.0) then
          goto cont1
        end
        local w = self.tpa_w_.a[uci]
        if w <= 0.0 then
          goto cont1
        end
        local yMid = self.depth_mid_.a[uj]
        local engaged = (self.tpa_latch_.a[uci] ~= 0) or (yMid >= (S_F_constants_SLOT_CROWN_CUTOFF * yf))
        if not engaged then
          goto cont1
        end
        local line_area = function(y)
  local t_1, t_2
  t_1 = af + (w * (y - yf))
  t_2 = 0.05 * af
  do return (t_1 < t_2) and t_2 or t_1 end
end
        self.area_mid_.a[uj] = line_area(yMid)
        self.area1_.a[uj] = line_area(self.depth1_.a[uj])
        self.area2_.a[uj] = line_area(self.depth2_.a[uj])
        self.width_mid_.a[uj] = w
        local v_L = self.cached_length_.a[uj]
        local slot_surf_per_end = (0.25 * w) * v_L
        self.surf_area1_.a[uj] = slot_surf_per_end
        self.surf_area2_.a[uj] = slot_surf_per_end
        self.hrad_mid_.a[uj] = rf
      end
      ::cont1::
      ci = ci + 1
    end
  end
end
function O_Tdynwave_DWSolver.updateDPSState(self, ctx, dt)
  local links = ctx.links
  self.sim_time_ = self.sim_time_ + dt
  do
    local ci = 0
    while ci < self.n_conduits_ do
      do
        local j = self.conduit_idx_.a[ci]
        local uj = j
        local uci = ci
        if self.is_open_.a[uj] ~= 0 then
          goto cont1
        end
        local yf = links.xsect_y_full.a[uj]
        local was_surcharged = self.dps_.surcharged.a[uci] ~= 0
        local now_surcharged = (self.depth_mid_.a[uj] > yf) and (self.dps_.As.a[uci] > 0.0)
        if now_surcharged and (not was_surcharged) then
          self.dps_.t_s.a[uci] = self.sim_time_
        end
        if now_surcharged then
          local dt_surcharge = self.sim_time_ - self.dps_.t_s.a[uci]
          self.dps_.P_hat.a[uci] = ((self.dps_.P_hat_0.a[uci] - 1.0) * L_exp(((-10.0) * dt_surcharge) / self.dps_config_.r)) + 1.0
        else
          self.dps_.P_hat.a[uci] = self.dps_.P_hat_0.a[uci]
          self.dps_.As.a[uci] = 0.0
          self.dps_.hs.a[uci] = 0.0
          self.dps_.hs_prev_iter.a[uci] = 0.0
        end
        self.dps_.surcharged.a[uci] = (now_surcharged and 1 or 0) & 0xFF
      end
      ::cont1::
      ci = ci + 1
    end
  end
  O_Tdynwave_DWSolver.spatialSmoothP(self, ctx)
end
function O_Tdynwave_DWSolver.spatialSmoothP(self, ctx)
  local t_1, t_2, t_3
  local links = ctx.links
  local un = self.n_nodes_
  if not S_Tdynwave_DWSolver_S_node_P_sum_33_done then
    S_Tdynwave_DWSolver_S_node_P_sum_33 = NewVecD()
    S_Tdynwave_DWSolver_S_node_P_sum_33_done = true
  end
  if not S_Tdynwave_DWSolver_S_node_P_count_34_done then
    S_Tdynwave_DWSolver_S_node_P_count_34 = NewVecI()
    S_Tdynwave_DWSolver_S_node_P_count_34_done = true
  end
  S_Tdynwave_DWSolver_S_node_P_sum_33:assign_ul_T(un, 0.0)
  S_Tdynwave_DWSolver_S_node_P_count_34:assign_ul_T(un, 0)
  do
    local ci = 0
    while ci < self.n_conduits_ do
      do
        local j = self.conduit_idx_.a[ci]
        local uj = j
        local uci = ci
        if self.is_open_.a[uj] ~= 0 then
          goto cont1
        end
        local n1 = links.node1.a[uj]
        local n2 = links.node2.a[uj]
        if (n1 >= 0) and (n1 < self.n_nodes_) then
          S_Tdynwave_DWSolver_S_node_P_sum_33.a[n1] = S_Tdynwave_DWSolver_S_node_P_sum_33.a[n1] + self.dps_.P_hat.a[uci]
          t_1 = S_Tdynwave_DWSolver_S_node_P_count_34.a[n1]
          S_Tdynwave_DWSolver_S_node_P_count_34.a[n1] = (((t_1 + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
          t_2, t_3 = {0}, 1
          t_2[t_3] = t_1
        end
        if (n2 >= 0) and (n2 < self.n_nodes_) then
          S_Tdynwave_DWSolver_S_node_P_sum_33.a[n2] = S_Tdynwave_DWSolver_S_node_P_sum_33.a[n2] + self.dps_.P_hat.a[uci]
          t_1 = S_Tdynwave_DWSolver_S_node_P_count_34.a[n2]
          S_Tdynwave_DWSolver_S_node_P_count_34.a[n2] = (((t_1 + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
          t_2, t_3 = {0}, 1
          t_2[t_3] = t_1
        end
      end
      ::cont1::
      ci = ci + 1
    end
  end
  do
    local ci_2 = 0
    while ci_2 < self.n_conduits_ do
      do
        local j_2 = self.conduit_idx_.a[ci_2]
        local uj_2 = j_2
        local uci_2 = ci_2
        if self.is_open_.a[uj_2] ~= 0 then
          goto cont2
        end
        local n1_2 = links.node1.a[uj_2]
        local n2_2 = links.node2.a[uj_2]
        local v_P_face1 = self.dps_.P_hat.a[uci_2]
        local v_P_face2 = self.dps_.P_hat.a[uci_2]
        if ((n1_2 >= 0) and (n1_2 < self.n_nodes_)) and (S_Tdynwave_DWSolver_S_node_P_count_34.a[n1_2] > 0) then
          v_P_face1 = S_Tdynwave_DWSolver_S_node_P_sum_33.a[n1_2] / S_Tdynwave_DWSolver_S_node_P_count_34.a[n1_2]
        end
        if ((n2_2 >= 0) and (n2_2 < self.n_nodes_)) and (S_Tdynwave_DWSolver_S_node_P_count_34.a[n2_2] > 0) then
          v_P_face2 = S_Tdynwave_DWSolver_S_node_P_sum_33.a[n2_2] / S_Tdynwave_DWSolver_S_node_P_count_34.a[n2_2]
        end
        self.dps_.P.a[uci_2] = 0.5 * (v_P_face1 + v_P_face2)
        t_1 = self.dps_.P.a[uci_2]
        self.dps_.P.a[uci_2] = (t_1 < 1.0) and 1.0 or t_1
      end
      ::cont2::
      ci_2 = ci_2 + 1
    end
  end
end
