function O_Tdynwave_DWSolver.lastConverged(self)
  do return self.last_converged_ end
end
function O_Tdynwave_DWSolver.isInitialized(self)
  do return not (self.xnode_.sumdqdh.n == 0) end
end
function O_Tdynwave_DWSolver.nodeNewSurfAreaDataMut(self)
  do return self.xnode_.new_surf_area:data() end
end
function O_Tdynwave_DWSolver.isBypassed(self, j)
  local uj = j
  do return L_ult(uj, self.bypassed_.n) and (self.bypassed_.a[uj] ~= 0) end
end
function O_Tdynwave_DWSolver.nodeSumDqdh(self, n)
  do return self.xnode_.sumdqdh.a, n end
end

