-- ---- O_Texfil_ExfilSolver
O_Texfil_ExfilSolver = lua_class("Texfil_ExfilSolver", nil, {Cpp_ICopy})
function O_Texfil_ExfilSolver._new() return L_setmetatable({}, O_Texfil_ExfilSolver) end
function O_Texfil_ExfilSolver.init(self, ctx)
  local nodes = ctx.nodes
  local n_nodes = ((nodes.type.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local n_exfil = 0
  do
    local i = 0
    while i < n_nodes do
      do
        local ui = i
        local sr = O_NodeSubtypes.storage_row(ctx.node_subtypes, i)
        local ksat = (sr >= 0) and F_lidnode_bottomConductivity(ctx, sr) or 0.0
        if (nodes.type.a[ui] == 3) and (ksat > 0.0) then
          n_exfil = (((n_exfil + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        end
      end
      i = i + 1
    end
  end
  if n_exfil == 0 then
    self.soa_.count_f = 0
    do return end
  end
  O_Texfil_ExfilSoA.resize(self.soa_, n_exfil)
  local v_BIG = 10000000000.0
  local k = 0
  do
    local i_2 = 0
    while i_2 < n_nodes do
      do
        local ui_2 = i_2
        local sr_2 = O_NodeSubtypes.storage_row(ctx.node_subtypes, i_2)
        local exf_suction = (sr_2 >= 0) and ctx.node_subtypes.storages.exfil_suction.a[sr_2] or 0.0
        local exf_ksat = (sr_2 >= 0) and F_lidnode_bottomConductivity(ctx, sr_2) or 0.0
        local exf_imd = (sr_2 >= 0) and ctx.node_subtypes.storages.exfil_imd.a[sr_2] or 0.0
        if (nodes.type.a[ui_2] ~= 3) or (exf_ksat <= 0.0) then
          goto cont2
        end
        local uk = k
        self.soa_.node_idx.a[uk] = i_2
        F_infil_grnampt_init(self.soa_.btm_ga.a[uk], exf_suction, exf_ksat, exf_imd, ctx.options)
        F_infil_grnampt_init(self.soa_.bank_ga.a[uk], exf_suction, exf_ksat, exf_imd, ctx.options)
        local curve_idx = (sr_2 >= 0) and ctx.node_subtypes.storages.curve.a[sr_2] or (-1)
        if curve_idx >= 0 then
          local curve = ctx.tables.tables.a[curve_idx]
          self.soa_.btm_area.a[uk] = F_table_lookupEx(curve, 0.0)
          self.soa_.bank_min_depth.a[uk] = 0.0
          self.soa_.bank_max_depth.a[uk] = 0.0
          self.soa_.bank_max_area.a[uk] = 0.0
          if not (curve.x.n == 0) then
            local alast = curve.y.a[0]
            do
              local ci = 1
              while L_ult(ci, curve.x.n) do
                do
                  local d = curve.x.a[ci]
                  local a = curve.y.a[ci]
                  if a < alast then
                    break
                  elseif a > alast then
                    self.soa_.bank_max_area.a[uk] = a
                    self.soa_.bank_max_depth.a[uk] = d
                  elseif self.soa_.bank_max_area.a[uk] == 0.0 then
                    self.soa_.bank_min_depth.a[uk] = d
                  else
                    break
                  end
                  alast = a
                end
                ci = ci + 1
              end
            end
          end
          do
            local ucf_len = F_ucf_UCF(3, ctx.options)
            self.soa_.btm_area.a[uk] = self.soa_.btm_area.a[uk] / (ucf_len * ucf_len)
            self.soa_.bank_max_area.a[uk] = self.soa_.bank_max_area.a[uk] / (ucf_len * ucf_len)
            self.soa_.bank_min_depth.a[uk] = self.soa_.bank_min_depth.a[uk] / ucf_len
            self.soa_.bank_max_depth.a[uk] = self.soa_.bank_max_depth.a[uk] / ucf_len
          end
        else
          local a_coeff = (sr_2 >= 0) and ctx.node_subtypes.storages.a.a[sr_2] or 0.0
          local b_coeff = (sr_2 >= 0) and ctx.node_subtypes.storages.b.a[sr_2] or 0.0
          local c_coeff = (sr_2 >= 0) and ctx.node_subtypes.storages.c.a[sr_2] or 0.0
          local sshape = (sr_2 >= 0) and ctx.node_subtypes.storages.shape.a[sr_2] or 1
          local btm = c_coeff
          if (((sshape == 2) or (sshape == 3)) or (sshape == 4)) or (sshape == 5) then
          elseif b_coeff == 0.0 then
            btm = btm + a_coeff
          end
          self.soa_.btm_area.a[uk] = btm
          self.soa_.bank_min_depth.a[uk] = 0.0
          self.soa_.bank_max_depth.a[uk] = v_BIG
          self.soa_.bank_max_area.a[uk] = v_BIG
        end
        k = (((k + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
      end
      ::cont2::
      i_2 = i_2 + 1
    end
  end
end
function O_Texfil_ExfilSolver.computeAll(self, ctx, dt)
  local t_1
  local nodes = ctx.nodes
  do
    local k = 0
    while k < self.soa_.count_f do
      do
        local uk = k
        local ni = self.soa_.node_idx.a[uk]
        if ni < 0 then
          goto cont1
        end
        local uni = ni
        if F_lidnode_richardsMode(ctx, ni) or (F_lidnode_bottomMode(ctx, ni) ~= 0) then
          ctx.node_subtypes.storages.exfil_rate.a[O_NodeSubtypes.storage_row(ctx.node_subtypes, ni)] = 0.0
          goto cont1
        end
        if L_ult(uni, nodes.aquifer2d_bed.n) and (nodes.aquifer2d_bed.a[uni] ~= 0) then
          local sr0 = O_NodeSubtypes.storage_row(ctx.node_subtypes, ni)
          if sr0 >= 0 then
            ctx.node_subtypes.storages.exfil_rate.a[sr0] = 0.0
          end
          goto cont1
        end
        local depth = nodes.depth.a[uni]
        local total_loss = 0.0
        local infil_factor = ctx.climate_state.infil_factor
        local recovery_factor = ctx.climate_state.recovery_factor
        local ga_rate = function(ga, d)
  if ga.IMDmax == 0.0 then
    do return ga.Ks * infil_factor end
  end
  do return F_infil_grnampt_getInfil(ga, 0.0, d, dt, 3, infil_factor, recovery_factor) end
end
        total_loss = total_loss + ((ga_rate(self.soa_.btm_ga.a[uk], depth) * self.soa_.btm_area.a[uk]) * F_lidnode_bottomCloggingFactor(ctx, O_NodeSubtypes.storage_row(ctx.node_subtypes, ni)))
        if depth > self.soa_.bank_min_depth.a[uk] then
          local area = F_node_getSurfArea(ctx.nodes, self.soa_.node_idx.a[uk], depth, ctx.tables, F_ucf_getUnitSystem(ctx.options.flow_units), ctx.node_subtypes)
          t_1 = self.soa_.bank_max_area.a[uk]
          area = ((t_1 < area) and t_1 or area) - self.soa_.btm_area.a[uk]
          if area > 0.0 then
            local bank_depth = depth
            if self.soa_.bank_ga.a[uk].IMDmax ~= 0.0 then
              if depth > self.soa_.bank_max_depth.a[uk] then
                bank_depth = (depth - self.soa_.bank_max_depth.a[uk]) + ((self.soa_.bank_max_depth.a[uk] - self.soa_.bank_min_depth.a[uk]) / 2.0)
              else
                bank_depth = (depth - self.soa_.bank_min_depth.a[uk]) / 2.0
              end
            end
            total_loss = total_loss + (area * ga_rate(self.soa_.bank_ga.a[uk], bank_depth))
          end
        end
        local sr = O_NodeSubtypes.storage_row(ctx.node_subtypes, ((uni + 0x80000000) & 0xFFFFFFFF) - 0x80000000)
        if sr >= 0 then
          ctx.node_subtypes.storages.exfil_rate.a[sr] = total_loss
        end
      end
      ::cont1::
      k = k + 1
    end
  end
end
