-- ---- O_Thydstruct_StructureSolver
O_Thydstruct_StructureSolver = lua_class("Thydstruct_StructureSolver", nil, {Cpp_ICopy})
function O_Thydstruct_StructureSolver._new() return L_setmetatable({}, O_Thydstruct_StructureSolver) end
function O_Thydstruct_StructureSolver.init(self, ctx)
  local t_1
  local n_pumps = 0
  local n_orifices = 0
  local n_weirs = 0
  local n_outlets = 0
  do
    local j = 0
    while j < (((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local uj = j
        t_1 = ctx.links.type.a[uj]
        if t_1 == 1 then
          n_pumps = (((n_pumps + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
          goto sw2
        elseif t_1 == 2 then
          n_orifices = (((n_orifices + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
          goto sw2
        elseif t_1 == 3 then
          n_weirs = (((n_weirs + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
          goto sw2
        elseif t_1 == 4 then
          n_outlets = (((n_outlets + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
          goto sw2
        else
          goto sw2
        end
        ::sw2::
      end
      j = j + 1
    end
  end
  O_Thydstruct_PumpGroup.resize(self.pumps_, n_pumps)
  O_Thydstruct_OrificeGroup.resize(self.orifices_, n_orifices)
  O_Thydstruct_WeirGroup.resize(self.weirs_, n_weirs)
  O_Thydstruct_OutletGroup.resize(self.outlets_, n_outlets)
  local ip = 0
  local v_io = 0
  local iw = 0
  local ix = 0
  do
    local j_2 = 0
    while j_2 < (((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local uj_2 = j_2
        t_1 = ctx.links.type.a[uj_2]
        if t_1 == 1 then
          do
            local uk = ip
            local v_P = ctx.link_subtypes.pumps
            local pr = O_LinkSubtypes.row_in(ctx.link_subtypes, j_2, ctx.link_subtypes.pumps.link_idx)
            self.pumps_.link_idx.a[uk] = j_2
            self.pumps_.curve_idx.a[uk] = v_P.curve.a[pr]
