function O_Thydstruct_StructureSolver.updatePumpTargetSettings(self, ctx)
  local links = ctx.links
  local nodes = ctx.nodes
  do
    local k = 0
    while k < self.pumps_.count_f do
      do
        local uk = k
        local j = self.pumps_.link_idx.a[uk]
        local uj = j
        local n1 = links.node1.a[uj]
        if n1 < 0 then
          goto cont1
        end
        local un1 = n1
        links.target_setting.a[uj] = links.setting.a[uj]
        local depth = nodes.depth.a[un1]
        local y_off = self.pumps_.y_off.a[uk]
        local y_on = self.pumps_.y_on.a[uk]
        if ((y_off > 0.0) and (links.setting.a[uj] > 0.0)) and (depth < y_off) then
          links.target_setting.a[uj] = 0.0
        end
        if ((y_on > 0.0) and (links.setting.a[uj] == 0.0)) and (depth > y_on) then
          links.target_setting.a[uj] = 1.0
        end
      end
      ::cont1::
      k = k + 1
    end
  end
end
function O_Thydstruct_StructureSolver.computeNonConduitFlowOne(self, ctx, dt, node_new_surf_area, link_idx)
  local t_1
  local uj = link_idx
  if ctx.links.type.a[uj] == 0 then
    ctx.links.dqdh.a[uj] = 0.0
    local q = 0.0
    if ctx.links.setting.a[uj] ~= 0.0 then
      local n1 = ctx.links.node1.a[uj]
      if n1 >= 0 then
        local un1 = n1
        if ctx.nodes.type.a[un1] == 2 then
          q = F_divider_getOutflow(ctx, n1, link_idx)
        else
          q = ctx.nodes.inflow.a[un1] + ctx.nodes.overflow.a[un1]
        end
      end
      local qlim = ctx.links.q_limit.a[uj]
      if (qlim > 0.0) and (q > qlim) then
        q = qlim
      end
    end
    ctx.links.flow.a[uj] = q
    do return end
  end
  local k = L_ult(uj, self.nc_group_k_.n) and self.nc_group_k_.a[uj] or (-1)
  if k < 0 then
    do return end
  end
  ctx.links.dqdh.a[uj] = 0.0
  t_1 = ctx.links.type.a[uj]
  if t_1 == 1 then
    O_Thydstruct_StructureSolver.computePumpFlowK(self, ctx, dt, node_new_surf_area, k)
    goto sw1
  elseif t_1 == 2 then
    O_Thydstruct_StructureSolver.computeOrificeFlowK(self, ctx, node_new_surf_area, k)
    goto sw1
  elseif t_1 == 3 then
    O_Thydstruct_StructureSolver.computeWeirFlowK(self, ctx, node_new_surf_area, k)
    goto sw1
  elseif t_1 == 4 then
    O_Thydstruct_StructureSolver.computeOutletFlowK(self, ctx, k)
    goto sw1
  else
    goto sw1
  end
  ::sw1::
end
function O_Thydstruct_StructureSolver.scatterHeldSurfArea(self, ctx, node_new_surf_area, link_idx)
  local uj = link_idx
  if ctx.links.type.a[uj] ~= 2 then
    do return end
  end
  local k = L_ult(uj, self.nc_group_k_.n) and self.nc_group_k_.a[uj] or (-1)
  if k < 0 then
    do return end
  end
  local n1 = ctx.links.node1.a[uj]
  local n2 = ctx.links.node2.a[uj]
  if (n1 < 0) or (n2 < 0) then
    do return end
  end
  O_Thydstruct_StructureSolver.scatterOrificeSurfArea(self, ctx, node_new_surf_area, k, uj, n1, n2)
