function O_Thydstruct_StructureSolver.computePumpFlowK(self, ctx, dt, node_new_surf_area, k)
  local t_1, t_2
  local links = ctx.links
  local nodes = ctx.nodes
  local fu = ctx.options.flow_units
  local ucf_flow = S_F_ucf_Qcf_UnitConversion[fu]
  local unit_sys = F_ucf_getUnitSystem(fu)
  local ucf_len = S_F_ucf_Ucf_UnitConversion[3][unit_sys]
  local ucf_vol = S_F_ucf_Ucf_UnitConversion[5][unit_sys]
  do
    local uk = k
    local j = self.pumps_.link_idx.a[uk]
    local uj = j
    local n1 = links.node1.a[uj]
    local n2 = links.node2.a[uj]
    if (n1 < 0) or (n2 < 0) then
      links.flow.a[uj] = 0.0
      do return end
    end
    local un1 = n1
    local un2 = n2
    local depth = nodes.depth.a[un1]
    local head = (nodes.depth.a[un2] + nodes.invert_elev.a[un2]) - (nodes.depth.a[un1] + nodes.invert_elev.a[un1])
    links.setting.a[uj] = links.target_setting.a[uj]
    links.flow_class.a[uj] = 0
    if links.setting.a[uj] == 0.0 then
      links.flow.a[uj] = 0.0
      do return end
    end
    local q = 0.0
    local ct = self.pumps_.curve_type.a[uk]
    local ci = self.pumps_.curve_idx.a[uk]
    local uci = ci
    if ct == 1 then
      if (ci >= 0) and L_ult(uci, ctx.tables.tables.n) then
        local vol = nodes.volume.a[un1] * ucf_vol
        q = F_table_intervalLookup(ctx.tables.tables.a[uci], vol)
      end
      goto sw1
    elseif ct == 2 then
      if (ci >= 0) and L_ult(uci, ctx.tables.tables.n) then
        q = F_table_intervalLookup(ctx.tables.tables.a[uci], depth * ucf_len)
      end
      goto sw1
    elseif ct == 3 or ct == 5 then
      do
        local s = (ct == 5) and links.setting.a[uj] or 1.0
