          t_1 = head / (s * s)
          t_2 = (t_1 < 0.0) and 0.0 or t_1
        else
          t_2 = 0.0
        end
        local h = t_2
        if (ci >= 0) and L_ult(uci, ctx.tables.tables.n) then
          local curve = ctx.tables.tables.a[uci]
          q = F_table_lookup_cursor(curve, h * ucf_len)
          if s > 0.0 then
            local slope = F_table_getSlope(curve, h * ucf_len)
            links.dqdh.a[uj] = (((-slope) * ucf_len) / ucf_flow) / s
          end
        end
        goto sw1
      end
    elseif ct == 4 then
      if (ci >= 0) and L_ult(uci, ctx.tables.tables.n) then
        q = F_table_lookup_cursor(ctx.tables.tables.a[uci], depth * ucf_len)
        local dh = 0.001
        local q1 = F_table_lookup_cursor(ctx.tables.tables.a[uci], (depth + dh) * ucf_len)
        links.dqdh.a[uj] = (q1 - q) / (dh * ucf_flow)
      end
      goto sw1
    elseif ct == 6 then
      q = nodes.inflow.a[un1] + nodes.overflow.a[un1]
      goto sw1
    end
    ::sw1::
    if (((ci >= 0) and L_ult(uci, ctx.tables.tables.n)) and (ct >= 1)) and (ct <= 5) then
      local x = ctx.tables.tables.a[uci].x
      if not (x.n == 0) then
        local argument = depth * ucf_len
        if ct == 1 then
          argument = nodes.volume.a[un1] * ucf_vol
        end
        if (ct == 3) or (ct == 5) then
          local speed = (ct == 5) and links.setting.a[uj] or 1.0
          t_1 = head / (speed * speed)
          argument = ((t_1 < 0.0) and 0.0 or t_1) * ucf_len
        end
        if (argument < x:front()) or (argument > x:back()) then
          links.flow_class.a[uj] = ((ct == 4) and (argument < x:front())) and 2 or 1
        end
      end
    end
    q = (q < 0.0) and 0.0 or q
    if ct ~= 6 then
      q = q / ucf_flow
    end
    q = q * links.setting.a[uj]
    if q > 0.0 then
      if ((nodes.type.a[un1] == 3) or (nodes.storage_area.a[un1] > 0.0)) or (self.pumps_.curve_type.a[uk] == 1) then
        if ctx.options.routing_model == 2 then
          t_1, t_2 = nodes.rpt_full_volume.a, un1
        else
          t_1, t_2 = nodes.full_volume.a, un1
        end
        local full_vol = t_1[t_2]
        if full_vol > 0.0 then
          local max_q = nodes.inflow.a[un1] + (nodes.old_volume.a[un1] / dt)
          if q > max_q then
            q = max_q
          end
        end
        if q < 0.0 then
          q = 0.0
        end
      elseif ((ct == 2) or (ct == 3)) or (ct == 4) then
        local net_inflow = (nodes.inflow.a[un1] - nodes.outflow.a[un1]) - q
        local net_vol = (0.5 * (nodes.old_net_inflow.a[un1] + net_inflow)) * dt
        if PtrD_op_Ne(node_new_surf_area, PtrD_ZERO) then
          t_1, t_2 = node_new_surf_area.a, node_new_surf_area.o + un1
        else
          t_1, t_2 = _ENV, "S_F_constants_MIN_SURFAREA"
        end
        local surf = t_1[t_2]
        local y_new = nodes.old_depth.a[un1] + (net_vol / surf)
        if y_new <= 0.0 then
          t_1 = nodes.inflow.a[un1]
          q = (t_1 < 0.0) and 0.0 or t_1
        end
      end
    end
    links.flow.a[uj] = q
  end
end
function O_Thydstruct_StructureSolver.computeOrificeFlowK(self, ctx, node_new_surf_area, k)
  local t_1
  local links = ctx.links
  local nodes = ctx.nodes
  local v_FUDGE_ORI = 0.0001
  do
    local uk = k
    local j = self.orifices_.link_idx.a[uk]
    local uj = j
    local n1 = links.node1.a[uj]
    local n2 = links.node2.a[uj]
    if (n1 < 0) or (n2 < 0) then
      links.flow.a[uj] = 0.0
      do return end
    end
    local un1 = n1
    local un2 = n2
    local setting = links.setting.a[uj]
    local y_full = links.xsect_y_full.a[uj]
    local cd_val = ctx.link_subtypes.orifices.cd.a[O_LinkSubtypes.row_in(ctx.link_subtypes, j, ctx.link_subtypes.orifices.link_idx)]
    local h_open = setting * y_full
    if setting == 0.0 then
      links.flow.a[uj] = 0.0
      O_Thydstruct_StructureSolver.scatterOrificeSurfArea(self, ctx, node_new_surf_area, uk, uj, un1, un2)
      do return end
    end
    local xs = F_hydstruct_buildXSP_HydStructures(ctx, uj)
    local a_eff = O_Txsect_XsectEval.getAofY(F_xsect_hostEval(), xs, h_open)
    local f_area = a_eff * L_sqrt(2.0 * S_F_constants_GRAVITY)
    local cOrif = cd_val * f_area
    local is_side = ctx.link_subtypes.orifices.orifice_type.a[O_LinkSubtypes.row_in(ctx.link_subtypes, j, ctx.link_subtypes.orifices.link_idx)] > 0.5
    local hCrit = 0.0
    local cWeir = 0.0
    if not is_side then
      local aOverL = 0.0
      if links.xsect_shape.a[uj] == 0 then
        aOverL = h_open / 4.0
      else
        local w = links.xsect_w_max.a[uj]
        aOverL = ((w > 0.0) and (h_open > 0.0)) and ((h_open * w) / (2.0 * (h_open + w))) or (h_open / 4.0)
      end
      hCrit = (cd_val / 0.414) * aOverL
      cWeir = (cd_val * L_sqrt(hCrit)) * f_area
    else
      hCrit = h_open
      cWeir = (cd_val * L_sqrt(h_open / 2.0)) * f_area
    end
    hCrit = (hCrit < v_FUDGE_ORI) and v_FUDGE_ORI or hCrit
    local h1 = {nodes.depth.a[un1] + nodes.invert_elev.a[un1]}
    local h2 = {F_hydstruct_tailwaterHead_HydStructures(ctx, un1, un2)}
    local dir = (h1[1] >= h2[1]) and 1.0 or (-1.0)
    local y1 = nodes.depth.a[un1]
    if dir < 0.0 then
      Std_swap__D(h1, 1, h2, 1)
      y1 = nodes.depth.a[un2]
    end
    local hcrest = nodes.invert_elev.a[un1] + links.offset1.a[uj]
    local hcrown = 0.0
    local head = 0.0
    local f = 0.0
    if not is_side then
      if h1[1] < hcrest then
        head = 0.0
      elseif h2[1] > hcrest then
        head = h1[1] - h2[1]
      else
        head = h1[1] - hcrest
