    if (head <= v_FUDGE_ORI) or (y1 <= v_FUDGE_ORI) then
      links.flow.a[uj] = 0.0
      links.depth.a[uj] = 0.0
      links.dqdh.a[uj] = 0.0
      links.flow_class.a[uj] = 0
      self.orifices_.surf_area.a[uk] = v_FUDGE_ORI * self.orifices_.length_eff.a[uk]
      O_Thydstruct_StructureSolver.scatterOrificeSurfArea(self, ctx, node_new_surf_area, uk, uj, un1, un2)
      do return end
    end
    if F_hydstruct_flapGateBlocks(ctx, j, n1, n2, dir) then
      links.flow.a[uj] = 0.0
      links.depth.a[uj] = 0.0
      links.dqdh.a[uj] = 0.0
      links.flow_class.a[uj] = 0
      self.orifices_.surf_area.a[uk] = v_FUDGE_ORI * self.orifices_.length_eff.a[uk]
      O_Thydstruct_StructureSolver.scatterOrificeSurfArea(self, ctx, node_new_surf_area, uk, uj, un1, un2)
      do return end
