    if hcrest > h2[1] then
      links.flow_class.a[uj] = (dir > 0.0) and 6 or 5
    else
      links.flow_class.a[uj] = 3
    end
    local y_link = y_full * setting
    if is_side then
      local link_depth = y_link * ((f < 0.0) and 0.0 or f)
      links.depth.a[uj] = link_depth
      local width_at_depth = O_Txsect_XsectEval.getWofY(F_xsect_hostEval(), xs, link_depth)
      self.orifices_.surf_area.a[uk] = width_at_depth * self.orifices_.length_eff.a[uk]
    else
      links.depth.a[uj] = y_link
      self.orifices_.surf_area.a[uk] = O_Txsect_XsectEval.getAofY(F_xsect_hostEval(), xs, y_link)
