      local veloc = q / a_eff
      local hLoss = (((4.0 / S_F_constants_GRAVITY) * veloc) * veloc) * L_exp(((-1.15) * veloc) / L_sqrt(head))
      if f < 1.0 then
        f = f - (hLoss / hCrit)
        f = (f < 0.0) and 0.0 or f
      else
        head = head - hLoss
        head = (head < 0.0) and 0.0 or head
      end
      if (f <= 0.0) or (head <= 0.0) then
