        dqdh = 0.0
      elseif f < 1.0 then
        q = cWeir * L_pow(f, 1.5)
        dqdh = (1.5 * q) / (f * hCrit)
      else
        q = cOrif * L_sqrt(head)
        dqdh = q / (2.0 * head)
      end
