      local p = R_getenv(R_Lit("SWMM_TRACE_ORIF"))
      local tr = R_getenv(R_Lit("SWMM_TRACE_RSTEP"))
      local ls = R_getenv(R_Lit("SWMM_TRACE_LSTEP"))
      S_Thydstruct_StructureSolver_S_of_target_46 = -1
      if (not ls:get_IsNull()) and (ls:get(0) ~= 0) then
