function O_Thydstruct_StructureSolver.computeWeirFlowK(self, ctx, node_new_surf_area, k)
  local t_2
  local links = ctx.links
  local nodes = ctx.nodes
  local v_FUDGE_W = 0.0001
  do
    local uk = k
    local j = self.weirs_.link_idx.a[uk]
    local uj = j
    local n1 = links.node1.a[uj]
    local n2 = links.node2.a[uj]
    if (n1 < 0) or (n2 < 0) then
      links.flow.a[uj] = 0.0
