    local dir = (hgl1[1] >= hgl2[1]) and 1.0 or (-1.0)
    if self.weirs_.weir_type.a[uk] == 4 then
      dir = (hgl1[1] > hgl2[1]) and 1.0 or (-1.0)
      if dir < 0.0 then
        Std_swap__D(hgl1, 1, hgl2, 1)
      end
      local h_road = nodes.invert_elev.a[un1] + ctx.link_subtypes.weirs.crest_height.a[O_LinkSubtypes.row_in(ctx.link_subtypes, j, ctx.link_subtypes.weirs.link_idx)]
