    end
    if F_hydstruct_flapGateBlocks(ctx, j, n1, n2, dir) then
      links.flow.a[uj] = 0.0
      links.depth.a[uj] = 0.0
      links.dqdh.a[uj] = 0.0
      self.weirs_.surf_area.a[uk] = 0.0
      do return end
    end
    if dir < 0.0 then
      Std_swap__D(hgl1, 1, hgl2, 1)
    end
    local y_full = links.xsect_y_full.a[uj]
    local setting = links.setting.a[uj]
    local hcrest = nodes.invert_elev.a[un1] + ctx.link_subtypes.weirs.crest_height.a[O_LinkSubtypes.row_in(ctx.link_subtypes, j, ctx.link_subtypes.weirs.link_idx)]
