    do return (self.weirs_.slope.a[uk] * d) * d end
  elseif wt == 3 then
    do return (links.xsect_y_bot.a[uj] + (self.weirs_.slope.a[uk] * d)) * d end
  else
    do return length * d end
  end
end
  do return areaOf(zy) - areaOf(z) end
end
    do
      t_2 = hgl1[1]
      local h1_min = (hcrown < t_2) and hcrown or t_2
      local y_sa = y_full - (hcrown - h1_min)
      local width_at_y = 0.0
      if y_sa > 0.0 then
        if wt == 0 or wt == 1 then
          width_at_y = length
          goto sw3
        elseif wt == 2 then
          width_at_y = (2.0 * self.weirs_.slope.a[uk]) * y_sa
          goto sw3
        elseif wt == 3 then
          do
            local y_bot = links.xsect_y_bot.a[uj]
            width_at_y = y_bot + ((2.0 * self.weirs_.slope.a[uk]) * y_sa)
            goto sw3
          end
        else
          width_at_y = length
          goto sw3
        end
        ::sw3::
      end
      self.weirs_.surf_area.a[uk] = width_at_y * self.weirs_.length_eff.a[uk]
    end
    if (hgl1[1] >= hcrown) and (self.weirs_.can_surcharge.a[uk] ~= 0) then
      local h_full = setting * y_full
      local q1f = {0.0}
      local q2f = {0.0}
      weirFlow(h_full, 1.0, q1f, 1, q2f, 1)
      local h_half = h_full / 2.0
      local c_surcharge = (h_half > 0.0) and ((q1f[1] + q2f[1]) / L_sqrt(h_half)) or 0.0
      local y_mid = (hcrest + hcrown) / 2.0
      local h_orif = (hgl2[1] < y_mid) and (hgl1[1] - y_mid) or (hgl1[1] - hgl2[1])
      local y_open = hcrown - hcrest
      q = c_surcharge * L_sqrt(h_orif)
      if flap then
        local a = weirOpenArea(y_open)
        if a > 0.0 then
          local v = q / a
          local hloss = (((4.0 / S_F_constants_GRAVITY) * v) * v) * L_exp(((-1.15) * v) / L_sqrt(y_open))
          h_orif = h_orif - hloss
          h_orif = (h_orif < 0.0) and 0.0 or h_orif
          q = c_surcharge * L_sqrt(h_orif)
        end
      end
      links.depth.a[uj] = y_open
      links.dqdh.a[uj] = (h_orif > 0.0) and (q / (2.0 * h_orif)) or 0.0
    else
      if hgl1[1] >= hcrown then
        head = hcrown - hcrest
      end
      local q1 = {0.0}
      local q2 = {0.0}
      weirFlow(head, dir, q1, 1, q2, 1)
      if flap then
        local area = weirOpenArea(head)
        if area > (1E-06) then
          local veloc = (q1[1] + q2[1]) / area
          local hLoss = (((4.0 / S_F_constants_GRAVITY) * veloc) * veloc) * L_exp(((-1.15) * veloc) / L_sqrt(head))
