          goto sw4
        elseif wt == 2 then
          links.dqdh.a[uj] = (q2h == 0.0) and (2.5 * q1h) or ((1.5 * q1h) + (2.5 * q2h))
          goto sw4
        else
          links.dqdh.a[uj] = (1.5 * q1h) + (2.5 * q2h)
          goto sw4
        end
        ::sw4::
      else
