        q1[1] = q1[1] * L_pow(1.0 - L_pow(ratio, wp), 0.385)
        if q2[1] > 0.0 then
          q2[1] = q2[1] * L_pow(1.0 - L_pow(ratio, 2.5), 0.385)
        end
      end
      q = q1[1] + q2[1]
      t_2 = hgl1[1] - hcrest
      links.depth.a[uj] = (y_full < t_2) and y_full or t_2
    end
    if q < 0.0 then
      q = 0.0
    end
    links.flow.a[uj] = q * dir
  end
end
function O_Thydstruct_StructureSolver.computeOutletFlowK(self, ctx, k)
  local t_1, t_2, t_3
  local links = ctx.links
  local nodes = ctx.nodes
  local fu = ctx.options.flow_units
  local unit_sys = F_ucf_getUnitSystem(fu)
  local ucf_len = S_F_ucf_Ucf_UnitConversion[3][unit_sys]
  local ucf_flow = S_F_ucf_Qcf_UnitConversion[fu]
  local v_FUDGE_OUT = 0.0001
  do
    local uk = k
    local j = self.outlets_.link_idx.a[uk]
    local uj = j
    local n1 = links.node1.a[uj]
    local n2 = links.node2.a[uj]
    if (n1 < 0) or (n2 < 0) then
      links.flow.a[uj] = 0.0
      links.depth.a[uj] = 0.0
      do return end
    end
    local un1 = n1
    local un2 = n2
    if links.setting.a[uj] == 0.0 then
      links.flow.a[uj] = 0.0
      do return end
    end
    local h1 = {nodes.depth.a[un1] + nodes.invert_elev.a[un1]}
    local h2 = {F_hydstruct_tailwaterHead_HydStructures(ctx, un1, un2)}
    local dir = (h1[1] >= h2[1]) and 1 or (-1)
    local y1 = nodes.depth.a[un1]
    if dir < 0 then
      Std_swap__D(h1, 1, h2, 1)
      y1 = nodes.depth.a[un2]
    end
    local olr_c = O_LinkSubtypes.row_in(ctx.link_subtypes, j, ctx.link_subtypes.outlets.link_idx)
    local hcrest = nodes.invert_elev.a[un1] + ((olr_c >= 0) and ctx.link_subtypes.outlets.crest_height.a[olr_c] or 0.0)
    local outlet_type = L_f2i32(ctx.link_subtypes.outlets.outlet_type.a[O_LinkSubtypes.row_in(ctx.link_subtypes, j, ctx.link_subtypes.outlets.link_idx)])
    local depth_based = (outlet_type == 1) or (outlet_type == 3)
    if depth_based then
      t_3 = h1[1] - hcrest
    else
      t_2 = h1[1]
      t_1 = h2[1]
      t_3 = t_2 - ((t_1 < hcrest) and hcrest or t_1)
    end
    local head = t_3
    local blocked_by_flap = F_hydstruct_flapGateBlocks(ctx, j, n1, n2, dir + 0.0)
    if ((head <= v_FUDGE_OUT) or (y1 <= v_FUDGE_OUT)) or blocked_by_flap then
      links.flow.a[uj] = 0.0
      links.depth.a[uj] = 0.0
      links.flow_class.a[uj] = 0
      links.dqdh.a[uj] = 0.0
      do return end
    end
    local lookup_val = head * ucf_len
    local q = 0.0
    local ci = self.outlets_.curve_idx.a[uk]
    if (ci >= 0) and L_ult(ci, ctx.tables.tables.n) then
      q = F_table_lookup_cursor(ctx.tables.tables.a[ci], lookup_val)
      q = q / ucf_flow
    elseif lookup_val > 0.0 then
      q = (self.outlets_.q_coeff.a[uk] * L_pow(lookup_val, self.outlets_.q_expon.a[uk])) / ucf_flow
    end
    q = q * links.setting.a[uj]
    if q < 0.0 then
      q = 0.0
    end
    links.flow.a[uj] = q * dir
    links.depth.a[uj] = head
    links.flow_class.a[uj] = 3
    links.dqdh.a[uj] = 0.0
  end
end
function O_Thydstruct_StructureSolver.scatterOrificeSurfArea(self, ctx, node_new_surf_area, uk_, uj_, un1_, un2_)
  if PtrD_op_Eq(node_new_surf_area, PtrD_ZERO) then
    do return end
  end
  local links = ctx.links
  local nodes = ctx.nodes
  local sa1 = self.orifices_.surf_area.a[uk_] * 0.5
  local sa2 = sa1
  local fc = links.flow_class.a[uj_]
  if (fc == 5) or (nodes.type.a[un1_] == 3) then
    sa1 = 0.0
  end
  if (fc == 6) or (nodes.type.a[un2_] == 3) then
    sa2 = 0.0
  end
  node_new_surf_area.a[node_new_surf_area.o + un1_] = node_new_surf_area.a[node_new_surf_area.o + un1_] + sa1
  node_new_surf_area.a[node_new_surf_area.o + un2_] = node_new_surf_area.a[node_new_surf_area.o + un2_] + sa2
end
