-- ---- O_Tinlet_InletSolver
O_Tinlet_InletSolver = lua_class("Tinlet_InletSolver", nil, {Cpp_ICopy})
function O_Tinlet_InletSolver._new() return L_setmetatable({nsides_prev_ = 0}, O_Tinlet_InletSolver) end
function O_Tinlet_InletSolver.init(self, ctx)
  local t_1, t_2, t_3
  local usages = ctx.inlet_usages
  local n = ((usages.design_index.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  O_Tinlet_InletSoA.resize(self.soa_, n)
  if n == 0 then
    do return end
  end
  local nn = ((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local nl = ((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  self.node_inlet_flow_:assign_ul_T(nn, 0.0)
  self.node_inflow_:assign_ul_T(nn, 0.0)
  self.is_capture_node_:assign_ul_T(nn, 0)
  local us = F_ucf_getUnitSystem(ctx.options.flow_units)
  local inv_len = S_F_ucf_Ucf_inv[3][us]
  local inv_flow = S_F_ucf_Qcf_inv[ctx.options.flow_units]
  local out_degree = NewVecI_ul_T(nn, 0)
  do
    local j = 0
    while j < nl do
      do
        local uj = j
        if ctx.links.direction.a[uj] < 0 then
          t_1, t_2 = ctx.links.node2.a, uj
        else
          t_1, t_2 = ctx.links.node1.a, uj
        end
        local m = t_1[t_2]
        if (m < 0) or (m >= nn) then
          goto cont1
        end
        if ctx.nodes.type.a[m] == 1 then
          if ctx.links.direction.a[uj] < 0 then
            t_1, t_2 = ctx.links.node1.a, uj
          else
            t_1, t_2 = ctx.links.node2.a, uj
          end
          m = t_1[t_2]
          if (m < 0) or (m >= nn) then
            goto cont1
          end
        end
        t_1 = out_degree.a[m]
        out_degree.a[m] = (((t_1 + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        t_2, t_3 = {0}, 1
        t_2[t_3] = t_1
      end
      ::cont1::
      j = j + 1
    end
  end
  do
    local i = 0
    while i < n do
      do
        local ui = i
        local li = usages.link_index.a[ui]
        local nh = usages.node_host.a[ui]
        local di = usages.design_index.a[ui]
        self.soa_.link_idx.a[ui] = li
        self.soa_.host_node.a[ui] = nh
        self.soa_.node_idx.a[ui] = usages.node_index.a[ui]
        if (self.soa_.node_idx.a[ui] >= 0) and (self.soa_.node_idx.a[ui] < nn) then
          self.is_capture_node_.a[self.soa_.node_idx.a[ui]] = 1
        end
        self.soa_.num_inlets.a[ui] = usages.num_inlets.a[ui]
        self.soa_.clog_factor.a[ui] = usages.clog_factor.a[ui]
        self.soa_.flow_limit.a[ui] = usages.flow_limit.a[ui] * inv_flow
        self.soa_.local_depress.a[ui] = usages.local_depress.a[ui] * inv_len
        self.soa_.local_width.a[ui] = usages.local_width.a[ui] * inv_len
        self.soa_.placement.a[ui] = usages.placement.a[ui]
        if (di >= 0) and (di < (((ctx.inlets.names_f.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
          local ud = di
          local type_str = ctx.inlets.inlet_type.a[ud]
          local itype = 6
          if type_str:EqLit(R_Lit("GRATE")) then
            itype = 0
          elseif type_str:EqLit(R_Lit("CURB")) then
            itype = 1
          elseif type_str:EqLit(R_Lit("COMBO")) then
            itype = 2
          elseif type_str:EqLit(R_Lit("SLOTTED")) then
            itype = 3
          elseif type_str:EqLit(R_Lit("DROP_GRATE")) then
            itype = 4
          elseif type_str:EqLit(R_Lit("DROP_CURB")) then
            itype = 5
          elseif type_str:EqLit(R_Lit("CUSTOM")) then
            itype = 6
          end
          self.soa_.inlet_type.a[ui] = itype
          local gt_str = ctx.inlets.grate_type.a[ud]
          local gt = 7
          if gt_str:EqLit(R_Lit("P_BAR-50")) then
            gt = 0
          elseif gt_str:EqLit(R_Lit("P_BAR-50x100")) then
            gt = 1
          elseif gt_str:EqLit(R_Lit("P_BAR-30")) then
            gt = 2
          elseif gt_str:EqLit(R_Lit("CURVED_VANE")) then
            gt = 3
          elseif gt_str:EqLit(R_Lit("TILT_BAR-45")) then
            gt = 4
          elseif gt_str:EqLit(R_Lit("TILT_BAR-30")) then
            gt = 5
          elseif gt_str:EqLit(R_Lit("RETICULINE")) then
            gt = 6
          end
          self.soa_.grate_type.a[ui] = gt
          if itype == 3 then
            self.soa_.slotted_length.a[ui] = ctx.inlets.length.a[ud] * inv_len
            self.soa_.slotted_width.a[ui] = ctx.inlets.width.a[ud] * inv_len
          elseif ((itype == 0) or (itype == 4)) or (itype == 2) then
            self.soa_.grate_length.a[ui] = ctx.inlets.length.a[ud] * inv_len
            self.soa_.grate_width.a[ui] = ctx.inlets.width.a[ud] * inv_len
          end
          self.soa_.open_area.a[ui] = ctx.inlets.open_area.a[ud]
          self.soa_.splash_veloc.a[ui] = ctx.inlets.splash_veloc.a[ud] * inv_len
          if ((itype == 1) or (itype == 5)) or (itype == 2) then
            self.soa_.curb_length.a[ui] = ctx.inlets.curb_length.a[ud] * inv_len
            self.soa_.curb_height.a[ui] = ctx.inlets.curb_height.a[ud] * inv_len
            self.soa_.curb_throat.a[ui] = ctx.inlets.curb_throat.a[ud]
          end
          self.soa_.curve_index.a[ui] = ctx.inlets.curve_index.a[ud]
          self.soa_.curve_kind.a[ui] = ctx.inlets.curve_kind.a[ud]
        end
        local bypass = -1
        local up = {-1}
        local up2 = {-1}
        if (nh >= 0) and (nh < nn) then
          bypass = nh
          do
            local j_2 = 0
            while (j_2 < nl) and (up2[1] < 0) do
              do
                local uj_2 = j_2
                if ctx.links.type.a[uj_2] ~= 0 then
                  goto cont3
                end
                if ctx.links.node2.a[uj_2] ~= nh then
                  goto cont3
                end
                if up[1] < 0 then
                  up[1] = j_2
                else
                  up2[1] = j_2
                end
              end
              ::cont3::
              j_2 = j_2 + 1
            end
          end
          if up[1] < 0 then
            do
              local j_3 = 0
              while j_3 < nl do
                do
                  local uj_3 = j_3
