          if n2 >= 0 then
            nodes.inflow.a[n2] = nodes.inflow.a[n2] + q
          end
          goto cont2
        end
        if links.xsect_shape.a[uj] == 25 then
          local n1_2 = links.node1.a[uj]
          local n2_2 = links.node2.a[uj]
          local q_2 = F_kinwave_getLinkInflow(ctx, structures, j_2, dt)
          links.flow.a[uj] = q_2
          if n1_2 >= 0 then
