        end
        local v_CD = ctx.link_subtypes.conduits
        local ucr = O_LinkSubtypes.row_in(ctx.link_subtypes, j_2, ctx.link_subtypes.conduits.link_idx)
        local n1_3 = links.node1.a[uj]
        local qin = 0.0
        if n1_3 >= 0 then
          qin = F_kinwave_getLinkInflow(ctx, structures, j_2, dt)
