        local xs = F_kinwave_buildXSP_KW_KinematicWave(ctx, uj)
        local q_full = v_CD.q_full.a[ucr]
        local a_full = links.xsect_a_full.a[uj]
        local s_full = links.xsect_s_full.a[uj]
        local beta = v_CD.beta.a[ucr]
        local length = v_CD.true_length.a[ucr]
        if length <= 0.0 then
