        local iters = O_Tkinwave_KWSolver.solveConduit(self, ((uj + 0x80000000) & 0xFFFFFFFF) - 0x80000000, xs, q_full, a_full, s_full, beta, length, dt, loss_rate)
        total_iters = (((total_iters + iters) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        n_solved = (((n_solved + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        local qout = self.q_out_.a[uj] * barrels
