        local y_in = O_Txsect_XsectEval.getYofA(F_xsect_hostEval(), xs, self.a_in_.a[uj])
        local y_out = O_Txsect_XsectEval.getYofA(F_xsect_hostEval(), xs, self.a_out_.a[uj])
