function O_Tkinwave_KWSolver.solveConduit(self, idx, xs, q_full, a_full, s_full, beta, length, dt, loss_rate)
  local ui = idx
  if (q_full <= 0.0) or (a_full <= 0.0) then
    self.q_out_.a[ui] = 0.0
    self.a_out_.a[ui] = 0.0
    do return 0 end
  end
  local q_in_norm = self.q_in_.a[ui] / q_full
  local q3 = loss_rate / q_full
  local beta1 = beta / q_full
  local prev_q1 = self.q1_.a[ui] / q_full
  local prev_a1 = self.a1_.a[ui] / a_full
  local prev_q2 = self.q2_.a[ui] / q_full
  local prev_a2 = self.a2_.a[ui] / a_full
  local a_in_norm = 0.0
  if q_in_norm >= 1.0 then
    a_in_norm = 1.0
  elseif q_in_norm <= 0.0 then
    a_in_norm = 0.0
  else
    local s_needed = q_in_norm / beta1
    a_in_norm = O_Txsect_XsectEval.getAofS(F_xsect_hostEval(), xs, s_needed) / a_full
  end
  if (q_in_norm <= S_F_kinwave_TINY_KinematicWave) and (prev_q2 <= S_F_kinwave_TINY_KinematicWave) then
    self.a_in_.a[ui] = a_in_norm * a_full
    self.a_out_.a[ui] = 0.0
    self.q_out_.a[ui] = 0.0
    if q_in_norm > 1.0 then
      q_in_norm = 1.0
    end
    self.q_in_.a[ui] = q_in_norm * q_full
    self.q1_.a[ui] = self.q_in_.a[ui]
    self.a1_.a[ui] = self.a_in_.a[ui]
    self.q2_.a[ui] = 0.0
    self.a2_.a[ui] = 0.0
    do return 1 end
  end
  local dxdt = ((length / dt) * a_full) / q_full
  local dq = prev_q2 - prev_q1
  local v_C1 = (dxdt * S_F_kinwave_WT) / S_F_kinwave_WX
  local v_C2 = (1.0 - S_F_kinwave_WT) * (a_in_norm - prev_a1)
  v_C2 = v_C2 - (S_F_kinwave_WT * prev_a2)
  v_C2 = (v_C2 * dxdt) / S_F_kinwave_WX
  v_C2 = (v_C2 + (((1.0 - S_F_kinwave_WX) / S_F_kinwave_WX) * dq)) - q_in_norm
  v_C2 = v_C2 + (q3 / S_F_kinwave_WX)
  local aHi = 1.0
  local fHi = (1.0 + v_C1) + v_C2
  local aLo = ((xs.type == 22) or (xs.type == 23)) and (xs.a_bot / a_full) or O_Txsect_XsectEval.getAmax(F_xsect_hostEval(), xs)
  local fLo = 0.0
  if aLo < aHi then
    fLo = ((beta1 * xs.s_max) + (v_C1 * aLo)) + v_C2
  else
    fLo = fHi
  end
  if (fHi * fLo) > 0.0 then
    aHi = aLo
    fHi = fLo
    aLo = 0.0
    fLo = v_C2
  end
  local a = {prev_a2}
  local result = 0
  if (fHi * fLo) <= 0.0 then
    if (a[1] < aLo) or (a[1] > aHi) then
      a[1] = 0.5 * (aLo + aHi)
    end
    if fLo > fHi then
      local aTmp = aLo
      aLo = aHi
      aHi = aTmp
    end
    local v___b1 = {[0] = a[1], n = 1}
    result = Mv_Back__ID(F_findroot_newton(aLo, aHi, NewPtrD_TA_l(v___b1, 0), S_F_kinwave_EPSIL, function(an, f, df)
      f.a[f.o] = ((beta1 * F_xsect_getSofA(xs, an * a_full)) + (v_C1 * an)) + v_C2
      df.a[df.o] = ((beta1 * a_full) * F_xsect_getdSdA(xs, an * a_full)) + v_C1
      do return end
    end), a, 1, v___b1)
    if result <= 0 then
      result = -1
    end
  elseif fLo < 0.0 then
    a[1] = (q_in_norm > 1.0) and a_in_norm or 1.0
    result = -2
  elseif fLo > 0.0 then
    a[1] = 0.0
    result = -3
  else
    result = -1
  end
  if result <= 0 then
    result = 1
  end
  local q_out_norm = beta1 * F_xsect_getSofA(xs, a[1] * a_full)
  self.a_in_.a[ui] = a_in_norm * a_full
  self.a_out_.a[ui] = a[1] * a_full
  self.q_out_.a[ui] = q_out_norm * q_full
  if q_in_norm > 1.0 then
    q_in_norm = 1.0
  end
  self.q_in_.a[ui] = q_in_norm * q_full
  self.q1_.a[ui] = self.q_in_.a[ui]
  self.a1_.a[ui] = self.a_in_.a[ui]
  self.q2_.a[ui] = self.q_out_.a[ui]
  self.a2_.a[ui] = self.a_out_.a[ui]
