function O_Router._new() return L_setmetatable({checkpoint_owned_session_ = false, checkpoint_aquifer_session_ = false, checkpoint_time_ = 0.0, checkpoint_step_end_ = 0.0, checkpoint_ready_ = false, checkpoint_prepared_ = false, checkpoint_step_finished_ = false, model_ = 0, lstep_enabled_ = false, lstep_rs_ = 0.0, fv_struct_t_prev_ = 0.0, cycle_detected_ = false}, O_Router) end
function O_Router.restoreFvClassicState(self, ctx)
  local t_1, t_2
  t_2 = ctx.options.routing_model ~= 3
  if not t_2 then
    t_1 = self.fv_solver_
    if not L_isa(t_1, O_Tfv_ExplicitFvSolver) then t_1 = nil end
    t_2 = not (t_1 ~= nil)
  end
  if t_2 then
    do return end
  end
  do
    local r = 0
    while r < (((self.fv_mesh_.conduit_cell_begin.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local begin = self.fv_mesh_.conduit_cell_begin.a[r]
        local count = self.fv_mesh_.conduit_cell_count.a[r]
        if (begin < 0) or (count <= 0) then
          goto cont1
        end
        local j = self.fv_mesh_.conduit_link.a[r]
        local length = 0.0
        do
          local c = begin
          while c < ((((begin + count) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
            do
              length = length + self.fv_mesh_.cell_dx.a[c]
            end
            c = c + 1
          end
        end
        local area = (length > 0.0) and (ctx.links.volume.a[j] / length) or 0.0
        do
          local c_2 = begin
          while c_2 < ((((begin + count) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
            do
              self.fv_state_.cell_a.a[c_2] = area
              self.fv_state_.cell_q.a[c_2] = (area > S_F_fv_kernels_kDryArea) and ctx.links.flow.a[j] or 0.0
            end
            c_2 = c_2 + 1
          end
        end
      end
      ::cont1::
      r = r + 1
    end
  end
  do
    local n = 0
    while n < (((self.fv_mesh_.node_invert.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        self.fv_state_.node_head.a[n] = ctx.nodes.invert_elev.a[n] + ctx.nodes.depth.a[n]
      end
      n = n + 1
    end
  end
  self.fv_solver_:initialize(self.fv_mesh_, self.fv_state_, self.fv_opts_)
  do
    local n_2 = 0
    while n_2 < (((self.fv_mesh_.node_invert.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        self.fv_state_.node_volume.a[n_2] = (ctx.nodes.type.a[n_2] == 1) and 0.0 or ctx.nodes.volume.a[n_2]
      end
      n_2 = n_2 + 1
    end
  end
end
function O_Router.init(self, ctx, model)
  local t_1, t_2, t_3
  self.checkpoint_context_ = nil
  self.checkpoint_owned_session_ = false
  self.checkpoint_model_:clear()
  self.checkpoint_step_end_ = 0.0
  self.checkpoint_time_ = 0.0
  self.checkpoint_step_finished_ = false
  self.checkpoint_prepared_ = false
  self.checkpoint_ready_ = false
  self.model_ = model
  local n_links = ((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local n_nodes = ((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local translateShape = function(link_shape)
  if link_shape == 0 then
    do return 1 end
  elseif link_shape == 1 then
    do return 2 end
  elseif link_shape == 2 then
    do return 3 end
  elseif link_shape == 3 then
    do return 4 end
  elseif link_shape == 4 then
    do return 5 end
  elseif link_shape == 5 then
    do return 6 end
  elseif link_shape == 6 then
    do return 7 end
  elseif link_shape == 7 then
    do return 8 end
  elseif link_shape == 8 then
    do return 11 end
  elseif link_shape == 9 then
    do return 15 end
  elseif link_shape == 10 then
    do return 16 end
  elseif link_shape == 11 then
    do return 17 end
  elseif link_shape == 12 then
    do return 18 end
  elseif link_shape == 13 then
    do return 19 end
  elseif link_shape == 14 then
    do return 20 end
  elseif link_shape == 15 then
    do return 21 end
  elseif link_shape == 16 then
    do return 9 end
  elseif link_shape == 17 then
    do return 10 end
  elseif link_shape == 18 then
    do return 12 end
  elseif link_shape == 19 then
    do return 13 end
  elseif link_shape == 20 then
    do return 14 end
  elseif link_shape == 21 then
    do return 22 end
  elseif link_shape == 22 then
    do return 23 end
  elseif link_shape == 23 then
    do return 24 end
  elseif link_shape == 24 then
    do return 25 end
  elseif link_shape == 25 then
    do return 0 end
  else
    do return 0 end
  end
end
  local xsect_params = NewVec_ul(n_links, K_MK45)
  do
    local j = 0
    while j < n_links do
      do
        local uj = j
        if ctx.links.type.a[uj] ~= 0 then
          goto cont2
        end
        local xs = xsect_params.a[uj]
        xs.type = translateShape(ctx.links.xsect_shape.a[uj])
        ctx.links.xsect_batch_shape.a[uj] = xs.type
        xs.y_full = ctx.links.xsect_y_full.a[uj]
        xs.a_full = ctx.links.xsect_a_full.a[uj]
        xs.w_max = ctx.links.xsect_w_max.a[uj]
        xs.r_full = ctx.links.xsect_r_full.a[uj]
        xs.s_full = ctx.links.xsect_s_full.a[uj]
        xs.y_bot = ctx.links.xsect_y_bot.a[uj]
        xs.a_bot = ctx.links.xsect_a_bot.a[uj]
        xs.s_bot = ctx.links.xsect_s_bot.a[uj]
        xs.r_bot = ctx.links.xsect_r_bot.a[uj]
        if (xs.a_full == 0.0) and (xs.y_full > 0.0) then
          local p = {[0] = xs.y_full, xs.w_max, 0.0, 0.0, n = 4}
          F_xsect_setParams(xs, xs.type, NewPtrD_TA_l(p, 0), 1.0)
          ctx.links.xsect_a_full.a[uj] = xs.a_full
          ctx.links.xsect_r_full.a[uj] = xs.r_full
          ctx.links.xsect_s_full.a[uj] = xs.s_full
          ctx.links.xsect_w_max.a[uj] = xs.w_max
        end
      end
      ::cont2::
      j = j + 1
    end
  end
  F_applyConduitLengthening(ctx, model)
  O_XSectGroups.build(self.groups_, xsect_params:data(), n_links)
  O_XSectGroups.attachTransectTables(self.groups_, ctx)
  F_outfall_buildOutfallLinkMap(ctx)
  self.cycle_detected_ = false
  t_1 = self.model_
  if t_1 == 1 then
    do
      O_Tkinwave_KWSolver.init(self.kw_solver_, n_links, self.groups_)
      local sorted = NewVecI()
      local divert = F_buildDivertLinks_Routing(ctx)
      local n_sorted = F_toposort_sortLinks(ctx.links.node1:data(), ctx.links.node2:data(), n_links, n_nodes, sorted, divert:data())
      if n_sorted < n_links then
        self.cycle_detected_ = true
      end
      O_Tkinwave_KWSolver.setLinkOrder(self.kw_solver_, sorted)
      goto sw3
    end
  elseif t_1 == 2 then
    do
      local ucf_len = S_F_ucf_Ucf_UnitConversion[3][F_ucf_getUnitSystem(ctx.options.flow_units)]
      self.dw_solver_.head_tol = (ctx.options.head_tol == 0.0) and S_F_constants_DEFAULT_HEAD_TOL or (ctx.options.head_tol / ucf_len)
      if ctx.options.max_trials > 0 then
        t_2, t_3 = ctx.options, "max_trials"
      else
        t_2, t_3 = _ENV, "S_F_constants_DEFAULT_MAX_TRIALS"
      end
      self.dw_solver_.max_trials = t_2[t_3]
      self.dw_solver_.surcharge_method = ctx.options.surcharge_method
      self.dw_solver_.node_continuity = ctx.options.node_continuity
      self.dw_solver_.anderson_accel = ctx.options.anderson_accel
      self.dw_solver_.unsteady_friction = ctx.options.unsteady_friction
      self.dw_solver_.uf_k3 = ctx.options.uf_k3
      self.dw_solver_.tpa_celerity = ctx.options.tpa_celerity
      O_Tdynwave_DWSolver.init(self.dw_solver_, n_nodes, n_links, self.groups_, ctx)
      goto sw3
    end
  elseif t_1 == 3 then
    O_Router.initFv(self, ctx)
    goto sw3
  elseif t_1 == 0 then
    do
      local divert_2 = F_buildDivertLinks_Routing(ctx)
      local n_sorted_2 = F_toposort_sortLinks(ctx.links.node1:data(), ctx.links.node2:data(), n_links, n_nodes, self.steady_sorted_links_, divert_2:data())
      if n_sorted_2 < n_links then
        self.cycle_detected_ = true
      end
      goto sw3
    end
  end
  ::sw3::
end
function O_Router.acceptedQualityWater(self, ctx, dt, out)
  local t_1, t_2, t_3
  out.ready = false
  t_1 = self.fv_solver_
  if not L_isa(t_1, O_Tfv_ExplicitFvSolver) then t_1 = nil end
  local native = t_1
  if ((not (native ~= nil)) or (dt <= 0.0)) or (native.water_.face_forward.n == 0) then
    do return end
  end
  local nn = ((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local nl = ((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local n = nn + nl
  local w = out.water
  local r = native.water_
  w.old_volume:assign_ul_T(n, 0.0)
  w.new_volume:assign_ul_T(n, 0.0)
  w.source_volume:assign_ul_T(n, 0.0)
  w.exported:assign_ul_T(n, 0.0)
  w.seeped:assign_ul_T(n, 0.0)
  w.evaporated:assign_ul_T(n, 0.0)
  w.transfers:clear()
  out.boundary_imports:clear()
  out.withdrawal:assign_ul_T(nn, 0.0)
  out.flooding:assign_ul_T(nn, 0.0)
  do
    local i = 0
    while L_ult(i, nn) do
      do
        if ctx.nodes.type.a[i] ~= 1 then
          w.old_volume.a[i] = ctx.nodes.old_volume.a[i]
          w.new_volume.a[i] = ctx.nodes.volume.a[i]
        end
        local row = O_NodeSubtypes.storage_row(ctx.node_subtypes, ((i + 0x80000000) & 0xFFFFFFFF) - 0x80000000)
        if row >= 0 then
          local st = ctx.node_subtypes.storages
          w.seeped.a[i] = st.exfil_loss.a[row]
          w.evaporated.a[i] = st.evap_loss.a[row]
        end
        if not (self.fv_mesh_.node_can_pond.a[i] ~= 0) then
          out.flooding.a[i] = native.flood_vol_.a[i]
        end
        out.withdrawal.a[i] = native.withdrawal_rates_.a[i] * dt
        if (ctx.nodes.type.a[i] == 1) and (out.withdrawal.a[i] > 0.0) then
          t_1 = Tquality_BoundaryWaterImport__new()
          t_1.node = i
          t_1.receiver = i
          t_1.volume = out.withdrawal.a[i]
          out.boundary_imports:push_back(t_1)
          w.source_volume.a[i] = w.source_volume.a[i] + out.withdrawal.a[i]
        end
        w.exported.a[i] = out.withdrawal.a[i] + out.flooding.a[i]
      end
      i = i + 1
    end
  end
  do
    local j = 0
    while L_ult(j, nl) do
      do
        if (ctx.links.type.a[j] ~= 0) or (ctx.links.xsect_shape.a[j] == 25) then
          goto cont2
        end
