function O_Router.initNodeFlows(self, ctx, dt, evap_rate)
  local t_1, t_2
  local nodes = ctx.nodes
  local n = ((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  do
    local i = 0
    while i < n do
      do
        local ui = i
        local loss_rate = 0.0
        if nodes.type.a[ui] == 3 then
          local sr = O_NodeSubtypes.storage_row(ctx.node_subtypes, i)
          local st = ctx.node_subtypes.storages
          local sru = sr
          local evap_frac = (sr >= 0) and st.evap_frac.a[sru] or 0.0
          local seep_rate = (sr >= 0) and st.seep_rate.a[sru] or 0.0
          local stor_evap_rate = evap_rate * evap_frac
          if (sr >= 0) and (not (st.lid_state.a[sru].cells.n == 0)) then
            local state = st.lid_state.a[sru]
            local potential = (evap_rate * evap_frac) * state.cells:front().area
            local area = F_node_getSurfArea(nodes, i, nodes.depth.a[ui], ctx.tables, F_ucf_getUnitSystem(ctx.options.flow_units), ctx.node_subtypes)
            if area > 0.0 then
              t_1 = potential - (state.evap_volume / dt)
              t_2 = ((0.0 < t_1) and t_1 or 0.0) / area
            else
              t_2 = 0.0
            end
            stor_evap_rate = t_2
            if state.richards then
              stor_evap_rate = 0.0
            end
          end
          local exfil_cfs = (sr >= 0) and st.exfil_rate.a[sru] or 0.0
          if ((stor_evap_rate > 0.0) or (seep_rate > 0.0)) or (exfil_cfs > 0.0) then
            local depth = nodes.depth.a[ui]
            local area_2 = F_node_getSurfArea(nodes, i, depth, ctx.tables, F_ucf_getUnitSystem(ctx.options.flow_units), ctx.node_subtypes)
            local evap_cfs = stor_evap_rate
            if nodes.volume.a[ui] > S_F_constants_FUDGE then
              evap_cfs = area_2 * stor_evap_rate
            end
            local total_loss = (evap_cfs + exfil_cfs) * dt
            if (total_loss > nodes.volume.a[ui]) and (total_loss > 0.0) then
              local ratio = nodes.volume.a[ui] / total_loss
              evap_cfs = evap_cfs * ratio
              exfil_cfs = exfil_cfs * ratio
            end
            if sr >= 0 then
              st.evap_loss.a[sru] = evap_cfs * dt
              st.exfil_loss.a[sru] = exfil_cfs * dt
            end
            loss_rate = evap_cfs + exfil_cfs
          elseif sr >= 0 then
            st.evap_loss.a[sru] = 0.0
            st.exfil_loss.a[sru] = 0.0
          end
        end
        nodes.losses.a[ui] = loss_rate
        nodes.inflow.a[ui] = nodes.lat_flow.a[ui]
        nodes.outflow.a[ui] = nodes.losses.a[ui]
        if ctx.options.routing_model == 3 then
          t_1, t_2 = nodes.full_volume.a, ui
        else
          t_1, t_2 = nodes.rpt_full_volume.a, ui
        end
        local full_vol = t_1[t_2]
        if (nodes.volume.a[ui] > full_vol) and (dt > 0.0) then
          nodes.overflow.a[ui] = (nodes.volume.a[ui] - full_vol) / dt
        else
          nodes.overflow.a[ui] = 0.0
        end
      end
      i = i + 1
    end
  end
end
function O_Router.computeConduitLosses(self, ctx, dt, evap_rate)
  local t_1, t_2
  local links = ctx.links
  local n = ((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  do
    local j = 0
    while j < n do
      do
        local uj = j
        if links.type.a[uj] ~= 0 then
          goto cont1
        end
        local v_CD = ctx.link_subtypes.conduits
        local ucr = O_LinkSubtypes.row_in(ctx.link_subtypes, j, ctx.link_subtypes.conduits.link_idx)
        local depth = 0.5 * (links.old_depth.a[uj] + links.depth.a[uj])
        local evap_loss = 0.0
        local seep_loss = {0.0}
        if depth > S_F_constants_FUDGE then
          local length = v_CD.true_length.a[ucr]
          if length <= 0.0 then
            length = v_CD.length.a[ucr]
          end
          if length <= 0.0 then
            length = v_CD.mod_length.a[ucr]
          end
          local batch_shape = links.xsect_batch_shape.a[uj]
          local gw_two_way = (not (v_CD.gw_coupled.n == 0)) and (v_CD.gw_coupled.a[ucr] ~= 0)
          if gw_two_way then
            t_1, t_2 = v_CD.gw_kc.a, ucr
          else
            t_1, t_2 = v_CD.seep_rate.a, ucr
          end
          local k_seep = t_1[t_2]
          local wantEvap = O_Txsect_XsectEval.isOpen(F_xsect_hostEval(), batch_shape) and (evap_rate > 0.0)
          local wantSeep = k_seep > 0.0
          if wantEvap or wantSeep then
            local xs = XSectParams__new()
            xs.type = batch_shape
            xs.y_full = links.xsect_y_full.a[uj]
            xs.a_full = links.xsect_a_full.a[uj]
            xs.w_max = links.xsect_w_max.a[uj]
            xs.yw_max = links.xsect_yw_max.a[uj]
            xs.r_full = links.xsect_r_full.a[uj]
            xs.s_full = links.xsect_s_full.a[uj]
            xs.s_max = links.xsect_s_max.a[uj]
            xs.y_bot = links.xsect_y_bot.a[uj]
            xs.a_bot = links.xsect_a_bot.a[uj]
            xs.s_bot = links.xsect_s_bot.a[uj]
            xs.r_bot = links.xsect_r_bot.a[uj]
            if ((batch_shape == 22) or (batch_shape == 23)) or (batch_shape == 25) then
              local ci = links.xsect_curve.a[uj]
              if (ci >= 0) and L_ult(ci, ctx.transect_tables.n) then
                local td = ctx.transect_tables.a[ci]
                xs.transect = ci
                xs.area_tbl = NewPtrD_TA_l(td.area_tbl, 0)
                xs.hrad_tbl = NewPtrD_TA_l(td.hrad_tbl, 0)
                xs.width_tbl = NewPtrD_TA_l(td.width_tbl, 0)
                xs.area_lut = td.area_lut
                xs.transect_tbl_size = S_F_transect_N_TRANSECT_TBL
              end
            end
            if wantEvap then
              local top_width = 0.0
              if (batch_shape == 22) or (batch_shape == 23) then
                if xs.y_full > 0.0 then
                  t_1 = depth / xs.y_full
                  t_2 = xs.w_max * ((1.0 < t_1) and 1.0 or t_1)
                else
                  t_2 = 0.0
                end
                top_width = t_2
              else
                top_width = O_Txsect_XsectEval.getWofY(F_xsect_hostEval(), xs, depth)
              end
              evap_loss = (top_width * length) * evap_rate
            end
            if wantSeep then
              local d_seep = depth
              local width = 0.0
              if batch_shape == 3 then
                width = xs.w_max
              else
                if d_seep >= xs.yw_max then
                  d_seep = xs.yw_max
                end
                width = O_Txsect_XsectEval.getWofY(F_xsect_hostEval(), xs, d_seep)
              end
              seep_loss[1] = (k_seep * width) * length
              seep_loss[1] = seep_loss[1] * ctx.climate_state.infil_factor
              if gw_two_way then
                seep_loss[1] = seep_loss[1] * F_hydraulics_aquiferSeepFactor(depth, v_CD.gw_head_rel.a[ucr], v_CD.gw_dc.a[ucr])
                seep_loss[1] = F_hydraulics_capAquiferGain(seep_loss[1], v_CD.gw_gain_max.a[ucr])
              end
            end
          end
          t_1 = seep_loss[1]
          local total = evap_loss + ((t_1 < 0.0) and 0.0 or t_1)
          if (total > 0.0) and ((self.model_ == 2) or (self.model_ == 3)) then
            local q_avail = links.volume.a[uj] / (dt * v_CD.barrels.a[ucr])
            if (total > q_avail) and (q_avail >= 0.0) then
              local ratio = q_avail / total
              evap_loss = evap_loss * ratio
              if seep_loss[1] > 0.0 then
                seep_loss[1] = seep_loss[1] * ratio
              end
            end
          end
        end
        F_hydraulics_applySeepageForcing(ctx, uj, seep_loss, 1)
        v_CD.evap_loss_rate.a[ucr] = evap_loss
        v_CD.seep_loss_rate.a[ucr] = seep_loss[1]
      end
      ::cont1::
      j = j + 1
    end
  end
end
function O_Router.refreshFvBoundaryFlows(self, ctx, t_elapsed, eval_structures)
