  if alpha >= 1.0 then
    do return 1.0 end
  end
  if alpha <= 0.0 then
    do return 0.0 end
  end
  if alpha <= (1E-05) then
    theta = L_pow(37.6911 * alpha, 0.3333333333333333)
    do return L_pow(theta, 4.333333333333333) / 124.4797 end
  end
  theta = O_Txsect_XsectEval.getThetaOfAlpha(self, alpha)
  do return (L_pow(theta - L_sin(theta), 1.6666666666666667) / (2.0 * S_F_xsect_PI)) / L_pow(theta, 0.6666666666666666) end
end
function O_Txsect_XsectEval.getAcircular(self, psi)
  local theta = 0.0
  if psi >= 1.0 then
    do return 1.0 end
  end
  if psi <= 0.0 then
    do return 0.0 end
  end
  if psi <= (1E-06) then
    theta = L_pow(124.4797 * psi, 0.23076923076923078)
    do return ((theta * theta) * theta) / 37.6911 end
  end
  theta = O_Txsect_XsectEval.getThetaOfPsi(self, psi)
