end
function O_Txsect_XsectEval.tabular_getdSdA(self, xs, a, v_table, n_items)
  local alpha = a / xs.a_full
  local delta = 1.0 / ((((n_items - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)
  local i = L_f2i32(alpha / delta)
  if i >= ((((n_items - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) then
    i = (((n_items - 2) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  end
  local dSdA = (v_table.a[v_table.o + ((((i + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)] - v_table.a[v_table.o + i]) / delta
  do return (dSdA * xs.s_full) / xs.a_full end
end
