  do return xs.r_bot * L_pow(y, xs.s_bot + 1.0) end
end
function O_Txsect_XsectEval.powerfunc_getWofY(self, xs, y)
  do return ((xs.s_bot + 1.0) * xs.r_bot) * L_pow(y, xs.s_bot) end
end
function O_Txsect_XsectEval.powerfunc_getYofA(self, xs, a)
