function O_Txsect_XsectEval.powerfunc_getPofY(self, xs, y)
  local dy1 = 0.02 * xs.y_full
  local h = ((xs.s_bot + 1.0) * xs.r_bot) / 2.0
  local m = xs.s_bot
  local p = 0.0
  local y1 = 0.0
  local x1 = 0.0
  local x2 = 0.0
  local y2 = 0.0
  local dx = 0.0
  local dy = 0.0
  repeat
    do
      y2 = y1 + dy1
      if y2 > y then
        y2 = y
      end
      x2 = h * L_pow(y2, m)
      dx = x2 - x1
      dy = y2 - y1
      p = p + L_sqrt((dx * dx) + (dy * dy))
      x1 = x2
      y1 = y2
    end
  until not (y2 < y)
  do return 2.0 * p end
end
