end
function O_Txsect_XsectEval.getYcrit(self, xs, q)
  local t_1
  if q <= 0.0 then
    do return 0.0 end
  end
  local q2g = (q * q) / S_F_xsect_GRAVITY
  if q2g == 0.0 then
    do return 0.0 end
  end
  local y = 0.0
  t_1 = xs.type
  if t_1 == 0 then
    do return 0.0 end
  elseif t_1 == 4 or t_1 == 3 then
    y = L_pow(q2g / (xs.w_max * xs.w_max), 0.3333333333333333)
    goto sw1
  elseif t_1 == 6 then
    y = L_pow((2.0 * q2g) / (xs.s_bot * xs.s_bot), 0.2)
    goto sw1
  elseif t_1 == 7 then
    y = L_pow((0.84375 * q2g) / (xs.r_bot * xs.r_bot), 0.25)
    goto sw1
  elseif t_1 == 8 then
    y = 1.0 / ((2.0 * xs.s_bot) + 3.0)
    y = L_pow((q2g * (xs.s_bot + 1.0)) / (xs.r_bot * xs.r_bot), y)
    goto sw1
  else
    do
      local qCritical = function(yc, qTarget)
  local a = O_Txsect_XsectEval.getAofY(self, xs, yc)
  local w = O_Txsect_XsectEval.getWofY(self, xs, yc)
  if w > 0.0 then
    do return (a * L_sqrt((S_F_xsect_GRAVITY * a) / w)) - qTarget end
  end
  do return -qTarget end
end
      local y0 = 1.01 * L_pow(q2g / xs.y_full, 0.25)
      if y0 >= xs.y_full then
        y0 = 0.97 * xs.y_full
      end
      local r = xs.a_full / (((S_F_xsect_PI / 4.0) * xs.y_full) * xs.y_full)
      if (r >= 0.5) and (r <= 2.0) then
        local v_N_INC = 25
        local dy = xs.y_full / v_N_INC
        local i1 = L_f2i32(y0 / dy)
        local q0 = qCritical(i1 * dy, 0.0)
        if q0 < q then
          y = xs.y_full
          do
            local i = (((i1 + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
            while i <= v_N_INC do
              do
                local qc = qCritical(i * dy, 0.0)
                if qc >= q then
                  y = (((q - q0) / (qc - q0)) + ((((i - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) * dy
                  break
                end
                q0 = qc
              end
              i = i + 1
            end
          end
        else
          y = 0.0
          do
            local i_2 = (((i1 - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
            while i_2 >= 0 do
              do
                local qc_2 = qCritical(i_2 * dy, 0.0)
                if qc_2 < q then
                  y = (((q - qc_2) / (q0 - qc_2)) + i_2) * dy
                  break
                end
                q0 = qc_2
              end
              i_2 = (((i_2 - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
            end
          end
        end
      else
        local y1 = 0.0
        local y2 = 0.99 * xs.y_full
        local q2 = qCritical(y2, 0.0)
        if q2 < q then
          y = xs.y_full
          goto sw1
        end
        local q0_2 = qCritical(y0, 0.0)
        local q1 = qCritical(0.5 * xs.y_full, 0.0)
        if q0_2 > q then
          y2 = y0
          if q1 < q then
            y1 = 0.5 * xs.y_full
          end
        else
          y1 = y0
          if q1 > q then
            y2 = 0.5 * xs.y_full
          end
        end
        y = O_Txsect_XsectEval.findroot_Ridder(self, y1, y2, 0.001, function(yc_2) return qCritical(yc_2, q) end)
      end
      goto sw1
    end
  end
  ::sw1::
  do return (xs.y_full < y) and xs.y_full or y end
end
function O_Txsect_XsectEval.isOpen(self, v_type)
  if v_type == 0 or v_type == 4 or v_type == 5 or v_type == 6 or v_type == 7 or v_type == 8 or v_type == 22 or v_type == 25 then
    do return true end
  else
    do return false end
  end
end

