    local i = 0
    while L_ult(i, v.n) do
      do
        v.a[i] = b.a[i] + (0.5 * (v.a[i] - b.a[i]))
      end
      i = i + 1
    end
  end
  do return end
end
  avg(self.face_forward, base.face_forward)
  avg(self.face_reverse, base.face_reverse)
  avg(self.structure_forward, base.structure_forward)
  avg(self.structure_reverse, base.structure_reverse)
  avg(self.cell_lateral, base.cell_lateral)
  avg(self.cell_loss, base.cell_loss)
  avg(self.node_deficit, base.node_deficit)
  avg(self.face_lateral_left, base.face_lateral_left)
