  else
    self.face_reverse.a[f] = self.face_reverse.a[f] - volume
  end
end
function O_Tfv_AcceptedWaterVolumes.structure(self, s, volume)
  if volume >= 0.0 then
    self.structure_forward.a[s] = self.structure_forward.a[s] + volume
  else
    self.structure_reverse.a[s] = self.structure_reverse.a[s] - volume
  end
end

