function O_Tfv_ExplicitFvSolver.nodeVolumeFromDepth(self, node, depth)
  local un = node
  if depth <= 0.0 then
    do return 0.0 end
  end
  local full = self.mesh_.node_full_depth.a[un]
  if ((self.mesh_.node_can_pond.a[un] ~= 0) and (full > 0.0)) and (depth > full) then
    do return O_Tfv_ExplicitFvSolver.nodeVolumeFromDepth(self, node, full) + ((depth - full) * self.mesh_.node_ponded_area.a[un]) end
  end
  local off = self.mesh_.node_vol_off.a[un]
  if off < 0 then
    do return self.state_.node_surf_area.a[un] * depth end
  end
  local dmax = self.mesh_.node_vol_dmax.a[un]
  local n = S_F_fv_kNodeVolSamples
  local vmax = self.mesh_.node_vol_tbl.a[((((off + n) - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000]
  if depth >= dmax then
    do return vmax + (self.mesh_.node_vol_atop.a[un] * (depth - dmax)) end
  end
  local dd = dmax / ((((n - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)
  local i = L_f2i32(depth / dd)
  if i > ((((n - 2) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) then
    i = (((n - 2) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  end
  if i < 0 then
    i = 0
  end
  local t = (depth - (i * dd)) / dd
  local v0 = self.mesh_.node_vol_tbl.a[(((off + i) + 0x80000000) & 0xFFFFFFFF) - 0x80000000]
  local v1 = self.mesh_.node_vol_tbl.a[((((off + i) + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000]
  do return v0 + ((v1 - v0) * t) end
end
