        t_1 = (s == 0) and ((((v_K - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) or trailing_zeros(s)
        t_2 = (((v_K - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        local jf = (t_2 < t_1) and t_2 or t_1
        t_1 = trailing_zeros((((s + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)
        t_2 = (((v_K - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        local jv = (t_2 < t_1) and t_2 or t_1
