    do return end
  end
  if (not self.acc_dirty_) and (not self.tpa_) then
    do return end
  end
  local nc = ((self.mesh_.cell_dx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local nn = ((self.mesh_.node_invert.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  do
    local c = 0
    while c < nc do
      do
        local uc = c
        if (self.acc_a_.a[uc] == 0.0) and (self.acc_q_.a[uc] == 0.0) then
