function O_Tfv_ExplicitFvSolver.rkAverage(self, forcing)
  local t_1
  local avg = function(cur, old)
  do
    local i = 0
    while L_ult(i, cur.n) do
      do
        cur.a[i] = 0.5 * (old.a[i] + cur.a[i])
      end
      i = i + 1
    end
  end
  do return end
end
  local nc = self.state_.cell_a.n
  do
    local s = 0
    while s < self.state_.n_species_f do
      do
        local base = s * nc
        do
          local i_2 = 0
          while L_ult(i_2, nc) do
            do
              local final_area = self.state_.cell_a.a[i_2]
              local sum_area = self.rk_cell_a_.a[i_2] + final_area
              self.state_.cell_phi.a[base + i_2] = (sum_area > 0.0) and (((self.rk_cell_a_.a[i_2] * self.rk_cell_phi_.a[base + i_2]) + (final_area * self.state_.cell_phi.a[base + i_2])) / sum_area) or self.rk_cell_phi_.a[base + i_2]
            end
            i_2 = i_2 + 1
          end
        end
      end
      s = s + 1
    end
  end
  avg(self.state_.cell_a, self.rk_cell_a_)
  avg(self.state_.cell_q, self.rk_cell_q_)
  do
    local n = 0
    while n < (((self.mesh_.node_invert.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local un = n
        if self.mesh_.node_kind.a[un] == 1 then
          goto cont4
        end
        if (not forcing.node_fixed_head:get_IsNull()) and is_finite(forcing.node_fixed_head.a[forcing.node_fixed_head.o + un]) then
          self.state_.node_head.a[un] = 0.5 * (self.rk_node_head_.a[un] + self.state_.node_head.a[un])
          goto cont4
        end
        if O_Tfv_ExplicitFvSolver.algebraicActive(self, n) then
          self.state_.node_head.a[un] = 0.5 * (self.rk_node_head_.a[un] + self.state_.node_head.a[un])
          t_1 = self.node_carry_.a[un]
          self.state_.node_volume.a[un] = (0.0 < t_1) and t_1 or 0.0
          goto cont4
        end
        local vol = 0.5 * (self.rk_node_vol_.a[un] + self.state_.node_volume.a[un])
        self.state_.node_volume.a[un] = vol
        self.state_.node_head.a[un] = self.mesh_.node_invert.a[un] + O_Tfv_ExplicitFvSolver.nodeDepthFromVolume(self, n, vol)
      end
      ::cont4::
      n = n + 1
    end
  end
  local avg_delta = function(cur_2, base_2)
  do
    local i_3 = 0
    while L_ult(i_3, cur_2.n) do
      do
        cur_2.a[i_3] = base_2.a[i_3] + (0.5 * (cur_2.a[i_3] - base_2.a[i_3]))
      end
      i_3 = i_3 + 1
    end
  end
  do return end
end
  avg_delta(self.node_exch_, self.rk_exch_)
  avg_delta(self.node_in_, self.rk_in_)
  avg_delta(self.node_out_, self.rk_out_)
  avg_delta(self.flood_vol_, self.rk_flood_)
  avg_delta(self.cell_q_int_, self.rk_qint_)
  avg_delta(self.node_carry_, self.rk_carry_)
  avg_delta(self.dummy_vol_, self.rk_dummy_)
  avg_delta(self.unmet_withdrawal_, self.rk_unmet_)
  if self.water_tracking_ then
    O_Tfv_AcceptedWaterVolumes.averageDelta(self.water_, self.rk_water_)
  end
  do
    local n_2 = 0
    while n_2 < (((self.mesh_.node_invert.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local un_2 = n_2
        if O_Tfv_ExplicitFvSolver.algebraicActive(self, n_2) and (not ((not forcing.node_fixed_head:get_IsNull()) and is_finite(forcing.node_fixed_head.a[forcing.node_fixed_head.o + un_2]))) then
          t_1 = self.node_carry_.a[un_2]
          self.state_.node_volume.a[un_2] = (0.0 < t_1) and t_1 or 0.0
        end
      end
      n_2 = n_2 + 1
    end
  end
  if self.tpa_ then
    self.state_.cell_tpa:Assign_VecT(self.rk_tpa_)
  end
  O_Tfv_ExplicitFvSolver.refreshDepths(self)
end
function O_Tfv_ExplicitFvSolver.faceSide(self, face, v_cell, node, zstar, dir, u_interior, out, i1_raw, i1_raw_k, z_side, z_side_k, measure_only)
