  if v_cell >= 0 then
    local uc = v_cell
    g = self.mesh_.geom.a[self.mesh_.cell_geom.a[uc]]
    if (self.opts_.order < 2) or (not (self.cell_ho2_.a[uc] ~= 0)) then
      eta = self.cell_eta_.a[uc]
