          end
        end
        if (not forcing.node_source_max:get_IsNull()) and L_ult(u1, forcing.n_nodes_f) then
          t_1 = forcing.node_source_max.a[forcing.node_source_max.o + u1]
          q = (t_1 < q) and t_1 or q
        end
        self.node_qdummy_.a[u1] = self.node_qdummy_.a[u1] - q
        self.node_qdummy_.a[u2] = self.node_qdummy_.a[u2] + q
        if book_receipts then
          self.dummy_vol_.a[us] = self.dummy_vol_.a[us] + (q * dt)
          if self.water_tracking_ then
            O_Tfv_AcceptedWaterVolumes.structure(self.water_, us, q * dt)
          end
        end
      end
      ::cont1::
      s = s + 1
    end
  end
end
