function O_Tfv_ExplicitFvSolver.divergence(self, d)
  if self.div_link_ < 0 then
    do return false end
  end
  d.link = self.div_link_
  d.value_f = self.div_value_
  d.what_f = self.div_what_
  do return true end
end
function O_Tfv_ExplicitFvSolver.setConduitStepSink(self, fn, user)
  self.step_sink_ = fn
  self.step_sink_user_ = user
end
function O_Tfv_ExplicitFvSolver.trackAcceptedWater(self, enabled)
  local t_1
  self.water_tracking_ = enabled
  if enabled and (self.mesh_ ~= nil) then
    O_Tfv_AcceptedWaterVolumes.resize(self.water_, ((self.mesh_.face_cl.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000, self.mesh_.struct_link.n, ((self.mesh_.cell_dx.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000, ((self.mesh_.node_invert.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)
  else
    t_1 = Tfv_AcceptedWaterVolumes__new()
    t_1.face_forward = NewVecD()
    t_1.face_reverse = NewVecD()
    t_1.structure_forward = NewVecD()
    t_1.structure_reverse = NewVecD()
    t_1.cell_lateral = NewVecD()
    t_1.cell_loss = NewVecD()
    t_1.node_deficit = NewVecD()
    t_1.face_lateral_left = NewVecD()
    t_1.face_lateral_right = NewVecD()
    t_1.face_spill = NewVecD()
    O_Tfv_AcceptedWaterVolumes.MoveFrom(self.water_, t_1)
  end
  self.save_water_:Assign(self.water_)
  self.rk_water_:Assign(self.water_)
end
function O_Tfv_ExplicitFvSolver.acceptedWater(self)
  do return self.water_ end
end
