function O_Tfv_ExplicitFvSolver.node_continuity_carry(self)
  do return self.node_carry_ end
end
function O_Tfv_ExplicitFvSolver.node_inflow_volume(self)
  do return self.node_in_ end
end
function O_Tfv_ExplicitFvSolver.node_outflow_volume(self)
  do return self.node_out_ end
end
function O_Tfv_ExplicitFvSolver.bookDivertedLateral(self, un, dt, forcing)
  if ((self.node_lat_div_.n == 0) or (not (self.node_lat_div_.a[un] ~= 0))) or (not (not forcing.node_lateral:get_IsNull())) then
    do return end
  end
  local lat = forcing.node_lateral.a[forcing.node_lateral.o + un]
  if lat > 0.0 then
    self.node_out_.a[un] = self.node_out_.a[un] + (lat * dt)
  end
end
function O_Tfv_ExplicitFvSolver.inlet_control(self)
  do return self.inlet_control_ end
end
function O_Tfv_ExplicitFvSolver.node_flood_volume(self)
  do return self.flood_vol_ end
end
function O_Tfv_ExplicitFvSolver.dummy_volume(self)
  do return self.dummy_vol_ end
end
function O_Tfv_ExplicitFvSolver.node_publish_stage(self)
  do return self.node_pub_ end
end
function O_Tfv_ExplicitFvSolver.cell_flow_integral(self)
  do return self.cell_q_int_ end
end
function O_Tfv_ExplicitFvSolver.nodeLateral(self, forcing, un)
  if (not (self.node_lat_div_.n == 0)) and (self.node_lat_div_.a[un] ~= 0) then
    do return 0.0 end
  end
  do return (not forcing.node_lateral:get_IsNull()) and forcing.node_lateral.a[forcing.node_lateral.o + un] or 0.0 end
end
function O_Tfv_ExplicitFvSolver.algebraicActive(self, n)
  local un = n
  if not (self.node_alg_.a[un] ~= 0) then
    do return false end
  end
  if (self.mesh_.node_can_pond.a[un] ~= 0) and (self.state_.node_volume.a[un] > self.node_vfull_.a[un]) then
    do return false end
  end
  do return true end
end
function O_Tfv_ExplicitFvSolver.incidentPressurized(self, un)
  local t_1, t_2
  do
    local p = self.mesh_.node_face_ptr.a[un]
    while p < self.mesh_.node_face_ptr.a[un + 1] do
      do
        local uf = self.mesh_.node_face_idx.a[p]
        if self.mesh_.face_cl.a[uf] >= 0 then
          t_1, t_2 = self.mesh_.face_cl.a, uf
        else
          t_1, t_2 = self.mesh_.face_cr.a, uf
        end
        local c = t_1[t_2]
        if c < 0 then
          goto cont1
        end
        local uc = c
        if self.tpa_ and (self.state_.cell_tpa.a[uc] ~= 0) then
          do return true end
        end
        local g = self.mesh_.geom.a[self.mesh_.cell_geom.a[uc]]
        if (not (g.is_open_f ~= 0)) and (self.state_.cell_h.a[uc] >= g.y_crown) then
          do return true end
        end
      end
      ::cont1::
      p = p + 1
    end
  end
  do return false end
end
function O_Tfv_ExplicitFvSolver.nodeQDummy(self, un)
  do return (self.node_qdummy_.n == 0) and 0.0 or self.node_qdummy_.a[un] end
end
function O_Tfv_ExplicitFvSolver.ltsEligible(self)
  do return ((self.opts_.lts and (self.opts_.time_integration ~= 1)) and (self.state_ ~= nil)) and (self.state_.n_species_f == 0) end
end
function O_Tfv_ExplicitFvSolver.faceIsLive(self, f)
  do return self.all_faces_live_ or ((not (self.live_stamp_.n == 0)) and (self.live_stamp_.a[f] == self.live_gen_)) end
end
function O_Tfv_ExplicitFvSolver.tpaCell(self, uc)
  do return self.tpa_ and (self.state_.cell_tpa.a[uc] ~= 0) end
end

