            i_6 = i_6 + 1
          end
        end
        do
          local e_4 = 0
          while L_ult(e_4, edges.n) do
            do
              local edge_4 = edges.a[e_4]
              self.diag_.a[edge_4.left] = self.diag_.a[edge_4.left] + self.weight_.a[e_4]
              if edge_4.right >= 0 then
                self.diag_.a[edge_4.right] = self.diag_.a[edge_4.right] + self.weight_.a[e_4]
                local a = root(edge_4.left)
                local b = root(edge_4.right)
                self.parent_.a[a] = b
              else
                self.anchored_.a[edge_4.left] = 1
              end
            end
            e_4 = e_4 + 1
          end
        end
        do
          local i_7 = 0
          while L_ult(i_7, n) do
            do
              if self.anchored_.a[i_7] ~= 0 then
                self.anchored_.a[root(((i_7 + 0x80000000) & 0xFFFFFFFF) - 0x80000000)] = 1
              end
            end
            i_7 = i_7 + 1
          end
        end
        do
          local i_8 = 0
          while L_ult(i_8, n) do
            do
              if not (self.anchored_.a[root(((i_8 + 0x80000000) & 0xFFFFFFFF) - 0x80000000)] ~= 0) then
                result.status = 2
                do return Tfv_NonlinearPressureStorage_Result_MoveNew(result) end
              end
              if not positive(self.diag_.a[i_8]) then
                result.status = 3
                do return Tfv_NonlinearPressureStorage_Result_MoveNew(result) end
              end
            end
            i_8 = i_8 + 1
          end
        end
        if result.scaled_residual <= 1.0 then
          result.scaled_residual = evaluate(self.head_, self.residual_)
          measure()
          if result.scaled_residual <= 1.0 then
            output_heads:Assign_VecT(self.head_)
            result.status = 0
          else
            result.status = 3
          end
          do return Tfv_NonlinearPressureStorage_Result_MoveNew(result) end
        end
        if it == c.max_newton then
          result.status = 8
          do return Tfv_NonlinearPressureStorage_Result_MoveNew(result) end
        end
        Algo_fill_IterT_IterT_T__D(self.delta_:begin(), self.delta_:end_(), 0.0)
        local rz = 0.0
        do
          local i_9 = 0
          while L_ult(i_9, n) do
            do
              self.r_.a[i_9] = -self.residual_.a[i_9]
              self.z_.a[i_9] = self.r_.a[i_9] / self.diag_.a[i_9]
              self.p_.a[i_9] = self.z_.a[i_9]
              rz = rz + (self.r_.a[i_9] * self.z_.a[i_9])
            end
            i_9 = i_9 + 1
          end
        end
        t_4 = c.linear_relative * norm(self.r_)
        result.linear_tolerance = (c.linear_absolute < t_4) and t_4 or c.linear_absolute
        local linear_status = 5
        do
          local k = 0
          while true do
            do
              local recursive_norm = norm(self.r_)
              if not is_finite(recursive_norm) then
                linear_status = 3
                break
              end
              if recursive_norm <= result.linear_tolerance then
                linear_status = 0
                break
              end
              if k == c.max_linear then
                break
              end
              matvec(self.p_, self.ap_)
              local curvature = 0.0
              do
                local i_10 = 0
                while L_ult(i_10, n) do
                  do
                    curvature = curvature + (self.p_.a[i_10] * self.ap_.a[i_10])
                  end
                  i_10 = i_10 + 1
                end
              end
              if (not positive(curvature)) or (not positive(rz)) then
                linear_status = 4
                break
              end
              local alpha = rz / curvature
              do
                local i_11 = 0
                while L_ult(i_11, n) do
                  do
                    self.delta_.a[i_11] = self.delta_.a[i_11] + (alpha * self.p_.a[i_11])
                    self.r_.a[i_11] = self.r_.a[i_11] - (alpha * self.ap_.a[i_11])
                    self.z_.a[i_11] = self.r_.a[i_11] / self.diag_.a[i_11]
                  end
                  i_11 = i_11 + 1
                end
              end
              result.linear_iterations = (((result.linear_iterations + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
              local next_rz = 0.0
              do
                local i_12 = 0
                while L_ult(i_12, n) do
                  do
                    next_rz = next_rz + (self.r_.a[i_12] * self.z_.a[i_12])
                  end
                  i_12 = i_12 + 1
                end
              end
              local beta = next_rz / rz
              do
                local i_13 = 0
                while L_ult(i_13, n) do
                  do
                    self.p_.a[i_13] = self.z_.a[i_13] + (beta * self.p_.a[i_13])
                  end
                  i_13 = i_13 + 1
                end
              end
              rz = next_rz
            end
            k = k + 1
          end
        end
        matvec(self.delta_, self.ap_)
        do
          local i_14 = 0
          while L_ult(i_14, n) do
            do
              self.ap_.a[i_14] = (-self.residual_.a[i_14]) - self.ap_.a[i_14]
            end
            i_14 = i_14 + 1
          end
        end
        result.linear_residual = norm(self.ap_)
        if not is_finite(result.linear_residual) then
          linear_status = 3
        elseif (linear_status == 0) and (result.linear_residual > result.linear_tolerance) then
          linear_status = 6
        end
        if linear_status ~= 0 then
          result.status = linear_status
          do return Tfv_NonlinearPressureStorage_Result_MoveNew(result) end
        end
        local step = 1.0
        do
          local i_15 = 0
          while L_ult(i_15, n) do
            do
              if not is_finite(self.delta_.a[i_15]) then
                result.status = 3
                do return Tfv_NonlinearPressureStorage_Result_MoveNew(result) end
              end
              if self.delta_.a[i_15] < 0.0 then
                t_4 = (0.99 * (self.head_.a[i_15] - rows.a[i_15].lower_head)) / (-self.delta_.a[i_15])
                step = (t_4 < step) and t_4 or step
              elseif self.delta_.a[i_15] > 0.0 then
                t_4 = (0.99 * (rows.a[i_15].upper_head - self.head_.a[i_15])) / self.delta_.a[i_15]
                step = (t_4 < step) and t_4 or step
              end
            end
            i_15 = i_15 + 1
          end
        end
        local accepted = false
        do
          local back = 0
          while (back <= c.max_backtracks) and (step > 0.0) do
            do
              local admissible = true
              do
                local i_16 = 0
                while L_ult(i_16, n) do
                  do
                    self.trial_.a[i_16] = self.head_.a[i_16] + (step * self.delta_.a[i_16])
                    admissible = ((admissible and is_finite(self.trial_.a[i_16])) and (self.trial_.a[i_16] >= rows.a[i_16].lower_head)) and (self.trial_.a[i_16] <= rows.a[i_16].upper_head)
                  end
                  i_16 = i_16 + 1
                end
              end
              local scaled_2 = admissible and evaluate(self.trial_, self.trial_residual_) or K_INF
              if is_finite(scaled_2) and ((scaled_2 <= 1.0) or (scaled_2 <= ((1.0 - (0.0001 * step)) * result.scaled_residual))) then
                self.head_:swap(self.trial_)
                self.residual_:swap(self.trial_residual_)
                result.scaled_residual = scaled_2
                accepted = true
                result.newton_iterations = (((result.newton_iterations + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
                break
              end
              if back < c.max_backtracks then
                step = step * 0.5
                result.backtracks = (((result.backtracks + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
              end
            end
            back = back + 1
          end
        end
        if not accepted then
          result.status = 7
          do return Tfv_NonlinearPressureStorage_Result_MoveNew(result) end
        end
      end
      it = it + 1
    end
  end
end
