function O_Tclimate_MovingAvg7._new() return L_setmetatable({front = 0, count_f = 0}, O_Tclimate_MovingAvg7) end
function O_Tclimate_MovingAvg7.push(self, t_avg, t_range)
  self.ta[self.front] = t_avg
  self.tr[self.front] = t_range
  self.front = L_imod((((self.front + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000, 7)
  if self.count_f < 7 then
    self.count_f = (((self.count_f + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  end
end
function O_Tclimate_MovingAvg7.avg_temp(self)
  if self.count_f == 0 then
    do return 0.0 end
  end
  local sum = 0.0
  do
    local i = 0
    while i < self.count_f do
      do
        sum = sum + self.ta[i]
      end
      i = i + 1
    end
  end
  do return sum / self.count_f end
end
function O_Tclimate_MovingAvg7.avg_range(self)
  if self.count_f == 0 then
    do return 0.0 end
  end
  local sum = 0.0
  do
    local i = 0
    while i < self.count_f do
      do
        sum = sum + self.tr[i]
      end
      i = i + 1
    end
  end
  do return sum / self.count_f end
end
