-- ---- O_Tclimate_ClimateFileReader
O_Tclimate_ClimateFileReader = lua_class("Tclimate_ClimateFileReader", nil, {Cpp_ICopy, Cpp_IDisposable})
function O_Tclimate_ClimateFileReader._new() return L_setmetatable({format_ = 0, unit_system_ = 0, buf_year_ = 0, buf_month_ = 0, day_offset_ = 0.0, date_field_pos_ = 0, wind_type_ = 0, temp_units_ = 0, saved_line_ = CPtr_ZERO, has_saved_line_ = false}, O_Tclimate_ClimateFileReader) end
function O_Tclimate_ClimateFileReader.open(self, path, p, unit_system, temp_units)
  local t_1, t_2
  O_Tclimate_ClimateFileReader.close(self)
  self.unit_system_ = unit_system
  self.file_ = F_io_fopen_utf8(path, R_Lit("r"))
  if not (self.file_ ~= nil) then
    do return false end
  end
  local line = R_Buf_i(513)
  if not (not R_fgets(line, S_Tclimate_ClimateFileReader_MAX_LINE, self.file_):get_IsNull()) then
    O_Tclimate_ClimateFileReader.close(self)
    do return false end
  end
  self.format_ = O_Tclimate_ClimateFileReader.detectFormat(self, line)
  if self.format_ == 0 then
    O_Tclimate_ClimateFileReader.close(self)
    do return false end
  end
  if temp_units >= 0 then
    self.temp_units_ = temp_units
  end
  if self.format_ == 2 then
  else
    R_strncpy(self.saved_line_, line, S_Tclimate_ClimateFileReader_MAX_LINE)
    self.saved_line_:set(S_Tclimate_ClimateFileReader_MAX_LINE, 0)
    t_1, t_2 = {0}, 1
    t_1[t_2] = ((0 + 0x80) & 0xFF) - 0x80
    self.has_saved_line_ = true
  end
  do return true end
end
function O_Tclimate_ClimateFileReader.close(self)
  if self.file_ ~= nil then
    R_fclose(self.file_)
    self.file_ = nil
  end
  self.format_ = 0
  self.buf_month_ = (-1)
  self.buf_year_ = -1
  self.has_saved_line_ = false
end
function O_Tclimate_ClimateFileReader.getRecord(self, oa_date, rec)
  local y = {0}
  local m = {0}
  local d = {0}
  Tclimate_ClimateFileReader_oaDateToYMD(oa_date + self.day_offset_, y, 1, m, 1, d, 1)
  if (y[1] ~= self.buf_year_) or (m[1] ~= self.buf_month_) then
    if not O_Tclimate_ClimateFileReader.bufferMonth(self, y[1], m[1]) then
      do return false end
    end
  end
  if (d[1] < 1) or (d[1] > 31) then
    do return false end
  end
  rec.tmin = (self.file_data_[0][d[1]] > (S_Tclimate_ClimateFileReader_MISSING + 1.0)) and self.file_data_[0][d[1]] or Std_QNaN
  rec.tmax = (self.file_data_[1][d[1]] > (S_Tclimate_ClimateFileReader_MISSING + 1.0)) and self.file_data_[1][d[1]] or Std_QNaN
  rec.evap = (self.file_data_[2][d[1]] > (S_Tclimate_ClimateFileReader_MISSING + 1.0)) and self.file_data_[2][d[1]] or Std_QNaN
  rec.wind = (self.file_data_[3][d[1]] > (S_Tclimate_ClimateFileReader_MISSING + 1.0)) and self.file_data_[3][d[1]] or Std_QNaN
  do return true end
end
function O_Tclimate_ClimateFileReader.detectFormat(self, line)
  local t_1, t_2
  if L_ult(26, R_strlen(line)) then
    if (((((((((line:get(0) + 0x80) & 0xFF) - 0x80) == 68) and ((((line:get(1) + 0x80) & 0xFF) - 0x80) == 76)) and ((((line:get(2) + 0x80) & 0xFF) - 0x80) == 89)) and ((((line:get(23) + 0x80) & 0xFF) - 0x80) == 57)) and ((((line:get(24) + 0x80) & 0xFF) - 0x80) == 57)) and ((((line:get(25) + 0x80) & 0xFF) - 0x80) == 57)) and ((((line:get(26) + 0x80) & 0xFF) - 0x80) == 57) then
      do return 3 end
    end
  end
  if not L_ult(R_strlen(line), 233) then
    local param = R_BufOf(4, {n = 0})
