function O_Trdii_iface_RdiiInterfaceFile._new() return L_setmetatable({writing_ = false, binary_ = false, rdii_step_ = 0, flow_units_ = 0, start_date_ = 0.0, end_date_ = 0.0, have_record_ = false}, O_Trdii_iface_RdiiInterfaceFile) end
function O_Trdii_iface_RdiiInterfaceFile.openForRead(self, ctx, path)
  O_Trdii_iface_RdiiInterfaceFile.close(self)
  self.writing_ = false
  self.have_record_ = false
  self.start_date_ = S_F_rdii_iface__anon_hydrology_RdiiInterface_cpp_NO_DATE_RdiiInterface
  self.end_date_ = S_F_rdii_iface__anon_hydrology_RdiiInterface_cpp_NO_DATE_RdiiInterface
  self.fp_ = F_io_fopen_utf8(path, R_Lit("rb"))
  if not (self.fp_ ~= nil) then
    do return -1 end
  end
  local stamp = R_BufOf(16, {n = 0})
  local stamp_len = R_strlen(S_F_rdii_iface_RDII_FILE_STAMP_RdiiInterface)
  if (Mem_fread_CPtr_ul_ul_CFile(stamp, 1, stamp_len, self.fp_) == stamp_len) and (R_strncmp(stamp, S_F_rdii_iface_RDII_FILE_STAMP_RdiiInterface, stamp_len) == 0) then
    self.binary_ = true
    local rc = O_Trdii_iface_RdiiInterfaceFile.readBinaryHeader(self, ctx)
    if rc ~= 0 then
      O_Trdii_iface_RdiiInterfaceFile.close(self)
      do return rc end
    end
  else
    R_fclose(self.fp_)
    self.fp_ = F_io_fopen_utf8(path, R_Lit("rt"))
    if not (self.fp_ ~= nil) then
      do return -1 end
    end
    self.binary_ = false
    local rc_2 = O_Trdii_iface_RdiiInterfaceFile.readTextHeader(self, ctx)
    if rc_2 ~= 0 then
      O_Trdii_iface_RdiiInterfaceFile.close(self)
      do return rc_2 end
    end
  end
  O_Trdii_iface_RdiiInterfaceFile.readNextRecord(self)
  do return 0 end
end
function O_Trdii_iface_RdiiInterfaceFile.openForWrite(self, path, rdii_step, node_idx)
  O_Trdii_iface_RdiiInterfaceFile.close(self)
  if node_idx.n == 0 then
    do return -2 end
  end
  self.fp_ = F_io_fopen_utf8(path, R_Lit("wb"))
  if not (self.fp_ ~= nil) then
    do return -1 end
  end
  self.writing_ = true
  self.binary_ = true
  self.rdii_step_ = (rdii_step > 0) and rdii_step or 300
  self.node_idx_:Assign_VecT(node_idx)
  self.flows_:assign_ul_T(self.node_idx_.n, 0.0)
  Mem_fwrite_CPtr_ul_ul_CFile(S_F_rdii_iface_RDII_FILE_STAMP_RdiiInterface, 1, R_strlen(S_F_rdii_iface_RDII_FILE_STAMP_RdiiInterface), self.fp_)
  local step = self.rdii_step_
  local n = ((self.node_idx_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  R_fwriteI1(step, self.fp_)
  R_fwriteI1(n, self.fp_)
  local idx = Algo_VecFrom__I(self.node_idx_:begin(), self.node_idx_:end_())
  Mem_fwrite_PtrT_ul_ul_CFile__I(idx:data(), 4, idx.n, self.fp_)
  do return 0 end
end
function O_Trdii_iface_RdiiInterfaceFile.applyFlows(self, ctx, current_date)
  if (not (self.fp_ ~= nil)) or self.writing_ then
    do return end
  end
  while self.have_record_ do
    if current_date < self.start_date_ then
      do return end
    end
    if current_date < self.end_date_ then
      break
    end
    O_Trdii_iface_RdiiInterfaceFile.readNextRecord(self)
  end
  if not self.have_record_ then
    do return end
  end
  do
    local i = 0
    while L_ult(i, self.node_idx_.n) do
      do
        local j = self.node_idx_.a[i]
        if (j < 0) or (j >= (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
          goto cont2
        end
        local q = self.flows_.a[i]
        if L_abs(q) < S_F_constants_FLOW_TOL then
          goto cont2
        end
        ctx.nodes.rdii_inflow.a[j] = ctx.nodes.rdii_inflow.a[j] + q
      end
      ::cont2::
      i = i + 1
    end
  end
end
function O_Trdii_iface_RdiiInterfaceFile.saveFlows(self, current_date, node_flows)
  if (not (self.fp_ ~= nil)) or (not self.writing_) then
    do return end
  end
  do
    local i = 0
    while L_ult(i, self.node_idx_.n) do
      do
        local j = self.node_idx_.a[i]
        self.flows_.a[i] = L_ult(j, node_flows.n) and L_f32(node_flows.a[j]) or 0.0
      end
      i = i + 1
    end
  end
  R_fwriteD1(current_date, self.fp_)
  Mem_fwrite_PtrT_ul_ul_CFile__F(self.flows_:data(), 4, self.flows_.n, self.fp_)
end
function O_Trdii_iface_RdiiInterfaceFile.close(self)
  if self.fp_ ~= nil then
    R_fclose(self.fp_)
    self.fp_ = nil
  end
  self.writing_ = false
  self.have_record_ = false
end
function O_Trdii_iface_RdiiInterfaceFile.readBinaryHeader(self, ctx)
  local step = {0}
  local n_nodes = {0}
  if (R_freadI1(step, 1, self.fp_) ~= 1) or (step[1] <= 0) then
    do return -2 end
  end
  if (R_freadI1(n_nodes, 1, self.fp_) ~= 1) or (n_nodes[1] <= 0) then
    do return -2 end
  end
  self.rdii_step_ = step[1]
  self.node_idx_:assign_ul_T(n_nodes[1], -1)
  self.flows_:assign_ul_T(n_nodes[1], 0.0)
  local idx = NewVecI_ul(n_nodes[1])
  if Mem_fread_PtrT_ul_ul_CFile__I(idx:data(), 4, n_nodes[1], self.fp_) ~= n_nodes[1] then
    do return -2 end
  end
  do
    local i = 0
    while L_ult(i, idx.n) do
      do
        local j = idx.a[i]
        if (j < 0) or (j >= (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
          do return -2 end
        end
        self.node_idx_.a[i] = j
      end
      i = i + 1
    end
  end
  do return 0 end
end
function O_Trdii_iface_RdiiInterfaceFile.readTextHeader(self, ctx)
  local line = R_Buf_i(1025)
