  if (R_sscanf(line, R_Lit("%s"), s1) ~= 1) or (R_strncmp(s1, R_Lit("SWMM5"), 5) ~= 0) then
    do return -2 end
  end
  if not (not R_fgets(line, S_F_rdii_iface__anon_hydrology_RdiiInterface_cpp_MAXLINE_RdiiInterface, self.fp_):get_IsNull()) then
    do return -2 end
  end
  if not (not R_fgets(line, S_F_rdii_iface__anon_hydrology_RdiiInterface_cpp_MAXLINE_RdiiInterface, self.fp_):get_IsNull()) then
    do return -2 end
  end
  if (R_sscanf(line, R_Lit("%d"), R_RefI(function(v___sv)
  self.rdii_step_ = v___sv
  do return end
end)) ~= 1) or (self.rdii_step_ <= 0) then
    do return -2 end
  end
  if not (not R_fgets(line, S_F_rdii_iface__anon_hydrology_RdiiInterface_cpp_MAXLINE_RdiiInterface, self.fp_):get_IsNull()) then
