-- ---- O_Trunoff_RunoffSoA
O_Trunoff_RunoffSoA = lua_class("Trunoff_RunoffSoA", nil, {Cpp_ICopy})
function O_Trunoff_RunoffSoA._new() return L_setmetatable({n_subcatch = 0}, O_Trunoff_RunoffSoA) end
function O_Trunoff_RunoffSoA.resize(self, n)
  self.n_subcatch = n
  local un = n
  self.area:assign_ul_T(un, 0.0)
  self.width:assign_ul_T(un, 0.0)
  self.slope:assign_ul_T(un, 0.0)
  self.imperv_pct:assign_ul_T(un, 0.0)
  self.frac_imperv0:assign_ul_T(un, 0.0)
  self.frac_imperv1:assign_ul_T(un, 0.0)
  self.alpha_imperv:assign_ul_T(un, 0.0)
  self.alpha_perv:assign_ul_T(un, 0.0)
  self.ds_imperv:assign_ul_T(un, 0.0)
  self.ds_perv:assign_ul_T(un, 0.0)
  self.n_imperv:assign_ul_T(un, 0.01)
  self.n_perv:assign_ul_T(un, 0.1)
  self.depth_imperv0:assign_ul_T(un, 0.0)
  self.depth_imperv1:assign_ul_T(un, 0.0)
  self.depth_perv:assign_ul_T(un, 0.0)
  self.old_runoff_imperv0:assign_ul_T(un, 0.0)
  self.old_runoff_imperv1:assign_ul_T(un, 0.0)
  self.old_runoff_perv:assign_ul_T(un, 0.0)
  self.runoff:assign_ul_T(un, 0.0)
  self.evap_loss:assign_ul_T(un, 0.0)
  self.infil_loss:assign_ul_T(un, 0.0)
  self.perv_evap_vol:assign_ul_T(un, 0.0)
  self.actual_perv_evap_vol:assign_ul_T(un, 0.0)
  self.infil_vol:assign_ul_T(un, 0.0)
  self.spatial_infil_vol:assign_ul_T(un, 0.0)
  self.native_infil_rate:assign_ul_T(un, 0.0)
  self.subarea_runoff_rate:assign_ul_T(un, 0.0)
  self.imperv_runoff_cfs:assign_ul_T(un, 0.0)
  self.perv_runoff_cfs:assign_ul_T(un, 0.0)
  self.outflow_vol:assign_ul_T(un, 0.0)
  self.completed:assign_ul_T(un, {[0] = Trunoff_CompletedSubareaWater__new(), Trunoff_CompletedSubareaWater__new(), Trunoff_CompletedSubareaWater__new(), n = 3})
end
function O_Trunoff_RunoffSoA.computeAlpha(self)
  do
    local i = 0
    while i < self.n_subcatch do
      do
        local ui = i
        local sq_slope = L_sqrt(self.slope.a[ui])
        local fi = self.imperv_pct.a[ui]
        local fp = 1.0 - fi
        if self.area.a[ui] > 0.0 then
          local area_imperv = self.area.a[ui] * fi
          local area_perv = self.area.a[ui] * fp
          self.alpha_imperv.a[ui] = ((self.n_imperv.a[ui] > 0.0) and (area_imperv > 0.0)) and ((((S_F_runoff_PHI * self.width.a[ui]) / area_imperv) * sq_slope) / self.n_imperv.a[ui]) or 0.0
          self.alpha_perv.a[ui] = ((self.n_perv.a[ui] > 0.0) and (area_perv > 0.0)) and ((((S_F_runoff_PHI * self.width.a[ui]) / area_perv) * sq_slope) / self.n_perv.a[ui]) or 0.0
        end
      end
      i = i + 1
    end
  end
end
