-- ---- O_Trunoff_RunoffSolver
O_Trunoff_RunoffSolver = lua_class("Trunoff_RunoffSolver", nil, {Cpp_ICopy})
function O_Trunoff_RunoffSolver._new() return L_setmetatable({}, O_Trunoff_RunoffSolver) end
function O_Trunoff_RunoffSolver.init(self, ctx, spatial_areas)
  local t_1, t_2
  local n = ((ctx.subcatch_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local external_area = NewVecD_ul_T(n, -1.0)
  do
    local v___r1 = spatial_areas
    do
      local v___i2_n = v___r1.n
      for v___i2 = 0, v___i2_n - 1 do
        local e = v___r1.a[v___i2]
        local i = Std_get0_PairAB__ID(e)
        local area = Std_get1_PairAB__ID(e)
        if ((((i < 0) or (i >= n)) or (not is_finite(area))) or (area < 0.0)) or (external_area.a[i] >= 0.0) then
          L_error(NewInvalidArgument_Str(Str_from_CPtr(R_Lit("Invalid or duplicate reviewed non-LID source area."))), 0)
        end
        external_area.a[i] = area
      end
    end
  end
  O_Trunoff_RunoffSoA.resize(self.soa_, n)
  self.completed_step_seconds_:assign_ul_T(n, 0.0)
  self.spatial_full_area_ft2_:clear()
  if not (spatial_areas.n == 0) then
    self.spatial_full_area_ft2_:assign_ul_T(n, -1.0)
  end
  local ucf_area = F_ucf_UCF(4, ctx.options)
  local ucf_depth = F_ucf_UCF(1, ctx.options)
  do
    local i_2 = 0
    while i_2 < n do
      do
        local ui = i_2
        local full_area_ft2 = ctx.subcatches.area.a[ui] / ucf_area
        local lid_area_ft2 = ctx.subcatches.total_lid_area_ft2.a[ui]
        t_1 = full_area_ft2 - lid_area_ft2
        self.soa_.area.a[ui] = (0.0 < t_1) and t_1 or 0.0
        if external_area.a[ui] >= 0.0 then
          self.soa_.area.a[ui] = external_area.a[ui] / 0.09290304
          self.spatial_full_area_ft2_.a[ui] = self.soa_.area.a[ui] + lid_area_ft2
        end
        self.soa_.width.a[ui] = ctx.subcatches.width.a[ui]
        self.soa_.slope.a[ui] = ctx.subcatches.slope.a[ui]
        self.soa_.imperv_pct.a[ui] = ctx.subcatches.frac_imperv.a[ui]
        local fi_ = ctx.subcatches.frac_imperv.a[ui]
        local pz_ = ctx.subcatches.pct_zero.a[ui]
        self.soa_.frac_imperv0.a[ui] = (fi_ * pz_) / 100.0
        self.soa_.frac_imperv1.a[ui] = fi_ * (1.0 - (pz_ / 100.0))
        self.soa_.n_imperv.a[ui] = ctx.subcatches.n_imperv.a[ui]
        self.soa_.n_perv.a[ui] = ctx.subcatches.n_perv.a[ui]
        self.soa_.ds_imperv.a[ui] = ctx.subcatches.ds_imperv.a[ui] / ucf_depth
        self.soa_.ds_perv.a[ui] = ctx.subcatches.ds_perv.a[ui] / ucf_depth
      end
      i_2 = i_2 + 1
    end
  end
  O_Trunoff_RunoffSoA.computeAlpha(self.soa_)
  O_Tsurface_InfilBank.init(self.infil_bank_, n)
  self.infil_factor_used_:assign_ul_T(n, 1.0)
  do
    local i_3 = 0
    while i_3 < n do
      do
        local ui_2 = i_3
        if ctx.subcatches.infil_p4.a[ui_2] == 0.0 then
          t_1, t_2 = _ENV, "S_F_constants_TINY"
        else
          t_1, t_2 = ctx.subcatches.infil_p4.a, ui_2
        end
        local dry_time = t_1[t_2]
        local p = {[0] = ctx.subcatches.infil_p1.a[ui_2], ctx.subcatches.infil_p2.a[ui_2], ctx.subcatches.infil_p3.a[ui_2], dry_time, ctx.subcatches.infil_p5.a[ui_2], n = 5}
        O_Tsurface_InfilBank.setMethod(self.infil_bank_, i_3, ctx.subcatches.infil_model.a[ui_2], NewPtrD_TA_l(p, 0), ctx.options)
      end
      i_3 = i_3 + 1
    end
  end
end
function O_Trunoff_RunoffSolver.execute(self, ctx, dt, evap_rate_in, infil_factor, recovery_factor, month, boundary, source_forcing, spatial_fractions, source_owners)
  local t_10, t_11, t_12, t_13
  local process_timer = Tperf_ProcessTimer_New_ProcessPhase(19)
  local n = self.soa_.n_subcatch
  if source_forcing ~= nil then
    if ((not is_finite(dt)) or (dt <= 0.0)) or ((((ctx.subcatch_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) ~= n) then
      L_error(NewInvalidArgument_Str(Str_from_CPtr(R_Lit("Completed source solve requires a positive interval and matching source count."))), 0)
    end
    local previous = -1
    do
      local v___r1 = source_forcing
      do
        local v___i2_n = v___r1.n
        for v___i2 = 0, v___i2_n - 1 do
          local s = v___r1.a[v___i2]
          if (((((s.subcatch <= previous) or (s.subcatch >= n)) or (not is_finite(s.rain))) or (s.rain < 0.0)) or (not is_finite(s.pet))) or (s.pet < 0.0) then
            L_error(NewInvalidArgument_Str(Str_from_CPtr(R_Lit("Completed source rates require ordered unique sources and finite nonnegative rates."))), 0)
          end
          do
            local v___r3 = s.surface_return
            do
              local v___i4_n = v___r3.n
              for v___i4 = 0, v___i4_n - 1 do
                local rate = v___r3[v___i4]
                if (not is_finite(rate)) or (rate < 0.0) then
                  L_error(NewInvalidArgument_Str(Str_from_CPtr(R_Lit("Invalid completed surface return rate."))), 0)
                end
              end
            end
          end
          previous = s.subcatch
        end
      end
    end
  end
  if spatial_fractions ~= nil then
    if (not (source_forcing ~= nil)) or (spatial_fractions.n ~= n) then
      L_error(NewInvalidArgument_Str(Str_from_CPtr(R_Lit("Partial spatial intake requires completed forcing and matching fractions."))), 0)
    end
    do
      local v___r5 = spatial_fractions
      do
        local v___i6_n = v___r5.n
        for v___i6 = 0, v___i6_n - 1 do
          local f = v___r5.a[v___i6]
          if ((not is_finite(f)) or (f < 0.0)) or (f > 1.0) then
            L_error(NewInvalidArgument_Str(Str_from_CPtr(R_Lit("Invalid partial spatial intake fraction."))), 0)
          end
        end
      end
    end
  end
  if (source_owners ~= nil) and ((source_forcing ~= nil) or (source_owners.n ~= n)) then
    L_error(NewInvalidArgument_Str(Str_from_CPtr(R_Lit("Ordinary runoff ownership requires a matching exclusive source map."))), 0)
  end
  if n == 0 then
    do return end
  end
  local count = (source_forcing ~= nil) and (((source_forcing.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) or n
  local source = function(slot_in)
  local slot = {slot_in}
  local t_1, t_2
  if source_forcing ~= nil then
    t_1, t_2 = source_forcing.a[slot[1]], "subcatch"
  else
    t_1, t_2 = slot, 1
  end
  do return t_1[t_2] end
end
  local un = n
  self.precip_:resize_ul(un)
  self.evap_rate_:resize_ul(un)
  self.infil_rate_:resize_ul(un)
  local ucf_landarea = F_ucf_UCF(4, ctx.options)
  do
    local slot_2 = 0
    while slot_2 < count do
      do
        local i = source(slot_2)
        if (source_owners ~= nil) and (source_owners.a[i] >= 0) then
          goto cont4
        end
        local ui = i
        if source_forcing ~= nil then
          self.precip_.a[ui] = source_forcing.a[slot_2].rain
          ctx.subcatches.rainfall.a[ui] = self.precip_.a[ui]
          goto cont4
        end
        local p = F_gage_splitPrecip(ctx, ui)
        local rain = p.rainfall
        if L_ult(ui, ctx.forcing.subcatch_rainfall_mode.n) and (ctx.forcing.subcatch_rainfall_mode.a[ui] ~= 0) then
          local rain_inhr = p.rainfall * F_ucf_UCF(0, ctx.options)
          rain_inhr = O_ForcingData.effective_rainfall(ctx.forcing, ui, rain_inhr)
          rain = rain_inhr / F_ucf_UCF(0, ctx.options)
        end
        local snow = O_ForcingData.effective_snowfall(ctx.forcing, ui, p.snowfall)
        self.precip_.a[ui] = rain + snow
        ctx.subcatches.rainfall.a[ui] = self.precip_.a[ui]
      end
      ::cont4::
      slot_2 = slot_2 + 1
    end
  end
  do
    local slot_3 = 0
    while slot_3 < count do
      do
        local i_2 = source(slot_3)
        if (source_owners ~= nil) and (source_owners.a[i_2] >= 0) then
          goto cont5
        end
        local ui_2 = i_2
        if source_forcing ~= nil then
          self.evap_rate_.a[ui_2] = source_forcing.a[slot_3].pet
          goto cont5
        end
        local is_dry_only = ctx.options.evap_dry_only
        local rain_2 = self.precip_.a[ui_2] * F_ucf_UCF(0, ctx.options)
        local broadcast = (is_dry_only and (rain_2 > 0.0)) and 0.0 or evap_rate_in
        self.evap_rate_.a[ui_2] = O_ForcingData.effective_evap_rate(ctx.forcing, ui_2, broadcast)
      end
      ::cont5::
      slot_3 = slot_3 + 1
    end
  end
  local processSource = function(slot_4)
  local t_3
  local i_3 = source(slot_4)
  if (source_owners ~= nil) and (source_owners.a[i_3] >= 0) then
    do return end
  end
  local ui_3 = i_3
  local fi = self.soa_.imperv_pct.a[ui_3]
  local fp = 1.0 - fi
  local f0 = self.soa_.frac_imperv0.a[ui_3]
  local f1 = self.soa_.frac_imperv1.a[ui_3]
  local total_area = self.soa_.area.a[ui_3]
  local precip = self.precip_.a[ui_3]
  local evapRate = self.evap_rate_.a[ui_3]
  local snow_open_imperv = 1.0
  local snow_open_perv = 1.0
  local snowpack = ctx.subcatches.snowpack.a[ui_3]
