-- ---- O_Tsnow_DegreeDaySnow
O_Tsnow_DegreeDaySnow = lua_class("Tsnow_DegreeDaySnow", O_Tsurface_SnowModel, {Cpp_ICopy})
function O_Tsnow_DegreeDaySnow._new() return L_setmetatable({}, O_Tsnow_DegreeDaySnow) end
function O_Tsnow_DegreeDaySnow.init(self, n_subcatch)
  O_Tsnow_SnowSoA.resize(self.soa_, n_subcatch)
end
function O_Tsnow_DegreeDaySnow.execute(self, p, dt, temp, wind, rainfall, snowfall, gamma, ea)
  local process_timer = Tperf_ProcessTimer_New_ProcessPhase(25)
  local n = self.soa_.n_subcatch
  if n == 0 then
    do return end
  end
  do
    local j = 0
    while j < n do
      do
        if (not (self.soa_.enabled.a[j] ~= 0)) or ((j < (((self.soa_.external.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) and self.soa_.external.a[j]) then
          goto cont1
        end
        local uj = j
        local rain = rainfall.a[rainfall.o + uj]
        local snow = snowfall.a[snowfall.o + uj]
        local rmelt = Tsnow_DegreeDaySnow_rainMeltRate(temp, wind, gamma, ea, rain)
        local first = (((j * S_F_snow_N_SUBAREAS) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        if ((self.soa_.wsnow.a[first] <= (8.333333333333333E-05)) and (self.soa_.wsnow.a[first + 1] <= (8.333333333333333E-05))) and (self.soa_.wsnow.a[first + 2] <= (8.333333333333333E-05)) then
          if self.soa_.track_age then
            F_snow__anon_hydrology_surface_DegreeDaySnow_cpp_meltThinPack__rSnowSoA_ul_d_DegreeDaySnow(self.soa_, first, dt)
          else
            F_snow__anon_hydrology_surface_DegreeDaySnow_cpp_meltThinPack__rSnowSoA_ul_d_DegreeDaySnow_t2(self.soa_, first, dt)
          end
          goto cont1
        end
        do
          local i = S_F_snow_SNOW_PLOWABLE
          while i <= S_F_snow_SNOW_PERV do
            do
              local ui = ((((j * S_F_snow_N_SUBAREAS) + i) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
              O_Tsnow_DegreeDaySnow.meltElement(self, ui, i, dt, temp, rain, snow, rmelt)
            end
            i = i + 1
          end
        end
      end
      ::cont1::
      j = j + 1
    end
  end
end
function O_Tsnow_DegreeDaySnow.setMeltCoeffs(self, day_of_year)
  local kSeasonRad = 0.0172615
  local season = L_sin(kSeasonRad * (day_of_year - 81.0))
  self.soa_.season = season
  local total = (((self.soa_.n_subcatch * S_F_snow_N_SUBAREAS) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  do
    local i = 0
    while i < total do
      do
        local ui = i
        self.soa_.dhm.a[ui] = 0.5 * ((self.soa_.dhmax.a[ui] * (1.0 + season)) + (self.soa_.dhmin.a[ui] * (1.0 - season)))
      end
      i = i + 1
    end
  end
end
function O_Tsnow_DegreeDaySnow.plowSnow(self, ctx, dt, snowfall)
  local n = self.soa_.n_subcatch
  if n == 0 then
    do return end
  end
  do
    local j = 0
    while j < n do
      do
        if (not (self.soa_.enabled.a[j] ~= 0)) or ((j < (((self.soa_.external.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) and self.soa_.external.a[j]) then
          goto cont1
        end
        local uj = j
        do
          local k = S_F_snow_SNOW_PLOWABLE
          while k <= S_F_snow_SNOW_PERV do
            do
              local idx = ((((j * S_F_snow_N_SUBAREAS) + k) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
              if self.soa_.fArea.a[idx] > 0.0 then
                local add = snowfall.a[snowfall.o + uj] * dt
                if self.soa_.track_age then
                  local have = self.soa_.wsnow.a[idx] + self.soa_.fw.a[idx]
                  if have > 0.0 then
                    self.soa_.age.a[idx] = self.soa_.age.a[idx] + dt
                  end
                  if add > 0.0 then
                    self.soa_.age.a[idx] = F_snow_mixAge_DegreeDaySnow(have, self.soa_.age.a[idx], add, self.soa_.precip_age)
                  end
                end
                self.soa_.wsnow.a[idx] = self.soa_.wsnow.a[idx] + add
                self.soa_.imelt.a[idx] = 0.0
              end
            end
            k = k + 1
          end
        end
      end
      ::cont1::
      j = j + 1
    end
  end
  do
    local j_2 = 0
    while j_2 < n do
      do
        if (not (self.soa_.enabled.a[j_2] ~= 0)) or ((j_2 < (((self.soa_.external.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) and self.soa_.external.a[j_2]) then
          goto cont3
        end
        local uj_2 = j_2
        local plow_idx = ((((j_2 * S_F_snow_N_SUBAREAS) + S_F_snow_SNOW_PLOWABLE) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        if self.soa_.fArea.a[plow_idx] <= 0.0 then
          goto cont3
        end
        if self.soa_.wsnow.a[plow_idx] < self.soa_.weplow.a[uj_2] then
          goto cont3
        end
        local exc = self.soa_.wsnow.a[plow_idx]
        local sf = (((j_2 * 5) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        local sfracTotal = 0.0
        local donor_age = self.soa_.track_age and self.soa_.age.a[plow_idx] or 0.0
        if self.soa_.sfrac.a[sf + 0] > 0.0 then
          local lid_ft2 = L_ult(uj_2, ctx.subcatches.total_lid_area_ft2.n) and ctx.subcatches.total_lid_area_ft2.a[uj_2] or 0.0
          local area_ft2 = (ctx.subcatches.area.a[uj_2] / F_ucf_UCF(4, ctx.options)) - lid_ft2
          if area_ft2 < 0.0 then
            area_ft2 = 0.0
          end
          self.soa_.removed = self.soa_.removed + (((self.soa_.sfrac.a[sf + 0] * exc) * self.soa_.fArea.a[plow_idx]) * area_ft2)
        end
        sfracTotal = sfracTotal + self.soa_.sfrac.a[sf + 0]
        local imperv_idx = ((((j_2 * S_F_snow_N_SUBAREAS) + S_F_snow_SNOW_IMPERV) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        if self.soa_.fArea.a[imperv_idx] > 0.0 then
          local f = self.soa_.fArea.a[plow_idx] / self.soa_.fArea.a[imperv_idx]
          local moved = (self.soa_.sfrac.a[sf + 1] * exc) * f
          if self.soa_.track_age and (moved > 0.0) then
            self.soa_.age.a[imperv_idx] = F_snow_mixAge_DegreeDaySnow(self.soa_.wsnow.a[imperv_idx] + self.soa_.fw.a[imperv_idx], self.soa_.age.a[imperv_idx], moved, donor_age)
          end
          self.soa_.wsnow.a[imperv_idx] = self.soa_.wsnow.a[imperv_idx] + moved
          sfracTotal = sfracTotal + self.soa_.sfrac.a[sf + 1]
        end
        local perv_idx = ((((j_2 * S_F_snow_N_SUBAREAS) + S_F_snow_SNOW_PERV) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        if self.soa_.fArea.a[perv_idx] > 0.0 then
          local f_2 = self.soa_.fArea.a[plow_idx] / self.soa_.fArea.a[perv_idx]
          local moved_2 = (self.soa_.sfrac.a[sf + 2] * exc) * f_2
          if self.soa_.track_age and (moved_2 > 0.0) then
            self.soa_.age.a[perv_idx] = F_snow_mixAge_DegreeDaySnow(self.soa_.wsnow.a[perv_idx] + self.soa_.fw.a[perv_idx], self.soa_.age.a[perv_idx], moved_2, donor_age)
          end
          self.soa_.wsnow.a[perv_idx] = self.soa_.wsnow.a[perv_idx] + moved_2
          sfracTotal = sfracTotal + self.soa_.sfrac.a[sf + 2]
        end
        if dt > 0.0 then
