function O_DefaultInputPlugin.read(self, path, ctx)
  local reader = Tinput_InputReader_New_rSectionRegistry(self.registry_)
  local ok = O_Tinput_InputReader.read(reader, path, ctx)
  self.skipped_sections_:Assign_VecT(reader.skipped_sections_)
  if not ok then
    self.last_error_:Assign_Str(ctx.error_message)
    do return (ctx.error_code ~= 0) and ctx.error_code or (-1) end
  end
  do return 0 end
end
