              if L_ult(pi, ctx.mass_balance.qual_routing_ex_in.n) then
                ctx.mass_balance.qual_routing_ex_in.a[pi] = ctx.mass_balance.qual_routing_ex_in.a[pi] + (mass_rate * dt)
              end
            end
            ::cont2::
            p = p + 1
          end
        end
      end
      ::cont1::
      i = i + 1
    end
  end
end
function O_Tquality_QualitySolver.addQualityOnlyInflows(self, ctx, dt)
  if not (dt > 0.0) then
    do return end
  end
  local np = ((ctx.pollutant_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local ns = ((ctx.reactions.species_name.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local nodes = ctx.nodes
  local mb = ctx.mass_balance
  local apply = function(q, row)
  local t_1
  if not q.any then
    do return end
  end
  t_1 = ((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local nn = (L_ult(t_1, q.vol.n)) and t_1 or q.vol.n
  local rx = ctx.reactions
  if (ns > 0) and (rx.msx_ext_mass_in.n ~= ((((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) * ns)) then
    rx.msx_ext_mass_in:assign_ul_T((((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) * ns, 0.0)
  end
  do
    local i = 0
    while L_ult(i, nn) do
      do
        if q.vol.a[i] <= 0.0 then
          goto cont1
        end
        nodes.qual_vol_in.a[i] = nodes.qual_vol_in.a[i] + q.vol.a[i]
        do
          local p = 0
          while p < np do
            do
              local k = (i * np) + p
              if (not L_ult(k, q.mass.n)) or (not L_ult(k, nodes.qual_mass_in.n)) then
                goto cont2
              end
              nodes.qual_mass_in.a[k] = nodes.qual_mass_in.a[k] + (q.mass.a[k] / dt)
              if L_ult(p, row.n) then
                row.a[p] = row.a[p] + q.mass.a[k]
              end
            end
            ::cont2::
            p = p + 1
          end
        end
        do
          local m = 0
          while m < ns do
            do
              local k_2 = (i * ns) + m
              if L_ult(k_2, q.msx.n) and L_ult(k_2, rx.msx_ext_mass_in.n) then
                rx.msx_ext_mass_in.a[k_2] = rx.msx_ext_mass_in.a[k_2] + (q.msx.a[k_2] / dt)
              end
            end
            m = m + 1
          end
        end
        if ctx.options.water_age and L_ult(i, ctx.water_age_state.node_age_vol_in.n) then
          ctx.water_age_state.node_age_vol_in.a[i] = ctx.water_age_state.node_age_vol_in.a[i] + (q.age_vol.a[i] / dt)
        end
        if ctx.options.heat_transport and L_ult(i, ctx.heat_state.node_temp_vol_in.n) then
          ctx.heat_state.node_temp_vol_in.a[i] = ctx.heat_state.node_temp_vol_in.a[i] + (q.temp_vol.a[i] / dt)
        end
      end
      ::cont1::
      i = i + 1
    end
  end
  O_SimulationContext_QualityOnlyInflow.clear(q)
  do return end
end
  apply(ctx.surface_outfall_quality, mb.qual_routing_ex_in)
  apply(ctx.link_gain_quality, mb.qual_routing_gw_in)
end
function O_Tquality_QualitySolver.addWetWeatherLoads(self, ctx, dt)
  local np = self.n_pollutants_
  do
    local i = 0
    while i < (((ctx.subcatch_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local ui = i
        local out_node = ctx.subcatches.outlet_node.a[ui]
        if (out_node < 0) or (out_node >= (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
          goto cont1
        end
        local ud = out_node
        local f = ctx.runoff_interp_f
        local f1 = 1.0 - f
        local q_new = ctx.subcatches.runoff.a[ui]
        local q_old = ctx.subcatches.old_runoff.a[ui]
        local q = (f1 * q_old) + (f * q_new)
        if q <= 0.0 then
          goto cont1
        end
        ctx.nodes.qual_vol_in.a[ud] = ctx.nodes.qual_vol_in.a[ud] + (q * dt)
        if L_ult(ud, self.qual_vol_lat_.n) then
          self.qual_vol_lat_.a[ud] = self.qual_vol_lat_.a[ud] + (q * dt)
        end
        do
          local have_sc = ctx.options.water_age and L_ult(ui, ctx.water_age_state.subcatch_runoff_age.n)
          if have_sc then
            local acc = ctx.water_age_state.node_age_vol_in
            if L_ult(ud, acc.n) then
              acc.a[ud] = acc.a[ud] + (q * ctx.water_age_state.subcatch_runoff_age.a[ui])
            end
          else
            F_quality__anon_quality_QualityRouting_cpp_addAgeVolume_QualityRouting(ctx, out_node, q, 0)
          end
        end
        do
          local have_sc_2 = ctx.options.heat_transport and L_ult(ui, ctx.heat_state.subcatch_runoff_temp.n)
          if have_sc_2 then
            local acc_2 = ctx.heat_state.node_temp_vol_in
            if L_ult(ud, acc_2.n) then
              acc_2.a[ud] = acc_2.a[ud] + (q * ctx.heat_state.subcatch_runoff_temp.a[ui])
            end
          else
            F_quality__anon_quality_QualityRouting_cpp_addTempVolume_QualityRouting(ctx, out_node, q, 0)
          end
        end
        do
          local p = 0
          while p < np do
            do
              local sc_idx = (ui * np) + p
              local nd_idx = (ud * np) + p
              local c_new = L_ult(sc_idx, ctx.subcatches.conc.n) and ctx.subcatches.conc.a[sc_idx] or 0.0
              local c_old = L_ult(sc_idx, ctx.subcatches.conc_old.n) and ctx.subcatches.conc_old.a[sc_idx] or 0.0
              local mass_rate = (f1 * (q_old * c_old)) + (f * (q_new * c_new))
              if (mass_rate > 0.0) and L_ult(nd_idx, ctx.nodes.qual_mass_in.n) then
                ctx.nodes.qual_mass_in.a[nd_idx] = ctx.nodes.qual_mass_in.a[nd_idx] + mass_rate
              end
              local pi = p
              if (mass_rate > 0.0) and L_ult(pi, ctx.mass_balance.qual_routing_wet.n) then
                ctx.mass_balance.qual_routing_wet.a[pi] = ctx.mass_balance.qual_routing_wet.a[pi] + (mass_rate * dt)
              end
            end
            p = p + 1
          end
        end
      end
      ::cont1::
      i = i + 1
    end
  end
  local f_dr = ctx.runoff_interp_f
  local f1_dr = 1.0 - f_dr
  do
    local j = 0
    while j < (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local uj = j
        local v_new = L_ult(uj, ctx.nodes.lid_drain_qual_vol.n) and ctx.nodes.lid_drain_qual_vol.a[uj] or 0.0
        local v_old = L_ult(uj, ctx.nodes.lid_drain_qual_vol_old.n) and ctx.nodes.lid_drain_qual_vol_old.a[uj] or 0.0
        local drain_vol_rate = (f1_dr * v_old) + (f_dr * v_new)
        if drain_vol_rate <= 0.0 then
          goto cont3
        end
        ctx.nodes.qual_vol_in.a[uj] = ctx.nodes.qual_vol_in.a[uj] + (drain_vol_rate * dt)
        if L_ult(uj, self.qual_vol_lat_.n) then
          self.qual_vol_lat_.a[uj] = self.qual_vol_lat_.a[uj] + (drain_vol_rate * dt)
        end
        if (ctx.options.water_age and L_ult(uj, ctx.water_age_state.node_lid_drain_age_vol_in.n)) and ((ctx.lid_layer_state.n_units > 0) and (ctx.lid_layer_state.n_species_f > 0)) then
          local acc_3 = ctx.water_age_state.node_age_vol_in
          if L_ult(uj, acc_3.n) then
            acc_3.a[uj] = acc_3.a[uj] + ctx.water_age_state.node_lid_drain_age_vol_in.a[uj]
          end
        else
          F_quality__anon_quality_QualityRouting_cpp_addAgeVolume_QualityRouting(ctx, j, drain_vol_rate, 0)
        end
        if (ctx.options.heat_transport and L_ult(uj, ctx.heat_state.node_lid_drain_temp_vol_in.n)) and ((ctx.lid_layer_state.n_units > 0) and (ctx.lid_layer_state.n_species_f > 0)) then
          local tacc = ctx.heat_state.node_temp_vol_in
          if L_ult(uj, tacc.n) then
            tacc.a[uj] = tacc.a[uj] + ctx.heat_state.node_lid_drain_temp_vol_in.a[uj]
          end
        else
          F_quality__anon_quality_QualityRouting_cpp_addTempVolume_QualityRouting(ctx, j, drain_vol_rate, 0)
        end
        do
          local p_2 = 0
          while p_2 < np do
            do
              local nd_idx_2 = (uj * np) + p_2
              local w_new = L_ult(nd_idx_2, ctx.nodes.lid_drain_qual_load.n) and ctx.nodes.lid_drain_qual_load.a[nd_idx_2] or 0.0
              local w_old = L_ult(nd_idx_2, ctx.nodes.lid_drain_qual_load_old.n) and ctx.nodes.lid_drain_qual_load_old.a[nd_idx_2] or 0.0
              local v_load = (f1_dr * w_old) + (f_dr * w_new)
              if (v_load > 0.0) and L_ult(nd_idx_2, ctx.nodes.qual_mass_in.n) then
                ctx.nodes.qual_mass_in.a[nd_idx_2] = ctx.nodes.qual_mass_in.a[nd_idx_2] + v_load
              end
              local pi_2 = p_2
              if (v_load > 0.0) and L_ult(pi_2, ctx.mass_balance.qual_routing_wet.n) then
                ctx.mass_balance.qual_routing_wet.a[pi_2] = ctx.mass_balance.qual_routing_wet.a[pi_2] + (v_load * dt)
              end
            end
            p_2 = p_2 + 1
          end
        end
      end
      ::cont3::
      j = j + 1
    end
  end
end
function O_Tquality_QualitySolver.updateLinkQuality(self, ctx, dt)
  local t_1, t_2
  local np = self.n_pollutants_
  local links = ctx.links
  local nodes = ctx.nodes
  local poll = ctx.pollutants
  local mb = ctx.mass_balance
  local is_steady = ctx.options.routing_model == 0
  local reactions_active = ctx.reactions.configured and ctx.reactions.compiled
  local v_CD = ctx.link_subtypes.conduits
  do
    local j = 0
    while j < (((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local uj = j
        if links.flow.a[uj] >= 0.0 then
          t_1, t_2 = links.node1.a, uj
        else
          t_1, t_2 = links.node2.a, uj
        end
        local upstream = t_1[t_2]
        if (upstream < 0) or (upstream >= (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
          goto cont1
        end
        local un = upstream
        if F_quality_linkTakesUpstreamValue(ctx, j) then
          do
            local p = 0
            while p < np do
              do
                local li = (uj * np) + p
                local ni = (un * np) + p
                if (not L_ult(li, links.conc.n)) or (not L_ult(ni, nodes.conc.n)) then
                  break
                end
                links.conc.a[li] = F_lidnode_outletQuality(ctx, upstream, j, p, nodes.conc.a[ni])
              end
              p = p + 1
            end
          end
          goto cont1
        end
        local cr = O_LinkSubtypes.row_in(ctx.link_subtypes, j, ctx.link_subtypes.conduits.link_idx)
        local ucr = (cr < 0) and 0 or cr
        local barrels = (cr >= 0) and (v_CD.barrels.a[ucr] + 0.0) or 1.0
        local q_seep = (cr >= 0) and (v_CD.seep_loss_rate.a[ucr] * barrels) or 0.0
        local v_evap = (cr >= 0) and ((v_CD.evap_loss_rate.a[ucr] * barrels) * dt) or 0.0
        local v_old = links.old_volume.a[uj]
        local f_evap = 1.0
        if (v_evap > 0.0) and (v_old > S_F_quality_ZERO_VOLUME) then
          f_evap = f_evap + (v_evap / v_old)
        end
        local q_in = F_quality_conduitMixingInflow(ctx, j, dt)
        local dry = (not is_steady) and F_quality_linkIsDry(ctx, j)
        do
          local p_2 = 0
          while p_2 < np do
            do
              local li_2 = (uj * np) + p_2
              local ni_2 = (un * np) + p_2
              if (not L_ult(li_2, links.conc.n)) or (not L_ult(ni_2, nodes.conc.n)) then
                goto cont3
              end
              local up = p_2
              local k = L_ult(up, poll.k_decay.n) and poll.k_decay.a[up] or 0.0
              if reactions_active then
                k = 0.0
              end
              local c_new = 0.0
              local reacted = 0.0
              local seeped = 0.0
              if is_steady then
                local n1 = links.node1.a[uj]
                if (n1 < 0) or (n1 >= (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
                  goto cont3
                end
                local n1i = (n1 * np) + up
                if not L_ult(n1i, nodes.conc.n) then
                  goto cont3
                end
                local c1 = nodes.conc.a[n1i]
                seeped = (q_seep * c1) * dt
                c1 = c1 * f_evap
                c_new = c1
                if k > 0.0 then
                  t_1 = c1 * L_exp((-k) * dt)
                  c_new = (0.0 < t_1) and t_1 or 0.0
                  reacted = ((c1 - c_new) * links.flow.a[uj]) * dt
                end
              else
                local c1_2 = links.conc_old.a[li_2]
                seeped = (q_seep * c1_2) * dt
                c1_2 = c1_2 * f_evap
                t_1 = 1.0 - (k * dt)
                local c2 = c1_2 * ((t_1 < 0.0) and 0.0 or t_1)
                reacted = (c1_2 - c2) * v_old
                if q_in <= S_F_quality_LEGACY_ZERO then
                  c_new = c2
                else
                  local w_in = F_lidnode_outletQuality(ctx, upstream, j, p_2, nodes.conc.a[ni_2]) * q_in
                  local v_in = q_in * dt
                  local c_in = (w_in * dt) / v_in
                  local c_max = (c2 < c_in) and c_in or c2
                  c_new = ((c2 * v_old) + (w_in * dt)) / (v_old + v_in)
                  c_new = (c_max < c_new) and c_max or c_new
                  c_new = (c_new < 0.0) and 0.0 or c_new
                end
                if dry then
                  if L_ult(up, mb.qual_routing_final_dry.n) then
                    mb.qual_routing_final_dry.a[up] = mb.qual_routing_final_dry.a[up] + (c_new * links.volume.a[uj])
                  end
                  c_new = 0.0
                end
              end
              c_new = (c_new < 0.0) and 0.0 or c_new
              links.conc.a[li_2] = c_new
              if (reacted > 0.0) and L_ult(up, mb.qual_routing_reacted.n) then
                mb.qual_routing_reacted.a[up] = mb.qual_routing_reacted.a[up] + reacted
              end
              if (seeped ~= 0.0) and L_ult(up, mb.qual_routing_seep.n) then
                mb.qual_routing_seep.a[up] = mb.qual_routing_seep.a[up] + seeped
              end
            end
            ::cont3::
            p_2 = p_2 + 1
          end
        end
      end
      ::cont1::
      j = j + 1
    end
  end
end
function O_Tquality_QualitySolver.applyTreatment(self, ctx, dt, full_inflow)
  local np = self.n_pollutants_
  if np <= 0 then
    do return end
  end
  local treat = ctx.treatment
  if not O_TreatmentData.hasAny(treat) then
    do return end
  end
  local nodes = ctx.nodes
  local nn = ((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  do
    local j = 0
    while j < nn do
      do
        local uj = j
        if not treat.has_treatment.a[uj] then
          goto cont1
        end
        local vol_in = nodes.qual_vol_in.a[uj]
        local q_raw = (dt > 0.0) and (vol_in / dt) or 0.0
        do
          local p = 0
          while p < np do
            do
              local mi = (uj * np) + p
              local have = L_ult(mi, nodes.qual_mass_in.n)
              if full_inflow then
                treat.cin.a[p] = ((q_raw > 0.0) and have) and (nodes.qual_mass_in.a[mi] / q_raw) or 0.0
              else
                treat.cin.a[p] = ((vol_in > 0.0) and have) and (nodes.qual_mass_in.a[mi] / vol_in) or 0.0
              end
            end
            p = p + 1
          end
        end
        F_quality_applyNodeTreatment(ctx, j, dt, q_raw, treat.cin:data())
      end
      ::cont1::
      j = j + 1
    end
  end
end
function O_Tquality_QualitySolver.addRdiiLoads(self, ctx, dt)
  local np = self.n_pollutants_
  if not (((((np > 0) or (((ctx.options.quality_solver == 1) and (not ctx.options.ignore_quality)) and (not (ctx.ard_config.bc_node.n == 0)))) or ctx.options.water_age) or ctx.options.heat_transport) or (ctx.reactions.configured and ctx.reactions.compiled)) then
    do return end
  end
  local nodes = ctx.nodes
  do
    local i = 0
    while i < (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local ui = i
        local q = nodes.rdii_inflow.a[ui]
        if q <= 0.0 then
          goto cont1
        end
        nodes.qual_vol_in.a[ui] = nodes.qual_vol_in.a[ui] + (q * dt)
        self.qual_vol_lat_.a[ui] = self.qual_vol_lat_.a[ui] + (q * dt)
        F_quality__anon_quality_QualityRouting_cpp_addAgeVolume_QualityRouting(ctx, i, q, 3)
        F_quality__anon_quality_QualityRouting_cpp_addTempVolume_QualityRouting(ctx, i, q, 3)
        do
          local p = 0
          while p < np do
            do
              local c_rdii = ctx.pollutants.c_rdii.a[p]
              if c_rdii <= 0.0 then
                goto cont2
              end
              local nd_idx = (ui * np) + p
              if L_ult(nd_idx, nodes.qual_mass_in.n) then
                nodes.qual_mass_in.a[nd_idx] = nodes.qual_mass_in.a[nd_idx] + (q * c_rdii)
              end
            end
            ::cont2::
            p = p + 1
          end
        end
        do
          local p_2 = 0
          while p_2 < np do
            do
              local c_rdii_2 = ctx.pollutants.c_rdii.a[p_2]
              if c_rdii_2 <= 0.0 then
                goto cont3
              end
              local pi = p_2
              if L_ult(pi, ctx.mass_balance.qual_routing_ii_in.n) then
                ctx.mass_balance.qual_routing_ii_in.a[pi] = ctx.mass_balance.qual_routing_ii_in.a[pi] + ((q * c_rdii_2) * dt)
              end
            end
            ::cont3::
            p_2 = p_2 + 1
          end
        end
      end
      ::cont1::
      i = i + 1
    end
  end
end
function O_Tquality_QualitySolver.addDwfLoads(self, ctx, dt)
  local np = self.n_pollutants_
  if not (((((np > 0) or (((ctx.options.quality_solver == 1) and (not ctx.options.ignore_quality)) and (not (ctx.ard_config.bc_node.n == 0)))) or ctx.options.water_age) or ctx.options.heat_transport) or (ctx.reactions.configured and ctx.reactions.compiled)) then
    do return end
  end
  local nodes = ctx.nodes
  do
    local i = 0
    while i < (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local ui = i
        local q = nodes.dwf_inflow.a[ui]
        if (q < 0.0) and L_ult(ui, self.qual_vol_lat_neg_.n) then
          self.qual_vol_lat_neg_.a[ui] = self.qual_vol_lat_neg_.a[ui] + (q * dt)
        end
        if q <= 0.0 then
          goto cont1
        end
        nodes.qual_vol_in.a[ui] = nodes.qual_vol_in.a[ui] + (q * dt)
        self.qual_vol_lat_.a[ui] = self.qual_vol_lat_.a[ui] + (q * dt)
        F_quality__anon_quality_QualityRouting_cpp_addAgeVolume_QualityRouting(ctx, i, q, 1)
        F_quality__anon_quality_QualityRouting_cpp_addTempVolume_QualityRouting(ctx, i, q, 1)
        do
          local p = 0
          while p < np do
            do
              local c_dwf = ctx.pollutants.c_dwf.a[p]
              local nd_idx = (ui * np) + p
              local w_adj = L_ult(nd_idx, nodes.dwf_qual_mass.n) and nodes.dwf_qual_mass.a[nd_idx] or 0.0
              local w = ((c_dwf > 0.0) and (q * c_dwf) or 0.0) + w_adj
              if w == 0.0 then
                goto cont2
              end
              if L_ult(nd_idx, nodes.qual_mass_in.n) then
                nodes.qual_mass_in.a[nd_idx] = nodes.qual_mass_in.a[nd_idx] + w
              end
              local pi = p
              if L_ult(pi, ctx.mass_balance.qual_routing_dw_in.n) then
                ctx.mass_balance.qual_routing_dw_in.a[pi] = ctx.mass_balance.qual_routing_dw_in.a[pi] + (w * dt)
              end
            end
            ::cont2::
            p = p + 1
          end
        end
      end
      ::cont1::
      i = i + 1
    end
  end
end
function O_Tquality_QualitySolver.addGwLoads(self, ctx, dt)
  local np = self.n_pollutants_
  if not (((((np > 0) or (((ctx.options.quality_solver == 1) and (not ctx.options.ignore_quality)) and (not (ctx.ard_config.bc_node.n == 0)))) or ctx.options.water_age) or ctx.options.heat_transport) or (ctx.reactions.configured and ctx.reactions.compiled)) then
    do return end
  end
  local nodes = ctx.nodes
  do
    local i = 0
    while i < (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local ui = i
        local q = nodes.gw_inflow.a[ui]
        if (q < 0.0) and L_ult(ui, self.qual_vol_lat_neg_.n) then
          self.qual_vol_lat_neg_.a[ui] = self.qual_vol_lat_neg_.a[ui] + (q * dt)
        end
        if q <= 0.0 then
          goto cont1
        end
        nodes.qual_vol_in.a[ui] = nodes.qual_vol_in.a[ui] + (q * dt)
        self.qual_vol_lat_.a[ui] = self.qual_vol_lat_.a[ui] + (q * dt)
        F_quality__anon_quality_QualityRouting_cpp_addAgeVolume_QualityRouting(ctx, i, q, 2)
        F_quality__anon_quality_QualityRouting_cpp_addTempVolume_QualityRouting(ctx, i, q, 2)
        do
          local p = 0
          while p < np do
            do
              local c_gw = ctx.pollutants.c_gw.a[p]
              if c_gw <= 0.0 then
                goto cont2
              end
              local nd_idx = (ui * np) + p
              if L_ult(nd_idx, nodes.qual_mass_in.n) then
                nodes.qual_mass_in.a[nd_idx] = nodes.qual_mass_in.a[nd_idx] + (q * c_gw)
              end
            end
            ::cont2::
            p = p + 1
          end
        end
        do
          local p_2 = 0
          while p_2 < np do
            do
              local c_gw_2 = ctx.pollutants.c_gw.a[p_2]
              if c_gw_2 <= 0.0 then
                goto cont3
              end
              local pi = p_2
              if L_ult(pi, ctx.mass_balance.qual_routing_gw_in.n) then
                ctx.mass_balance.qual_routing_gw_in.a[pi] = ctx.mass_balance.qual_routing_gw_in.a[pi] + ((q * c_gw_2) * dt)
              end
            end
            ::cont3::
            p_2 = p_2 + 1
          end
        end
      end
      ::cont1::
      i = i + 1
    end
  end
end
function O_Tquality_QualitySolver.addIfaceLoads(self, ctx, dt)
  local np = self.n_pollutants_
  if not (((((np > 0) or (((ctx.options.quality_solver == 1) and (not ctx.options.ignore_quality)) and (not (ctx.ard_config.bc_node.n == 0)))) or ctx.options.water_age) or ctx.options.heat_transport) or (ctx.reactions.configured and ctx.reactions.compiled)) then
    do return end
  end
  local nodes = ctx.nodes
  if nodes.iface_qual_mass.n == 0 then
    do return end
  end
  do
    local i = 0
    while i < (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local ui = i
        local q = nodes.iface_inflow.a[ui]
        if (q < 0.0) and L_ult(ui, self.qual_vol_lat_neg_.n) then
          self.qual_vol_lat_neg_.a[ui] = self.qual_vol_lat_neg_.a[ui] + (q * dt)
        end
        if q <= 0.0 then
          goto cont1
        end
        nodes.qual_vol_in.a[ui] = nodes.qual_vol_in.a[ui] + (q * dt)
        self.qual_vol_lat_.a[ui] = self.qual_vol_lat_.a[ui] + (q * dt)
        F_quality__anon_quality_QualityRouting_cpp_addAgeVolume_QualityRouting(ctx, i, q, 5)
        F_quality__anon_quality_QualityRouting_cpp_addTempVolume_QualityRouting(ctx, i, q, 5)
        do
          local p = 0
          while p < np do
            do
              local nd_idx = (ui * np) + p
              local mass_rate = L_ult(nd_idx, nodes.iface_qual_mass.n) and nodes.iface_qual_mass.a[nd_idx] or 0.0
              if mass_rate <= 0.0 then
                goto cont2
              end
              if L_ult(nd_idx, nodes.qual_mass_in.n) then
                nodes.qual_mass_in.a[nd_idx] = nodes.qual_mass_in.a[nd_idx] + mass_rate
              end
            end
            ::cont2::
            p = p + 1
          end
        end
        do
          local p_2 = 0
          while p_2 < np do
            do
              local nd_idx_2 = (ui * np) + p_2
              local mass_rate_2 = L_ult(nd_idx_2, nodes.iface_qual_mass.n) and nodes.iface_qual_mass.a[nd_idx_2] or 0.0
              if mass_rate_2 <= 0.0 then
                goto cont3
              end
              local pi = p_2
              if L_ult(pi, ctx.mass_balance.qual_routing_ex_in.n) then
                ctx.mass_balance.qual_routing_ex_in.a[pi] = ctx.mass_balance.qual_routing_ex_in.a[pi] + (mass_rate_2 * dt)
              end
            end
            ::cont3::
            p_2 = p_2 + 1
          end
        end
      end
      ::cont1::
      i = i + 1
    end
  end
end
function O_Tquality_QualitySolver.accumulateLinkLoads(self, ctx, dt)
  local t_1, t_2
  local np = self.n_pollutants_
  local links = ctx.links
  do
    local j = 0
    while j < (((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local uj = j
        local q = L_abs(links.flow.a[uj])
        if q <= 0.0 then
          goto cont1
        end
        if links.flow.a[uj] >= 0.0 then
          t_1, t_2 = links.node2.a, uj
        else
          t_1, t_2 = links.node1.a, uj
        end
        local downstream = t_1[t_2]
        if (downstream < 0) or (downstream >= (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) then
          goto cont1
        end
        local ud = downstream
        ctx.nodes.qual_vol_in.a[ud] = ctx.nodes.qual_vol_in.a[ud] + (q * dt)
        do
          local p = 0
          while p < np do
            do
              local lp = (uj * np) + p
              local np_idx = (ud * np) + p
              local c_link = L_ult(lp, links.conc_old.n) and links.conc_old.a[lp] or 0.0
              if F_quality_linkTakesUpstreamValue(ctx, j) then
                if links.flow.a[uj] >= 0.0 then
                  t_1, t_2 = links.node1.a, uj
                else
                  t_1, t_2 = links.node2.a, uj
                end
                local source = t_1[t_2]
                if F_lidnode_active(ctx, source) or F_lidnode_active(ctx, downstream) then
                  c_link = ctx.nodes.conc.a[((((source * np) + p) + 0x80000000) & 0xFFFFFFFF) - 0x80000000]
                  if ctx.nodes.type.a[source] == 1 then
                    c_link = ctx.options.outfall_backflow_zero and 0.0 or ctx.nodes.conc_old.a[((((source * np) + p) + 0x80000000) & 0xFFFFFFFF) - 0x80000000]
                  end
                end
                c_link = F_lidnode_outletQuality(ctx, source, j, p, c_link)
              end
              local mass = q * c_link
              if F_quality_linkTakesUpstreamValue(ctx, j) and F_lidnode_active(ctx, downstream) then
                if links.flow.a[uj] >= 0.0 then
                  t_1, t_2 = links.node1.a, uj
                else
                  t_1, t_2 = links.node2.a, uj
                end
                local source_2 = t_1[t_2]
                if ctx.nodes.type.a[source_2] == 1 then
                  ctx.mass_balance.qual_routing_ex_in.a[p] = ctx.mass_balance.qual_routing_ex_in.a[p] + (mass * dt)
                end
              end
              if L_ult(np_idx, ctx.nodes.qual_mass_in.n) then
                ctx.nodes.qual_mass_in.a[np_idx] = ctx.nodes.qual_mass_in.a[np_idx] + mass
                F_lidnode_receiveQuality(ctx, downstream, j, q * dt, p, mass, dt)
              end
            end
            p = p + 1
          end
        end
        local r = O_NodeSubtypes.storage_row(ctx.node_subtypes, downstream)
        if r >= 0 then
          do
            local v___r1 = ctx.node_subtypes.storages.lid_state.a[r].quality_ports
            do
              local v___i2_n = v___r1.n
              for v___i2 = 0, v___i2_n - 1 do
                local port = v___r1.a[v___i2]
                if (port.link == j) and (port.volume > 0.0) then
                  ctx.nodes.qual_vol_in.a[ud] = ctx.nodes.qual_vol_in.a[ud] - port.volume
                end
              end
            end
          end
        end
      end
      ::cont1::
      j = j + 1
    end
  end
end
function O_Tquality_QualitySolver.mixAtNodes(self, ctx, dt)
  local t_1
  local np = self.n_pollutants_
  local nodes = ctx.nodes
  local poll = ctx.pollutants
  local mb = ctx.mass_balance
  local zero_bf_opt = ctx.options.outfall_backflow_zero
  local reactions_active = ctx.reactions.configured and ctx.reactions.compiled
  local any_treatment = O_TreatmentData.hasAny(ctx.treatment)
  do
    local i = 0
    while i < (((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000) do
      do
        local ui = i
        local v_old = nodes.old_volume.a[ui]
        local v_in = nodes.qual_vol_in.a[ui]
        local is_storage = nodes.type.a[ui] == 3
        local zero_bf = zero_bf_opt and (nodes.type.a[ui] == 1)
        if not F_quality_nodeIsReactor(ctx, i) then
          local q_node = (dt > 0.0) and (v_in / dt) or 0.0
          do
            local p = 0
            while p < np do
              do
                local idx = (ui * np) + p
                if not L_ult(idx, nodes.conc.n) then
                  goto cont2
                end
                if q_node > S_F_quality_LEGACY_ZERO then
                  local mass_in = L_ult(idx, nodes.qual_mass_in.n) and (nodes.qual_mass_in.a[idx] * dt) or 0.0
                  if mass_in < 0.0 then
                    local avail = nodes.conc_old.a[idx] * v_old
                    if mass_in < (-avail) then
                      F_quality_bookNegativeSourceClamp(ctx, i, p, -(avail + mass_in))
                      mass_in = -avail
                    end
                  end
                  nodes.conc.a[idx] = mass_in / v_in
                elseif zero_bf then
                  nodes.conc.a[idx] = 0.0
                elseif nodes.depth.a[ui] > S_F_quality_ZERO_DEPTH then
                  nodes.conc.a[idx] = nodes.conc_old.a[idx]
                else
                  nodes.conc.a[idx] = L_ult(idx, nodes.qual_mass_in.n) and nodes.qual_mass_in.a[idx] or 0.0
                end
              end
              ::cont2::
              p = p + 1
            end
          end
          goto cont1
        end
        local f_evap = F_quality_storageEvapFactor(ctx, i)
        local q_exfil = 0.0
        if is_storage then
          local srow = O_NodeSubtypes.storage_row(ctx.node_subtypes, i)
          if srow >= 0 then
            local us = srow
            local st = ctx.node_subtypes.storages
            local v_exfil = L_ult(us, st.exfil_loss.n) and st.exfil_loss.a[us] or 0.0
            q_exfil = (dt > 0.0) and (v_exfil / dt) or 0.0
          end
        end
        local q_in = (dt > 0.0) and (v_in / dt) or 0.0
        local dry = F_quality_nodeIsDry(ctx, i, q_in) and (not F_lidnode_active(ctx, i))
        do
          local p_2 = 0
          while p_2 < np do
            do
              local idx_2 = (ui * np) + p_2
              if not L_ult(idx_2, nodes.conc.n) then
                goto cont3
              end
              local up = p_2
              local c1 = nodes.conc_old.a[idx_2]
              local seeped = (q_exfil * c1) * dt
              c1 = c1 * f_evap
              local k = L_ult(up, poll.k_decay.n) and poll.k_decay.a[up] or 0.0
              if reactions_active then
                k = 0.0
              end
              if ((k ~= 0.0) and any_treatment) and F_quality__anon_quality_QualityRouting_cpp_nodeHasTreatmentFor_QualityRouting(ctx, i, p_2) then
                k = 0.0
              end
              local reacted = 0.0
              if k ~= 0.0 then
                t_1 = c1 * (1.0 - (k * dt))
                local c2 = (0.0 < t_1) and t_1 or 0.0
                reacted = (c1 - c2) * v_old
                c1 = c2
              end
              local mass_in_2 = L_ult(idx_2, nodes.qual_mass_in.n) and (nodes.qual_mass_in.a[idx_2] * dt) or 0.0
              if mass_in_2 < 0.0 then
                local avail_2 = nodes.conc_old.a[idx_2] * v_old
                if mass_in_2 < (-avail_2) then
                  F_quality_bookNegativeSourceClamp(ctx, i, p_2, -(avail_2 + mass_in_2))
                  mass_in_2 = -avail_2
                end
              end
              local c_new = 0.0
              if q_in <= S_F_quality_LEGACY_ZERO then
                c_new = c1
              else
                local c_in = mass_in_2 / v_in
                local c_max = (c1 < c_in) and c_in or c1
                c_new = ((c1 * v_old) + mass_in_2) / (v_old + v_in)
                c_new = (c_max < c_new) and c_max or c_new
                c_new = (c_new < 0.0) and 0.0 or c_new
              end
              if dry then
                if L_ult(up, mb.qual_routing_final_dry.n) then
                  mb.qual_routing_final_dry.a[up] = mb.qual_routing_final_dry.a[up] + (c_new * nodes.volume.a[ui])
                end
                c_new = 0.0
              end
              c_new = (c_new < 0.0) and 0.0 or c_new
              nodes.conc.a[idx_2] = c_new
              if (reacted > 0.0) and L_ult(up, mb.qual_routing_reacted.n) then
                mb.qual_routing_reacted.a[up] = mb.qual_routing_reacted.a[up] + reacted
              end
              if (seeped ~= 0.0) and L_ult(up, mb.qual_routing_seep.n) then
                mb.qual_routing_seep.a[up] = mb.qual_routing_seep.a[up] + seeped
              end
            end
            ::cont3::
            p_2 = p_2 + 1
          end
        end
      end
      ::cont1::
      i = i + 1
    end
  end
end
