    do return NewStr_CPtr(R_Lit("LARD channel species state is unavailable.")) end
  end
  do
    local v___r1 = updates
    do
      local v___i2_n = v___r1.n
      for v___i2 = 0, v___i2_n - 1 do
        local u = v___r1.a[v___i2]
        do
          if (((u.link < 0) or (u.link >= (((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000))) or (u.region ~= 0)) or (u.concentration_delta.n ~= layout.ns) then
            do return NewStr_CPtr(R_Lit("LARD species increment has an invalid channel region or row count.")) end
          end
          if u.concentration_delta.a[layout.temp_row] ~= 0.0 then
            do return NewStr_CPtr(R_Lit("LARD species update cannot modify the temperature row.")) end
          end
          local mean = NewVecD_ul(layout.ns)
          O_Tlard_SegmentStore.mean_conc(self.store_, u.link, mean:data())
          do
            local k = 0
            while k < self.store_.count_.a[u.link] do
              do
                do
                  local row = 0
                  while row < layout.ns do
                    do
                      local delta = u.concentration_delta.a[row]
                      local target = mean.a[row] + delta
                      local v_next = (mean.a[row] > 0.0) and ((self.store_.conc_.a[((row * self.store_.nl_) * self.store_.cap_) + O_Tlard_SegmentStore.phys(self.store_, u.link, k)] * target) / mean.a[row]) or target
                      if ((not is_finite(delta)) or (not is_finite(v_next))) or ((row ~= layout.temp_row) and (v_next < 0.0)) then
                        do return NewStr_CPtr(R_Lit("LARD species increment is nonfinite or makes a carried mass negative.")) end
                      end
                    end
                    row = row + 1
                  end
                end
              end
              k = k + 1
            end
          end
        end
      end
    end
  end
  do
    local v___r3 = updates
    do
      local v___i4_n = v___r3.n
      for v___i4 = 0, v___i4_n - 1 do
        local u_2 = v___r3.a[v___i4]
        do
          local mean_2 = NewVecD_ul(layout.ns)
          O_Tlard_SegmentStore.mean_conc(self.store_, u_2.link, mean_2:data())
          do
            local k_2 = 0
            while k_2 < self.store_.count_.a[u_2.link] do
              do
                do
                  local row_2 = 0
                  while row_2 < layout.ns do
                    do
                      if row_2 ~= layout.temp_row then
                        local target_2 = mean_2.a[row_2] + u_2.concentration_delta.a[row_2]
                        local next_2 = (mean_2.a[row_2] > 0.0) and ((self.store_.conc_.a[((row_2 * self.store_.nl_) * self.store_.cap_) + O_Tlard_SegmentStore.phys(self.store_, u_2.link, k_2)] * target_2) / mean_2.a[row_2]) or target_2
                        O_Tlard_SegmentStore.set_seg_conc(self.store_, u_2.link, k_2, row_2, next_2)
                      end
                    end
                    row_2 = row_2 + 1
