function O_Tlard_LagrangianSolver.step__rSimulationContext_d(self, ctx, dt_routing)
  local v_L = F_lard_rowLayout(ctx)
  local np = v_L.np
  local ns = v_L.ns
  if ns <= 0 then
    do return end
  end
  if not self.initialized_ then
    O_Tlard_LagrangianSolver.init(self, ctx)
  end
  local nl = ((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  local links = ctx.links
  local topo_dirty = false
  do
    local l = 0
    while l < nl do
      do
        local ul = l
        local q = links.flow.a[ul]
        if L_abs(q) <= S_F_lard_kTinyFlow then
          goto cont1
        end
        local sign = ((((q >= 0.0) and 1 or (-1)) + 0x80) & 0xFF) - 0x80
        if sign ~= self.flow_sign_.a[ul] then
          if links.type.a[ul] == 0 then
            O_Tlard_SegmentStore.reverse(self.store_, l)
          end
          self.flow_sign_.a[ul] = sign
          topo_dirty = true
        end
      end
      ::cont1::
      l = l + 1
    end
  end
  if topo_dirty or (self.topo_.n == 0) then
    O_Tlard_LagrangianSolver.computeTopoOrder(self, ctx)
  end
  local dtq = ctx.options.quality_step
  local nsub = ((dtq > 0.0) and (dtq < dt_routing)) and L_f2i32(L_ceil(dt_routing / dtq)) or 1
  local dt = dt_routing / nsub
  local frac = 1.0 / nsub
  do
    local sub = 0
    while sub < nsub do
      do
        O_Tlard_LagrangianSolver.substep(self, ctx, dt, frac)
      end
      sub = sub + 1
    end
  end
  O_Tlard_LagrangianSolver.applyFluxesAndBed(self, ctx, dt_routing)
  O_Tlard_LagrangianSolver.publish(self, ctx, dt_routing)
end
function O_Tlard_LagrangianSolver.substep(self, ctx, dt, frac)
