        local j_from = O_Tlard_RwptDispersion.locate(self, z, nseg)
        local dz = (F_lard_rwpt_u_dev(e, ubar, ustar, turbulent) / ubar) * q_dt
        local d_eta = F_lard_rwpt_d_eta(e, h, ustar, turbulent)
        local drift = F_lard_rwpt_d_eta_grad(e, h, ustar, turbulent)
        t_3 = drift * dt
        t_2 = F_lard_rwpt_normal(seed, l, stepc, p, 3)
        t_1 = (2.0 * d_eta) * dt
        e = e + (t_3 + (t_2 * L_sqrt((t_1 < 0.0) and 0.0 or t_1)))
        while (e < 0.0) or (e > 1.0) do
          if e < 0.0 then
            e = -e
          end
          if e > 1.0 then
            e = 2.0 - e
          end
        end
        z = z + dz
        while (z < 0.0) or (z > vol) do
          if z < 0.0 then
            z = -z
          end
          if z > vol then
            z = (2.0 * vol) - z
          end
        end
        local j_to = O_Tlard_RwptDispersion.locate(self, z, nseg)
        if j_to ~= j_from then
          local vshare = vol / self.npart_
          local j_2 = j_from
          local stepdir = (j_to > j_from) and 1 or (-1)
          while j_2 ~= j_to do
            local jn = (((j_2 + stepdir) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
