                end
                s = s + 1
              end
            end
            O_Tlard_RwptDispersion.exchange(self, segs, l, j_2, jn, delta:data(), ns)
            j_2 = jn
          end
        end
        self.zeta_.a[ip] = z
        self.eta_.a[ip] = e
