  end
  do return j end
end
function O_Tlard_RwptDispersion.exchange(self, segs, l, j, jn, delta, ns)
  local t_1, t_2, t_3
  do
    local s = 0
    while s < ns do
      do
        local vj = segs.vol_.a[O_Tlard_SegmentStore.phys(segs, l, j)]
        local vn = segs.vol_.a[O_Tlard_SegmentStore.phys(segs, l, jn)]
        if (vj <= 0.0) or (vn <= 0.0) then
          goto cont1
        end
        local cj = segs.conc_.a[((s * segs.nl_) * segs.cap_) + O_Tlard_SegmentStore.phys(segs, l, j)]
        local cn = segs.conc_.a[((s * segs.nl_) * segs.cap_) + O_Tlard_SegmentStore.phys(segs, l, jn)]
        t_2 = delta.a[delta.o + s]
        t_3 = cj * vj
        t_1 = cj - cn
        local take = M_min_dA({[0] = t_2, t_3, ((0.0 < t_1) and t_1 or 0.0) * vn, n = 3})
        if take <= 0.0 then
