        if not (h > 0.0) then
          goto cont1
        end
        local rh = F_fv_kernels_closureHydRad(g.closure_tbl, h)
        if not (rh > 0.0) then
          goto cont1
        end
        local bed_m2 = ((area_x / rh) * self.mesh_.cell_dx.a[c]) * kSqFtToSqM
        local sd_c = F_transport_heat_sedimentFor(ctx, HeatElement_link(O_Ttransport_ArdEngine.cellLink(self, c)))
        local vol_w = vol_ft3 * kCuFtToCuM
        local vol_b = bed_m2 * sd_c.bed_thickness
        local q_exch = F_transport_heat_bedExchangeQ(sd_c, bed_m2)
        if (not (q_exch > 0.0)) or (not (vol_b > 0.0)) then
          goto cont1
        end
        do
          local sp = 0
          while L_ult(sp, une) do
            do
              local cw, cw_k = self.state_.cell_phi.a, (sp * unc) + c
              local cb, cb_k = bed.cell_conc.a, (sp * unc) + c
              local st = F_transport_heat_exchangePair(cw[cw_k], cb[cb_k], vol_w, vol_b, q_exch, dt)
              cw[cw_k] = cw[cw_k] + st.dc_w
              cb[cb_k] = cb[cb_k] + st.dc_b
            end
            sp = sp + 1
          end
        end
      end
      ::cont1::
      c = c + 1
    end
  end
end
function O_Ttransport_ArdEngine.cellLink(self, v_cell)
  if not L_ult(v_cell, self.mesh_.cell_conduit.n) then
    do return -1 end
  end
  local cr = self.mesh_.cell_conduit.a[v_cell]
  if (cr < 0) or (not L_ult(cr, self.mesh_.conduit_link.n)) then
    do return -1 end
  end
  do return self.mesh_.conduit_link.a[cr] end
end
