function HotStartManager_save(ctx, path)
  local t_1, t_2, t_3, t_4
  S_F_tl_last_io_error_HotStartManager:clear()
  if ((ctx.state_accessors.has_fv_retained_dry_mass ~= nil) and ctx.state_accessors.has_fv_retained_dry_mass()) and (not (ctx.state_accessors.get_fv_dry_state ~= nil)) then
    S_F_tl_last_io_error_HotStartManager:Assign_CPtr(R_Lit("Hotstart cannot preserve retained FV dry scalar inventory; save after it remobilizes."))
    do return nil end
  end
  if not (ctx.reactions.lid_controls.n == 0) then
    S_F_tl_last_io_error_HotStartManager:Assign_CPtr(R_Lit("LID reaction inventories require a full native engine checkpoint"))
    do return nil end
  end
  if false then
    S_F_tl_last_io_error_HotStartManager:Assign_CPtr(R_Lit("Independent groundwater hotstart needs the complete routing and surface clocks. Start a checkpoint session or configure a native SAVE HOTSTART before starting the run."))
    do return nil end
  end
  if false then
    S_F_tl_last_io_error_HotStartManager:Assign_CPtr(R_Lit("Coupled mesh/ground heat hotstart requires its thermal energy restart extension"))
    do return nil end
  end
  if F__anon_core_HotStartManager_cpp_meshLidRestartUnsupported_HotStartManager(ctx) then
    S_F_tl_last_io_error_HotStartManager:Assign_CPtr(R_Lit("Mesh LID hotstart requires the R5 joint owner restart extension"))
    do return nil end
  end
  if ctx.runtime_coupling_used then
    S_F_tl_last_io_error_HotStartManager:Assign_CPtr(R_Lit("Hotstart cannot preserve runtime 2D coupling prescriptions and receipts"))
    do return nil end
  end
  local use_v2 = (ctx.state_accessors.get_infil_state ~= nil) or (ctx.state_accessors.get_gw_state ~= nil)
  local hs = HotStartFile__new()
  hs.path:Assign_Str(path)
  hs.header.version_f = ctx.options.water_age and 3 or (use_v2 and 2 or 1)
  if F__anon_core_HotStartManager_cpp_captureSpeciesBlock_HotStartManager(ctx, hs) then
    hs.header.version_f = 4
  end
  if false then
    hs.header.version_f = 5
    if false then
      hs.header.version_f = 6
      do
        local i = 0
        while L_ult(i, hs.gw_species.n) do
          do
            if (hs.gw_species_ledger.a[(i * S_HotStartFile_kGwSpeciesLedgerTerms) + 11] ~= 0.0) or (hs.gw_species_ledger.a[(i * S_HotStartFile_kGwSpeciesLedgerTerms) + 12] ~= 0.0) then
              hs.header.version_f = 7
            end
          end
          i = i + 1
        end
      end
    end
  end
  hs.header.timestamp = R_time_Ptrl(PtrL_ZERO)
  hs.header.sim_time = ctx.current_time
  hs.header.start_date = ctx.options.start_date
  hs.header.end_date = ctx.options.end_date
  hs.header.crs:Assign_Str(ctx.spatial.crs)
  local n_nodes = ((ctx.node_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  hs.nodes:resize_ul(n_nodes)
  do
    local i_2 = 0
    while i_2 < n_nodes do
      do
        local ui = i_2
        hs.nodes.a[ui].id_f:Assign_Str(ctx.node_names.names_:at(i_2))
        hs.nodes.a[ui].depth = ctx.nodes.depth.a[ui]
        hs.nodes.a[ui].head = ctx.nodes.head.a[ui]
        hs.nodes.a[ui].volume = ctx.nodes.volume.a[ui]
        if F_lidnode_active(ctx, i_2) then
          hs.header.version_f = (hs.header.version_f < 10) and 10 or hs.header.version_f
          local state = ctx.node_subtypes.storages.lid_state.a[O_NodeSubtypes.storage_row(ctx.node_subtypes, i_2)]
          hs.nodes.a[ui].lid_treated_volume = state.treated_volume
          hs.nodes.a[ui].lid_quality_mass:Assign_VecT(state.quality_mass)
          if state.richards then
            hs.header.version_f = 11
            local stack = F_lidnode_layers(ctx, ctx.node_subtypes.storages.lid.a[O_NodeSubtypes.storage_row(ctx.node_subtypes, i_2)].control)
            do
              local k = 0
              while L_ult(k, state.cells.n) do
                do
                  local v_cell = state.cells.a[k]
                  local p = stack.a[(((v_cell.layer - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000].retention
                  local values = hs.nodes.a[ui].lid_richards
                  values:insert_IterT_TA(values:end_():Clone(), {[0] = state.richards_water.a[k], p.theta_r, p.alpha, p.n, p.l, p.specific_storage, v_cell.conductivity, v_cell.wilting_point, n = 8})
                end
                k = k + 1
              end
            end
          end
          if state.infiltration_cell >= 0 then
            local ga = state.surface_infil
            t_1 = {n = 11}
            t_1[0] = ga.S
            t_1[1] = ga.Ks
            t_1[2] = ga.IMDmax
            t_1[3] = ga.IMD
            t_1[4] = ga.F
            t_1[5] = ga.Fu
            t_1[6] = ga.Fumax
            t_1[7] = ga.Lu
            t_1[8] = ga.T
            t_1[9] = state.infiltration_head
            t_1[10] = ga.saturated and 1.0 or 0.0
            hs.nodes.a[ui].lid_infiltration:MoveFrom_TA(t_1)
          end
          do
            local v___r1 = state.cells
            do
              local v___i2_n = v___r1.n
              for v___i2 = 0, v___i2_n - 1 do
                local c = v___r1.a[v___i2]
                t_1 = HotStartLidCellRecord__new()
                t_1.layer = c.layer
                t_1.bottom = c.bottom
                t_1.top = c.top
                t_1.porosity = c.porosity
                t_1.volume = c.geometric_volume
                t_1.theta = c.theta
                hs.nodes.a[ui].lid_cells:push_back(t_1)
              end
            end
          end
        end
        if ctx.options.water_age and L_ult(ui, ctx.water_age_state.node_age.n) then
          hs.nodes.a[ui].age = ctx.water_age_state.node_age.a[ui]
        end
      end
      i_2 = i_2 + 1
    end
  end
  local n_links = ((ctx.link_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  hs.links:resize_ul(n_links)
  do
    local i_3 = 0
    while i_3 < n_links do
      do
        local ui_2 = i_3
        hs.links.a[ui_2].id_f:Assign_Str(ctx.link_names.names_:at(i_3))
        hs.links.a[ui_2].flow = ctx.links.flow.a[ui_2]
        hs.links.a[ui_2].depth = ctx.links.depth.a[ui_2]
        hs.links.a[ui_2].volume = ctx.links.volume.a[ui_2]
        if ctx.options.water_age and L_ult(ui_2, ctx.water_age_state.link_age.n) then
          hs.links.a[ui_2].age = ctx.water_age_state.link_age.a[ui_2]
        end
      end
      i_3 = i_3 + 1
    end
  end
  local n_sub = ((ctx.subcatch_names.names_.n + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  hs.subcatches:resize_ul(n_sub)
  do
    local i_4 = 0
    while i_4 < n_sub do
      do
        local ui_3 = i_4
        local rec = hs.subcatches.a[ui_3]
        rec.id_f:Assign_Str(ctx.subcatch_names.names_:at(i_4))
        rec.runoff = ctx.subcatches.runoff.a[ui_3]
        rec.gwater = ctx.subcatches.gw_flow.a[ui_3]
        if use_v2 then
          if ctx.state_accessors.get_infil_state ~= nil then
            ctx.state_accessors.get_infil_state(i_4, rec, "infil_model", NewPtrD_TA_l(rec.infil, 0))
          else
            rec.infil_model = 0
          end
          if ctx.state_accessors.get_gw_state ~= nil then
            ctx.state_accessors.get_gw_state(i_4, rec, "gw_theta", rec, "gw_lower_depth")
          end
        end
      end
      i_4 = i_4 + 1
    end
  end
  if not (hs.gw_interface.n == 0) then
    hs.header.version_f = (hs.header.version_f < 13) and 13 or hs.header.version_f
  end
  t_1, t_2, t_3 = L_pcall(function()
    if ctx.state_accessors.get_fv_dry_state ~= nil then
      hs.fv_dry_state:MoveFrom(ctx.state_accessors.get_fv_dry_state())
    end
    if ctx.state_accessors.get_snow_state ~= nil then
      hs.snow_state:MoveFrom(ctx.state_accessors.get_snow_state())
    end
    if not (hs.snow_state.n == 0) then
      hs.header.version_f = 14
    end
    if ctx.state_accessors.get_surface_state ~= nil then
      hs.surface_state:MoveFrom(ctx.state_accessors.get_surface_state())
    end
    if not (hs.surface_state.n == 0) then
      hs.header.version_f = 16
    end
    if not (hs.fv_dry_state.n == 0) then
      hs.header.version_f = 18
    end
  end)
  if not t_1 then
    t_4 = L_excof(t_2)
    if L_isa(t_4, Cpp_CppException) then
      local e = t_4
      Dbg_Caught(e)
      S_F_tl_last_io_error_HotStartManager:Assign_CPtr(e:what())
      Mv_Delete(hs)
      do return nil end
    else
      L_error(t_4, 0)
    end
  end
  if t_1 and t_2 == 1 then do return t_3 end end
  if not HotStartManager_write_file(hs, path) then
    Mv_Delete(hs)
    do return nil end
  end
  do return hs end
end
function HotStartManager_save_with_engine_checkpoint(ctx, runoff_solver, gw_solver, path, engine_checkpoint)
