function SimulationContext_updateMaxStats(arr, obj_type, idx, value)
  local candidate = SimulationContext_MaxStats__new()
  candidate.obj_type = obj_type
  candidate.index = idx
  candidate.value_f = value
  do
    local k = 0
    while k < S_SimulationContext_MAX_STATS do
      do
        if L_abs(candidate.value_f) > L_abs(arr.a[arr.o + k].value_f) then
          local tmp = SimulationContext_MaxStats_New_rMaxStats(arr.a[arr.o + k])
          arr.a[arr.o + k]:Assign(candidate)
          candidate:Assign(tmp)
        end
      end
      k = k + 1
    end
  end
end
