function Tucf_DisplayUnits_from(opts)
  local d = Tucf_DisplayUnits__new()
  local fu = opts.flow_units
  if (fu < 0) or (fu > 5) then
    fu = 0
  end
  local us = F_ucf_getUnitSystem(fu)
  local si = us == 1
  d.unit_system = us
  d.flow_units = fu
  d.flow = S_F_ucf_Qcf_UnitConversion[fu]
  d.length = S_F_ucf_Ucf_UnitConversion[3][us]
  d.volume = S_F_ucf_Ucf_UnitConversion[5][us]
  d.rainfall = S_F_ucf_Ucf_UnitConversion[0][us]
  d.raindepth = S_F_ucf_Ucf_UnitConversion[1][us]
  d.evaprate = S_F_ucf_Ucf_UnitConversion[2][us]
  d.landarea = S_F_ucf_Ucf_UnitConversion[4][us]
  d.mvol = si and (2.83168E-05) or S_F_ucf_FT3_TO_MGAL_UnitConversion
  d.landvol = si and (2.83168E-06) or (1.0 / S_F_ucf_ACRES_TO_FT2_UnitConversion)
  d.flow_word = S_F_ucf_FlowUnitWords[fu]
  d.length_word = si and R_Lit("Meters") or R_Lit("Feet")
  d.depth_word = si and R_Lit("mm") or R_Lit("in")
  d.vel_word = si and R_Lit("m/sec") or R_Lit("ft/sec")
  d.mvol_word = si and R_Lit("10^6 ltr") or R_Lit("10^6 gal")
  d.landvol_word = si and R_Lit("hectare-m") or R_Lit("acre-feet")
  d.storage_vol_word = si and R_Lit("1000 m3") or R_Lit("1000 ft3")
  do return Tucf_DisplayUnits_MoveNew(d) end
end
