function UserFlags_make_key(object_type, object_name, flag_name)
  local key = {NewStr()}
  key[1]:reserve((((object_type.n + 1) + object_name.n) + 1) + flag_name.n)
  key[1]:append_Str(object_type)
  key[1]:append_i(58)
  key[1]:append_Str(object_name)
  key[1]:append_i(58)
  key[1]:append_Str(flag_name)
  do return Mv_Take(key, 1, NewStr) end
end
