function LinkData_lstep_bin(dt, rs)
  local b = 0
  local edge = 0.5 * rs
  while (b < ((((S_LinkData_N_LSTEP_BINS - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)) and (dt <= edge) do
    b = (((b + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
    edge = edge * 0.5
  end
  do return b end
end
