function Thydraulics_TimestepController_compute_next(ctx, dt_cfl)
  local opt = ctx.options
  local min_step = opt.min_routing_step
  local dt = (dt_cfl < opt.routing_step) and dt_cfl or opt.routing_step
  local total_msec = O_SimulationOptions.totalDurationMs(opt)
  if (ctx.elapsed_ms + (1000.0 * dt)) > total_msec then
    dt = (total_msec - ctx.elapsed_ms) / 1000.0
    dt = (dt < 0.001) and 0.001 or dt
  end
  if (ctx.dt_controls_remaining > 0.0) and (ctx.dt_controls_remaining < dt) then
    dt = ctx.dt_controls_remaining
  end
  if dt <= 0.0 then
    dt = min_step
  end
  do return dt end
end
function Thydraulics_TimestepController_advance(ctx, dt_taken)
  ctx.current_time = ctx.current_time + dt_taken
  ctx.current_date = F_datetime_addSeconds(ctx.options.start_date, ctx.current_time)
  ctx.old_elapsed_ms = ctx.elapsed_ms
  ctx.elapsed_ms = ctx.elapsed_ms + (1000.0 * dt_taken)
  if ctx.dt_controls_remaining > 0.0 then
    ctx.dt_controls_remaining = ctx.dt_controls_remaining - dt_taken
    if ctx.dt_controls_remaining < 0.0 then
      ctx.dt_controls_remaining = 0.0
    end
  end
end
function Thydraulics_TimestepController_reset_output_timer(ctx)
  ctx.next_report_ms = ctx.next_report_ms + (1000.0 * ctx.options.report_step)
end
function Thydraulics_TimestepController_output_due(ctx)
  do return ctx.elapsed_ms >= ctx.next_report_ms end
end
function Thydraulics_TimestepController_simulation_complete(ctx)
  do return ctx.elapsed_ms >= O_SimulationOptions.totalDurationMs(ctx.options) end
end
