function Tfv_PressurizedHeadSolver_cellPressurized(mesh, state, v_cell)
  local uc = v_cell
  if not (state.cell_tpa.n == 0) then
    do return state.cell_tpa.a[uc] ~= 0 end
  end
  local g = mesh.geom.a[mesh.cell_geom.a[uc]]
  do return (not (g.is_open_f ~= 0)) and (state.cell_h.a[uc] >= g.y_crown) end
end
function Tfv_PressurizedHeadSolver_faceModeOf(mesh, state, f)
  local uf = f
  if mesh.face_gate.a[uf] ~= 0 then
    do return 0 end
  end
  if mesh.face_culvert.a[uf] >= 0 then
    do return 0 end
  end
  local cl = mesh.face_cl.a[uf]
  local cr = mesh.face_cr.a[uf]
  local nd = mesh.face_node.a[uf]
  if (nd < 0) and ((cl < 0) or (cr < 0)) then
    do return 0 end
  end
  local pl = false
  local pr = false
  local cell_side_press = false
  if cl >= 0 then
    pl = Tfv_PressurizedHeadSolver_cellPressurized(mesh, state, cl)
    cell_side_press = cell_side_press or pl
  end
  if cr >= 0 then
    pr = Tfv_PressurizedHeadSolver_cellPressurized(mesh, state, cr)
    cell_side_press = cell_side_press or pr
  end
  if nd >= 0 then
    local gp = Tfv_PressurizedHeadSolver_ghostPressurized(mesh, state, f)
    if cl < 0 then
      pl = gp
    end
    if cr < 0 then
      pr = gp
    end
  end
  if not cell_side_press then
    do return 0 end
  end
  do return ((pl and pr) and 1 or 2) & 0xFF end
end
function Tfv_PressurizedHeadSolver_ghostPressurized(mesh, state, f)
  local t_1, t_2
  local uf = f
  local nd = mesh.face_node.a[uf]
  if nd < 0 then
    do return false end
  end
  if mesh.face_cl.a[uf] >= 0 then
    t_1, t_2 = mesh.face_cl.a, uf
  else
    t_1, t_2 = mesh.face_cr.a, uf
  end
  local other = t_1[t_2]
  if other < 0 then
    do return false end
  end
  local g = mesh.geom.a[mesh.cell_geom.a[other]]
  if g.is_open_f ~= 0 then
    do return false end
  end
  if ((not (state.cell_tpa.n == 0)) and (state.cell_tpa.a[other] ~= 0)) and (mesh.node_sur_depth.a[nd] > 0.0) then
    do return true end
  end
  local hg = state.node_head.a[nd] - mesh.face_zb.a[uf]
  do return hg >= g.y_crown end
end
