function Trdii_RDIISolver_getRainInterval(uh, wet_step)
  local ri = L_f2i32(wet_step)
  if ri <= 0 then
    ri = 300
  end
  do
    local m = 0
    while m < 12 do
      do
        do
          local k = 0
          while k < 3 do
            do
              local tp = uh.tPeak[m][k]
              if tp > 0.0 then
                local tLimb = L_f2i32(tp)
                if tLimb > 0 then
                  ri = (tLimb < ri) and tLimb or ri
                end
                local tFall = L_f2i32(uh.tBase[m][k] - tp)
                if tFall > 0 then
                  ri = (tFall < ri) and tFall or ri
                end
              end
            end
            k = k + 1
          end
        end
      end
      m = m + 1
    end
  end
  do return (ri < 1) and 1 or ri end
end
function Trdii_RDIISolver_getMaxPeriods(uh, response, rainInterval)
  if rainInterval <= 0 then
    do return 0 end
  end
  local k = L_imod(response, 3)
  local nMax = 0
  do
    local m = 0
    while m < 12 do
      do
        local n = (((L_f2i32(uh.tBase[m][k] / rainInterval) + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
        nMax = (n < nMax) and nMax or n
      end
      m = m + 1
    end
  end
  do return nMax end
end
