function Trunoff_RunoffSolver_updatePondedDepth(depth, depth_k, inflow, alpha, dStore, dt, t_runoff, t_runoff_k)
  local t_1
  local tx = dt
  if (depth[depth_k] + (inflow * tx)) <= dStore then
    depth[depth_k] = depth[depth_k] + (inflow * tx)
  else
    local dx = dStore - depth[depth_k]
    if (dx > 0.0) and (inflow > 0.0) then
      tx = tx - (dx / inflow)
      depth[depth_k] = dStore
    end
    if (alpha > 0.0) and (tx > 0.0) then
      local captured_inflow = inflow
      local captured_alpha = alpha
      local captured_dStore = dStore
      local v___b1 = {[0] = depth[depth_k], n = 1}
      local v___cap2 = captured_inflow
      local v___cap3 = captured_alpha
      local v___cap4 = captured_dStore
      Mv_Back__ID(F_ode_integrate(NewPtrD_TA_l(v___b1, 0), 1, 0.0, tx, S_F_runoff_ODETOL, tx, function(p, d, dddt)
        local rx = d.a[d.o] - v___cap4
        local outflow = (rx > 0.0) and (v___cap3 * L_pow(rx, S_F_runoff_MEXP)) or 0.0
        dddt.a[dddt.o] = v___cap2 - outflow
        do return end
      end), depth, depth_k, v___b1)
    else
      tx = (tx < 0.0) and 0.0 or tx
      depth[depth_k] = depth[depth_k] + (inflow * tx)
    end
  end
  t_1 = depth[depth_k]
  depth[depth_k] = (t_1 < 0.0) and 0.0 or t_1
  t_runoff[t_runoff_k] = tx
end
