function Tsnow_DegreeDaySnow_rainMeltRate(temp, wind, gamma, ea, rainfall)
  rainfall = rainfall * 43200.0
  if rainfall > 0.02 then
    local uadj = 0.006 * wind
    local t1 = temp - 32.0
    local t2 = (7.5 * gamma) * uadj
    local t3 = (8.5 * uadj) * (ea - 0.18)
    local smelt = (t1 * ((0.001167 + t2) + (0.007 * rainfall))) + t3
    do return smelt / 43200.0 end
  end
  do return 0.0 end
end
