function Tinput_InputReader_parse_section_header(line)
  if L_ult(line.n, 3) or ((((line:front() + 0x80) & 0xFF) - 0x80) ~= 91) then
    do return NewStr() end
  end
  local close = line:find_i_ul(93, 0)
  if close == 0xFFFFFFFFFFFFFFFF then
    do return NewStr() end
  end
  local name = Tinput_Tokenizer_trim(line:substr(1, close - 1))
  if name.n == 0 then
    do return NewStr() end
  end
  do return Tinput_Tokenizer_to_upper(name:Clone()) end
end
