function Tinput_Tokenizer_strip_comment(line)
  local in_quote = false
  do
    local i = 0
    while L_ult(i, line.n) do
      do
        local c = ((line.b[i] + 0x80) & 0xFF) - 0x80
        if c == 34 then
          in_quote = not in_quote
        elseif (c == 59) and (not in_quote) then
          do return line:substr(0, i) end
        end
      end
      i = i + 1
    end
  end
  do return line:Clone() end
end
function Tinput_Tokenizer_tokenize(line)
  local t_1
  local stripped = Tinput_Tokenizer_strip_comment(line:Clone())
  local pure_csv = Tinput_Tokenizer_is_pure_csv_line(stripped:Clone())
  local tokens = {NewVec(NewStr)}
  tokens[1]:reserve(8)
  local i = 0
  local n = stripped.n
  while L_ult(i, n) do
    do
      while L_ult(i, n) and (((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 32) or ((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 9)) do
        i = i + 1
      end
      if not L_ult(i, n) then
        break
      end
      if ((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 44) and Tinput_Tokenizer_comma_separates(stripped:Clone(), i, pure_csv) then
        if (i == 0) or ((((stripped.b[i - 1] + 0x80) & 0xFF) - 0x80) == 44) then
          tokens[1]:emplace_back(NewStr())
        end
        i = i + 1
        goto cont1
      end
      if (((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 34 then
        i = i + 1
        local tok = {NewStr()}
        while L_ult(i, n) and ((((stripped.b[i] + 0x80) & 0xFF) - 0x80) ~= 34) do
          t_1 = i
          i = t_1 + 1
          tok[1]:append_i(((stripped.b[t_1] + 0x80) & 0xFF) - 0x80)
        end
        if L_ult(i, n) then
          i = i + 1
        end
        tokens[1]:push_back(Mv_Take(tok, 1, NewStr))
        while L_ult(i, n) and (((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 32) or ((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 9)) do
          i = i + 1
        end
        if L_ult(i, n) and ((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 44) then
          i = i + 1
        end
        goto cont1
      end
      local start = i
      local in_quote = false
      while L_ult(i, n) do
        local c = ((stripped.b[i] + 0x80) & 0xFF) - 0x80
        if c == 34 then
          in_quote = not in_quote
        elseif (not in_quote) and (((c == 32) or (c == 9)) or ((c == 44) and Tinput_Tokenizer_comma_separates(stripped:Clone(), i, pure_csv))) then
          break
        end
        i = i + 1
      end
      tokens[1]:emplace_back(stripped:substr(start, i - start))
      if L_ult(i, n) and ((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 44) then
        i = i + 1
      end
    end
    ::cont1::
  end
  do return Mv_Take(tokens, 1, K_MK50) end
end
function Tinput_Tokenizer_tokenize_views_into(line, tokens)
  local stripped = Tinput_Tokenizer_strip_comment(line:Clone())
  local pure_csv = Tinput_Tokenizer_is_pure_csv_line(stripped:Clone())
  tokens:clear()
  if L_ult(tokens:capacity(), 8) then
    tokens:reserve(8)
  end
  local i = 0
  local n = stripped.n
  while L_ult(i, n) do
    do
      while L_ult(i, n) and (((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 32) or ((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 9)) do
        i = i + 1
      end
      if not L_ult(i, n) then
        break
      end
      if ((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 44) and Tinput_Tokenizer_comma_separates(stripped:Clone(), i, pure_csv) then
        i = i + 1
        goto cont1
      end
      local start = i
      while (L_ult(i, n) and (not (((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 32) or ((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 9)))) and (not (((((stripped.b[i] + 0x80) & 0xFF) - 0x80) == 44) and Tinput_Tokenizer_comma_separates(stripped:Clone(), i, pure_csv))) do
        i = i + 1
      end
      if L_ult(start, i) then
        tokens:push_back(stripped:substr(start, i - start))
