function PluginFactory_is_file_path(str)
  if str.n == 0 then
    do return false end
  end
  if str:find_i_ul(47, 0) ~= 0xFFFFFFFFFFFFFFFF then
    do return true end
  end
  if str:find_i_ul(92, 0) ~= 0xFFFFFFFFFFFFFFFF then
    do return true end
  end
  do return PluginFactory_is_shared_library(str) end
end
function PluginFactory_is_shared_library(filename)
  if L_ult(filename.n, 3) then
    do return false end
  end
  local ends_with = function(s, suffix) return (not L_ult(s.n, suffix.n)) and (s:compare_ul_ul_Str(s.n - suffix.n, suffix.n, suffix) == 0) end
  do return ends_with(filename, NewStr_CPtr(R_Lit(".so"))) end
end
