  if i >= ((((n - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) then
    do return t.a[t.o + ((((n - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)] end
  end
  local x0 = i * delta
  local y = t.a[t.o + i] + (((x - x0) * (t.a[t.o + ((((i + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)] - t.a[t.o + i])) / delta)
  if i < 2 then
