end
function F_xsect_locate_bisect(y, v_table, jLast)
  local j1 = 0
  local j2 = jLast
  if y <= v_table.a[v_table.o + 0] then
    do return 0 end
  end
  if y >= v_table.a[v_table.o + jLast] then
    do return jLast end
  end
  while ((((j2 - j1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) > 1 do
    local j = ((((j1 + j2) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) // 2
    if y >= v_table.a[v_table.o + j] then
