function F_xsect_build_locate_lut(v_L, v_table, jLast)
  local t_1, t_2, t_3
  O_Txsect_LocateLut.MoveFrom(v_L, Txsect_LocateLut__new())
  if ((not (not v_table:get_IsNull())) or (jLast < 2)) or (jLast > 254) then
    do return end
  end
  do
    local j = 1
    while j <= jLast do
      do
        if not (v_table.a[v_table.o + j] >= v_table.a[v_table.o + ((((j - 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000)]) then
          do return end
        end
      end
      j = j + 1
    end
  end
  local span = v_table.a[v_table.o + jLast] - v_table.a[v_table.o + 0]
  if not (span > 0.0) then
    do return end
  end
  v_L.t0 = v_table.a[v_table.o + 0]
  v_L.scale = S_Txsect_LocateLut_kBuckets / span
  v_L.j_last = jLast
  do
    local b = 0
    while b <= S_Txsect_LocateLut_kBuckets do
      do
        local best = 0
        do
          local j_2 = 0
          while j_2 <= jLast do
            do
              if F_xsect_lut_bucket(v_L, v_table.a[v_table.o + j_2]) >= b then
                break
              end
              best = j_2
            end
            j_2 = j_2 + 1
          end
        end
        t_1 = best & 0xFF
        v_L.lo[b] = t_1
        t_2, t_3 = {0}, 1
        t_2[t_3] = t_1
      end
      b = b + 1
    end
  end
end
function F_xsect_locate_lut(y, v_table, jLast, v_L)
  if not (y > v_table.a[v_table.o + 0]) then
    do return 0 end
  end
  if y >= v_table.a[v_table.o + jLast] then
    do return jLast end
  end
  local b = F_xsect_lut_bucket(v_L, y)
  local j1 = v_L.lo[b]
  local j2 = (((v_L.lo[(((b + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000] + 1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000
  if j2 > jLast then
    j2 = jLast
  end
  while ((((j2 - j1) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) > 1 do
    local jm = ((((j1 + j2) + 0x80000000) & 0xFFFFFFFF) - 0x80000000) // 2
    if y >= v_table.a[v_table.o + jm] then
      j1 = jm
    else
      j2 = jm
    end
  end
  do return j1 end
end
