function F_xsect_setParams(xs, v_type, p, ucf)
  local t_1, t_2
  xs.type = v_type
  local shape = v_type
  if shape == 1 then
    do
      local d = p.a[p.o + 0] / ucf
      xs.y_full = d
      xs.w_max = d
      xs.yw_max = d / 2.0
      xs.a_full = ((S_F_xsect_PI / 4.0) * d) * d
      xs.r_full = d / 4.0
      xs.s_full = xs.a_full * L_pow(xs.r_full, 0.6666666666666666)
      xs.s_max = 1.08 * xs.s_full
      do return 0 end
    end
  elseif shape == 24 then
    do
      local d_2 = p.a[p.o + 0] / ucf
      xs.y_full = d_2
      xs.w_max = d_2
      xs.yw_max = d_2 / 2.0
      xs.a_full = ((S_F_xsect_PI / 4.0) * d_2) * d_2
      xs.r_full = d_2 / 4.0
      xs.s_full = xs.a_full * L_pow(xs.r_full, 0.63)
      xs.s_max = 1.06949 * xs.s_full
      xs.r_bot = p.a[p.o + 1]
      do return 0 end
    end
  elseif shape == 3 then
    do
      local y = p.a[p.o + 0] / ucf
      local w = p.a[p.o + 1] / ucf
      xs.y_full = y
      xs.w_max = w
      xs.yw_max = y
      xs.a_full = y * w
      xs.r_full = xs.a_full / (2.0 * (y + w))
      xs.s_full = xs.a_full * L_pow(xs.r_full, 0.6666666666666666)
      local a_max = S_F_xsect_RECT_ALFMAX * xs.a_full
      xs.s_max = a_max * L_pow(O_Txsect_XsectEval.rect_closed_getRofA(F_xsect_hostEval(), xs, a_max), 0.6666666666666666)
      do return 0 end
    end
  elseif shape == 4 then
    do
      local y_2 = p.a[p.o + 0] / ucf
      local w_2 = p.a[p.o + 1] / ucf
      xs.y_full = y_2
      xs.w_max = w_2
      xs.yw_max = y_2
      xs.s_bot = p.a[p.o + 2]
      xs.a_full = y_2 * w_2
      xs.r_full = xs.a_full / (((2.0 - xs.s_bot) * y_2) + w_2)
      xs.s_full = xs.a_full * L_pow(xs.r_full, 0.6666666666666666)
      xs.s_max = xs.s_full
      do return 0 end
    end
  elseif shape == 5 then
    do
      local y_3 = p.a[p.o + 0] / ucf
      local yb = p.a[p.o + 1] / ucf
      local m1 = p.a[p.o + 2]
      local m2 = p.a[p.o + 3]
      xs.y_full = y_3
      xs.yw_max = y_3
      xs.y_bot = yb
      xs.s_bot = (m1 + m2) / 2.0
      xs.r_bot = L_sqrt(1.0 + (m1 * m1)) + L_sqrt(1.0 + (m2 * m2))
      xs.w_max = yb + (y_3 * (m1 + m2))
      xs.a_full = (yb + (xs.s_bot * y_3)) * y_3
      xs.r_full = xs.a_full / (yb + (y_3 * xs.r_bot))
      xs.s_full = xs.a_full * L_pow(xs.r_full, 0.6666666666666666)
      xs.s_max = xs.s_full
      do return 0 end
    end
  elseif shape == 6 then
    do
      local y_4 = p.a[p.o + 0] / ucf
      local w_3 = p.a[p.o + 1] / ucf
      xs.y_full = y_4
      xs.w_max = w_3
      xs.yw_max = y_4
