function F_xsect_shape_rectAofY(y, w_max)
  do return y * w_max end
end
function F_xsect_shape_trapezAofY(y, y_bot, s_bot)
  do return (y_bot + (s_bot * y)) * y end
end
function F_xsect_shape_triangAofY(y, s_bot)
  do return (y * y) * s_bot end
end
function F_xsect_shape_parabAofY(y, r_bot)
  do return ((1.3333333333333333 * r_bot) * y) * L_sqrt(y) end
end
function F_xsect_shape_powerfuncAofY(y, s_bot, r_bot)
  do return r_bot * L_pow(y, s_bot + 1.0) end
end
function F_xsect_shape_rectClosedRofA(a, w_max, a_full)
