              if mode ~= 1 then
                ctx.errors:push_back(F_format_error__i_sv_sv(203, NewStr_CPtr(R_Lit("")), NewStr_CPtr(R_Lit("[FILES] USE OUTFLOWS"))))
                goto cont1
              end
              O_FilePathPair.op_Assign__rstr(files.outflows_path, path)
