                O_FilePathPair.op_Assign__rstr(entry[1].path, path)
                entry[1].datetime = F_input__anon_input_handlers_FilesHandler_cpp_parse_optional_datetime_FilesHandler(tok, 3)
                local fmt_at = (not L_ult(tok.n, 6)) and 5 or 3
                if tok.n == (fmt_at + 1) then
                  local fmt = Tinput_Tokenizer_to_upper(tok.a[fmt_at]:Clone())
                  if fmt:EqLit(R_Lit("LEGACY")) then
                    entry[1].format = 1
                  elseif fmt:EqLit(R_Lit("NATIVE")) then
                    entry[1].format = 2
                  else
                    ctx.warnings_f:push_back(Str_Cat_Str_CPtr(Str_Cat_CPtr_Str(R_Lit("\n  WARNING: Unknown SAVE HOTSTART format '"), tok.a[fmt_at]), R_Lit("' in [FILES] section - LEGACY or NATIVE expected; the default format will be used.")))
                    if ctx.warning_code == 0 then
